/*
Script Name : Generate-DiffBackupScript
Category    : backups-and-recovery
Purpose     : Generate a DIFFERENTIAL backup script for all online user databases.
              @ts in the generated script resolves at execution time so filenames
              include the backup timestamp, not the script generation timestamp.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-generate-backup-and-restore-scripts/)
Requires    : VIEW ANY DATABASE
*/
-- SAFE:ReadOnly
-- IMPACT:Low
SET NOCOUNT ON;

DECLARE @BackupPath    nvarchar(260) = N'D:\SQL-Backups';
DECLARE @Compression   bit           = 1;
DECLARE @StatsInterval int           = 5;

IF RIGHT(@BackupPath, 1) = N'\' SET @BackupPath = LEFT(@BackupPath, LEN(@BackupPath) - 1);

DECLARE @WithClause nvarchar(200) = N'WITH DIFFERENTIAL, ';
SET @WithClause += CASE WHEN @Compression = 1 THEN N'COMPRESSION, ' ELSE N'' END;
SET @WithClause += N'STATS = ' + CAST(@StatsInterval AS nvarchar(3)) + N';';

DECLARE @cmd nvarchar(max) =
    N'-- DIFFERENTIAL backup script - ' + @@SERVERNAME                     + CHAR(13) + CHAR(10) +
    N'-- Path  : ' + @BackupPath                                            + CHAR(13) + CHAR(10) +
    N'-- Requires a prior FULL backup for each database.'                   + CHAR(13) + CHAR(10) +
    N'-- Verify path exists before executing.'                              + CHAR(13) + CHAR(10) +
                                                                              CHAR(13) + CHAR(10) +
    N'DECLARE @ts   varchar(15)  = FORMAT(GETDATE(), ''yyyyMMdd_HHmmss'');' + CHAR(13) + CHAR(10) +
    N'DECLARE @path nvarchar(500);'                                          + CHAR(13) + CHAR(10);

SELECT @cmd +=
    CHAR(13) + CHAR(10) +
    N'SET @path = ''' + @BackupPath + N'\' + d.name + N'_DIFF_'' + @ts + ''.bak'';'    + CHAR(13) + CHAR(10) +
    N'BACKUP DATABASE [' + d.name + N'] TO DISK = @path ' + @WithClause               + CHAR(13) + CHAR(10)
FROM sys.databases AS d
WHERE d.database_id > 4
  AND d.state_desc  = N'ONLINE'
ORDER BY d.name;

IF @cmd IS NULL OR @cmd = N''
    SET @cmd = N'-- No online user databases found.' + CHAR(13) + CHAR(10);

SELECT @cmd AS script;

/*
Script Name : Generate-FullBackupScript
Category    : backups-and-recovery
Purpose     : Generate a FULL backup script for all online user databases.
              @ts in the generated script resolves at execution time so filenames
              include the backup timestamp, not the script generation timestamp.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-generate-backup-and-restore-scripts/)
Requires    : VIEW ANY DATABASE
*/
-- SAFE:ReadOnly
-- IMPACT:Low
SET NOCOUNT ON;

DECLARE @BackupPath    nvarchar(260) = N'D:\SQL-Backups';
DECLARE @Compression   bit           = 1;
DECLARE @StatsInterval int           = 5;

IF RIGHT(@BackupPath, 1) = N'\' SET @BackupPath = LEFT(@BackupPath, LEN(@BackupPath) - 1);

DECLARE @WithClause nvarchar(200) = N'WITH ';
SET @WithClause += CASE WHEN @Compression = 1 THEN N'COMPRESSION, ' ELSE N'' END;
SET @WithClause += N'STATS = ' + CAST(@StatsInterval AS nvarchar(3)) + N';';

DECLARE @cmd nvarchar(max) =
    N'-- FULL backup script - ' + @@SERVERNAME                              + CHAR(13) + CHAR(10) +
    N'-- Path  : ' + @BackupPath                                            + CHAR(13) + CHAR(10) +
    N'-- Verify path exists before executing.'                              + CHAR(13) + CHAR(10) +
                                                                              CHAR(13) + CHAR(10) +
    N'DECLARE @ts   varchar(15)  = FORMAT(GETDATE(), ''yyyyMMdd_HHmmss'');' + CHAR(13) + CHAR(10) +
    N'DECLARE @path nvarchar(500);'                                          + CHAR(13) + CHAR(10);

SELECT @cmd +=
    CHAR(13) + CHAR(10) +
    N'SET @path = ''' + @BackupPath + N'\' + d.name + N'_FULL_'' + @ts + ''.bak'';'    + CHAR(13) + CHAR(10) +
    N'BACKUP DATABASE [' + d.name + N'] TO DISK = @path ' + @WithClause               + CHAR(13) + CHAR(10)
FROM sys.databases AS d
WHERE d.database_id > 4
  AND d.state_desc  = N'ONLINE'
ORDER BY d.name;

IF @cmd IS NULL OR @cmd = N''
    SET @cmd = N'-- No online user databases found.' + CHAR(13) + CHAR(10);

SELECT @cmd AS script;

/*
Script Name : Generate-RestoreScript
Category    : backups-and-recovery
Purpose     : Generate a RESTORE DATABASE script for all online user databases.
              Set @ts to the timestamp of the backup files you want to restore
              before executing. Review WITH MOVE if restoring to a different server.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-generate-backup-and-restore-scripts/)
Requires    : VIEW ANY DATABASE
*/
-- SAFE:ReadOnly
-- IMPACT:Low
SET NOCOUNT ON;

DECLARE @BackupPath    nvarchar(260) = N'D:\SQL-Backups';
DECLARE @WithReplace   bit           = 1;    -- 1 = WITH REPLACE
DECLARE @WithNoRecovery bit          = 0;    -- 1 = WITH NORECOVERY (log chain)
DECLARE @StatsInterval int           = 5;

IF RIGHT(@BackupPath, 1) = N'\' SET @BackupPath = LEFT(@BackupPath, LEN(@BackupPath) - 1);

DECLARE @WithClause nvarchar(200) = N'WITH ';
SET @WithClause += CASE WHEN @WithReplace    = 1 THEN N'REPLACE, '    ELSE N'' END;
SET @WithClause += CASE WHEN @WithNoRecovery = 1 THEN N'NORECOVERY, ' ELSE N'' END;
SET @WithClause += N'STATS = ' + CAST(@StatsInterval AS nvarchar(3)) + N';';

DECLARE @cmd nvarchar(max) =
    N'-- RESTORE script - ' + @@SERVERNAME                                 + CHAR(13) + CHAR(10) +
    N'-- Path  : ' + @BackupPath                                            + CHAR(13) + CHAR(10) +
    N'-- Set @ts to the timestamp of the backup files to restore.'          + CHAR(13) + CHAR(10) +
    N'-- Review WITH MOVE if restoring to a different server or drive.'     + CHAR(13) + CHAR(10) +
                                                                              CHAR(13) + CHAR(10) +
    N'DECLARE @ts   varchar(15)  = ''yyyyMMdd_HHmmss''; -- replace with actual backup timestamp' + CHAR(13) + CHAR(10) +
    N'DECLARE @path nvarchar(500);'                                          + CHAR(13) + CHAR(10);

SELECT @cmd +=
    CHAR(13) + CHAR(10) +
    N'SET @path = ''' + @BackupPath + N'\' + d.name + N'_FULL_'' + @ts + ''.bak'';'    + CHAR(13) + CHAR(10) +
    N'RESTORE DATABASE [' + d.name + N'] FROM DISK = @path ' + @WithClause             + CHAR(13) + CHAR(10)
FROM sys.databases AS d
WHERE d.database_id > 4
  AND d.state_desc  = N'ONLINE'
ORDER BY d.name;

IF @cmd IS NULL OR @cmd = N''
    SET @cmd = N'-- No online user databases found.' + CHAR(13) + CHAR(10);

SELECT @cmd AS script;

/*
Script Name : Generate-TLogBackupScript
Category    : backups-and-recovery
Purpose     : Generate a transaction log backup script for all online user databases
              in FULL or BULK_LOGGED recovery model. SIMPLE recovery databases are
              excluded — log backups are not supported for them.
              @ts in the generated script resolves at execution time so filenames
              include the backup timestamp, not the script generation timestamp.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-generate-backup-and-restore-scripts/)
Requires    : VIEW ANY DATABASE
*/
-- SAFE:ReadOnly
-- IMPACT:Low
SET NOCOUNT ON;

DECLARE @BackupPath    nvarchar(260) = N'D:\SQL-Backups';
DECLARE @Compression   bit           = 1;
DECLARE @StatsInterval int           = 5;

IF RIGHT(@BackupPath, 1) = N'\' SET @BackupPath = LEFT(@BackupPath, LEN(@BackupPath) - 1);

DECLARE @WithClause nvarchar(200) = N'WITH ';
SET @WithClause += CASE WHEN @Compression = 1 THEN N'COMPRESSION, ' ELSE N'' END;
SET @WithClause += N'STATS = ' + CAST(@StatsInterval AS nvarchar(3)) + N';';

DECLARE @cmd nvarchar(max) =
    N'-- TRANSACTION LOG backup script - ' + @@SERVERNAME                  + CHAR(13) + CHAR(10) +
    N'-- Path  : ' + @BackupPath                                            + CHAR(13) + CHAR(10) +
    N'-- FULL and BULK_LOGGED databases only (SIMPLE excluded).'            + CHAR(13) + CHAR(10) +
    N'-- Verify path exists before executing.'                              + CHAR(13) + CHAR(10) +
                                                                              CHAR(13) + CHAR(10) +
    N'DECLARE @ts   varchar(15)  = FORMAT(GETDATE(), ''yyyyMMdd_HHmmss'');' + CHAR(13) + CHAR(10) +
    N'DECLARE @path nvarchar(500);'                                          + CHAR(13) + CHAR(10);

SELECT @cmd +=
    CHAR(13) + CHAR(10) +
    N'SET @path = ''' + @BackupPath + N'\' + d.name + N'_LOG_'' + @ts + ''.trn'';'    + CHAR(13) + CHAR(10) +
    N'BACKUP LOG [' + d.name + N'] TO DISK = @path ' + @WithClause                   + CHAR(13) + CHAR(10)
FROM sys.databases AS d
WHERE d.database_id > 4
  AND d.state_desc        = N'ONLINE'
  AND d.recovery_model_desc IN (N'FULL', N'BULK_LOGGED')
ORDER BY d.name;

IF @cmd IS NULL OR @cmd = N''
    SET @cmd = N'-- No eligible databases found. All online user databases may be in SIMPLE recovery.' + CHAR(13) + CHAR(10);

SELECT @cmd AS script;

/*
Script Name : New-TestDatabases
Category    : dba-lab
Purpose     : Create multiple test databases with randomised names for lab and migration scenarios.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-generate-test-databases/)
Requires    : sysadmin or dbcreator
Notes       : Edit the DECLARE parameter block before running in SSMS.
              For PowerShell-driven creation use powershell\lab\New-MultipleDatabases.ps1.
              For parameterised execution from a script use powershell\lab\Run-CreateTestDatabases.ps1.
*/
-- WARNING: Creates databases — review @Count and @Prefix before running
-- SAFE:CreatesObjects
-- IMPACT:High
SET NOCOUNT ON;

-- Parameters (edit these values before running)
DECLARE @Count      INT     = 10;
DECLARE @Prefix     SYSNAME = N'migdb';
DECLARE @StartIndex INT     = 1;
DECLARE @SuffixLen  INT     = 8;
DECLARE @IndexWidth INT     = 3;
DECLARE @DataSizeMB INT     = 25;
DECLARE @LogSizeMB  INT     = 10;

DECLARE @i   INT = @StartIndex;
DECLARE @End INT = @i + @Count - 1;
DECLARE @Name SYSNAME;
DECLARE @SQL  NVARCHAR(MAX);

WHILE @i <= @End
BEGIN
    SET @Name = @Prefix + '_'
        + RIGHT(REPLICATE('0', @IndexWidth) + CAST(@i AS VARCHAR(20)), @IndexWidth)
        + '_' + LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), @SuffixLen);

    PRINT 'Creating: ' + @Name;

    IF DB_ID(@Name) IS NULL
    BEGIN
        BEGIN TRY
            SET @SQL = N'CREATE DATABASE [' + @Name + N'];';
            EXEC sp_executesql @SQL;

            DECLARE @DataLogical SYSNAME = NULL;
            DECLARE @LogLogical  SYSNAME = NULL;

            SELECT @DataLogical = mf.name FROM sys.master_files mf
            WHERE mf.database_id = DB_ID(@Name) AND mf.type_desc = 'ROWS';

            SELECT @LogLogical = mf.name FROM sys.master_files mf
            WHERE mf.database_id = DB_ID(@Name) AND mf.type_desc = 'LOG';

            IF @DataLogical IS NOT NULL
            BEGIN
                SET @SQL = N'ALTER DATABASE [' + @Name + N'] MODIFY FILE (NAME = N''' + @DataLogical
                    + ''', SIZE = ' + CAST(@DataSizeMB AS NVARCHAR(10)) + N'MB);';
                EXEC sp_executesql @SQL;
            END

            IF @LogLogical IS NOT NULL
            BEGIN
                SET @SQL = N'ALTER DATABASE [' + @Name + N'] MODIFY FILE (NAME = N''' + @LogLogical
                    + ''', SIZE = ' + CAST(@LogSizeMB AS NVARCHAR(10)) + N'MB);';
                EXEC sp_executesql @SQL;
            END
        END TRY
        BEGIN CATCH
            PRINT 'Failed creating ' + @Name + ': ' + ERROR_MESSAGE();
            THROW;
        END CATCH
    END

    SET @i += 1;
END

PRINT 'Done.';

SELECT
    name        AS database_name,
    create_date AS created_at,
    state_desc
FROM sys.databases
WHERE name LIKE @Prefix + N'_%'
ORDER BY create_date DESC;

/*
Script Name : Set-AgentJobState
Category    : maintenance
Purpose     : Save, disable and restore SQL Agent job state as one operation, so a maintenance
              window can quiet an instance and then put it back EXACTLY as it was.
              @Action = N'Report'   lists every job with the change that would be made. Default.
              @Action = N'Save'     snapshots each job's enabled flag into a state table.
              @Action = N'Disable'  disables enabled jobs, honouring the exclusion lists.
              @Action = N'Restore'  re-applies the latest snapshot and proves the result matches.
Author      : Peter Whyte (https://sqldba.blog)
Requires    : SQLAgentOperatorRole or sysadmin. Save also needs CREATE TABLE in @StateDatabase.
Notes       : Disabling is not stopping. A job already running keeps running after it is disabled;
              set @StopRunning = 1 to stop in-flight jobs as well, and understand that stopping a
              job mid-step leaves whatever it was doing half done.
              Restore only touches jobs whose current state DISAGREES with the snapshot, so it
              cannot re-enable something you disabled deliberately after taking the snapshot.
              Jobs created after the snapshot are not in it. Restore leaves them alone and Report
              lists them, because guessing at their intended state is not a rollback.
              Disable refuses to run when no snapshot exists. That is the whole safety property:
              never turn everything off without a recorded way back.
*/
-- WARNING: Disable turns off EVERY Agent job that is not excluded — run Save first
-- SAFE:CreatesObjects
-- IMPACT:High
SET NOCOUNT ON;

-- ── Parameters ────────────────────────────────────────────────────────────────
DECLARE @Action            nvarchar(10)  = N'Report';        -- Report | Save | Disable | Restore
DECLARE @StateDatabase     sysname       = N'DBA_Admin';     -- a utility database, NOT tempdb
DECLARE @ExcludeCategories nvarchar(max) = N'Log Shipping,REPL-Distribution,REPL-LogReader,REPL-Merge,REPL-Snapshot';
DECLARE @ExcludeJobs       nvarchar(max) = N'';              -- comma separated exact job names
DECLARE @StopRunning       bit           = 0;                -- Disable only: stop in-flight jobs
-- ─────────────────────────────────────────────────────────────────────────────

IF @Action NOT IN (N'Report', N'Save', N'Disable', N'Restore')
BEGIN
    RAISERROR('@Action must be Report, Save, Disable or Restore.', 16, 1);
    RETURN;
END

IF DB_ID(@StateDatabase) IS NULL
BEGIN
    RAISERROR('@StateDatabase %s does not exist on this instance.', 16, 1, @StateDatabase);
    RETURN;
END

IF @StateDatabase IN (N'tempdb')
BEGIN
    RAISERROR('@StateDatabase must not be tempdb - the snapshot would not survive a restart.', 16, 1);
    RETURN;
END

DECLARE @sql   nvarchar(max);
DECLARE @db    nvarchar(300) = QUOTENAME(@StateDatabase);
DECLARE @rows  int;

-- Exclusions, resolved once into a temp table so every branch agrees on the same set.
IF OBJECT_ID('tempdb..#excluded') IS NOT NULL DROP TABLE #excluded;
CREATE TABLE #excluded (job_id uniqueidentifier PRIMARY KEY, name sysname, reason nvarchar(60));

INSERT INTO #excluded (job_id, name, reason)
SELECT j.job_id, j.name, N'category ' + c.name
FROM   msdb.dbo.sysjobs j
JOIN   msdb.dbo.syscategories c ON c.category_id = j.category_id
WHERE  LTRIM(RTRIM(c.name)) IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@ExcludeCategories, ',')
                                WHERE LTRIM(RTRIM(value)) <> N'');

INSERT INTO #excluded (job_id, name, reason)
SELECT j.job_id, j.name, N'named in @ExcludeJobs'
FROM   msdb.dbo.sysjobs j
WHERE  LTRIM(RTRIM(j.name)) IN (SELECT LTRIM(RTRIM(value)) FROM STRING_SPLIT(@ExcludeJobs, ',')
                                WHERE LTRIM(RTRIM(value)) <> N'')
AND    NOT EXISTS (SELECT 1 FROM #excluded e WHERE e.job_id = j.job_id);

-- The latest snapshot, lifted out of @StateDatabase into a temp table so the rest of the script
-- is plain readable T-SQL rather than one long dynamic string.
IF OBJECT_ID('tempdb..#snapshot') IS NOT NULL DROP TABLE #snapshot;
CREATE TABLE #snapshot (job_id uniqueidentifier PRIMARY KEY, name sysname, enabled tinyint,
                        CapturedAt datetime2(0));

SET @sql = N'
IF OBJECT_ID(''' + @db + N'.dbo.AgentJobState'') IS NOT NULL
    SELECT job_id, name, enabled, CapturedAt
    FROM   ' + @db + N'.dbo.AgentJobState
    WHERE  CapturedAt = (SELECT MAX(CapturedAt) FROM ' + @db + N'.dbo.AgentJobState);';
INSERT INTO #snapshot (job_id, name, enabled, CapturedAt) EXEC sp_executesql @sql;

DECLARE @snapAt datetime2(0) = (SELECT MAX(CapturedAt) FROM #snapshot);
DECLARE @snapN  int          = (SELECT COUNT(*) FROM #snapshot);

-- ══ Report ═══════════════════════════════════════════════════════════════════
IF @Action = N'Report'
BEGIN
    IF @snapAt IS NULL
        PRINT 'No snapshot found in ' + @StateDatabase + '.dbo.AgentJobState. Run @Action = Save first.';
    ELSE
        PRINT 'Latest snapshot: ' + CONVERT(varchar(19), @snapAt, 120)
              + ' holding ' + CAST(@snapN AS varchar(10)) + ' job(s).';

    SELECT j.name,
           c.name                                      AS category,
           j.enabled                                   AS enabled_now,
           s.enabled                                   AS enabled_in_snapshot,
           e.reason                                    AS excluded_because,
           CASE
               WHEN e.job_id IS NOT NULL              THEN N'excluded, left alone'
               WHEN s.job_id IS NULL                  THEN N'not in snapshot - Restore will not touch it'
               WHEN j.enabled = 1                     THEN N'Disable would turn this off'
               ELSE                                        N'already disabled'
           END                                         AS on_disable,
           CASE
               WHEN s.job_id IS NULL                  THEN N'no snapshot row'
               WHEN s.enabled = j.enabled             THEN N'already matches'
               ELSE N'Restore would set enabled = ' + CAST(s.enabled AS varchar(1))
           END                                         AS on_restore
    FROM   msdb.dbo.sysjobs j
    JOIN   msdb.dbo.syscategories c ON c.category_id = j.category_id
    LEFT   JOIN #snapshot s ON s.job_id = j.job_id
    LEFT   JOIN #excluded e ON e.job_id = j.job_id
    ORDER  BY c.name, j.name;

    SELECT COUNT(*)                                                AS jobs_total,
           SUM(CASE WHEN j.enabled = 1 THEN 1 ELSE 0 END)          AS enabled_now,
           (SELECT COUNT(*) FROM #excluded)                        AS excluded,
           @snapN                                                  AS in_snapshot,
           SUM(CASE WHEN s.job_id IS NULL THEN 1 ELSE 0 END)       AS added_since_snapshot
    FROM   msdb.dbo.sysjobs j
    LEFT   JOIN #snapshot s ON s.job_id = j.job_id;

    -- The statements Disable would run, and the ones that would undo it. Report is a dry run,
    -- so this is the script you review before committing to anything - or save and run by hand
    -- if you would rather drive it yourself than let the tool do it.
    SELECT j.name                                                  AS job,
           N'EXEC msdb.dbo.sp_update_job @job_name = N'
             + QUOTENAME(j.name, '''') + N', @enabled = 0;'        AS disable_statement,
           N'EXEC msdb.dbo.sp_update_job @job_name = N'
             + QUOTENAME(j.name, '''') + N', @enabled = 1;'        AS enable_statement
    FROM   msdb.dbo.sysjobs j
    JOIN   msdb.dbo.syscategories c ON c.category_id = j.category_id
    WHERE  j.enabled = 1
    AND    NOT EXISTS (SELECT 1 FROM #excluded e WHERE e.job_id = j.job_id)
    ORDER  BY c.name, j.name;
    RETURN;
END

-- ══ Save ═════════════════════════════════════════════════════════════════════
IF @Action = N'Save'
BEGIN
    SET @sql = N'
    IF OBJECT_ID(''' + @db + N'.dbo.AgentJobState'') IS NULL
        CREATE TABLE ' + @db + N'.dbo.AgentJobState (
            CapturedAt datetime2(0)      NOT NULL CONSTRAINT DF_AgentJobState_CapturedAt DEFAULT SYSDATETIME(),
            job_id     uniqueidentifier  NOT NULL,
            name       sysname           NOT NULL,
            enabled    tinyint           NOT NULL,
            CONSTRAINT PK_AgentJobState PRIMARY KEY (CapturedAt, job_id)
        );';
    EXEC sp_executesql @sql;

    -- One CapturedAt for the whole snapshot. SYSDATETIME() per row would split a single save
    -- across two timestamps and Restore reads MAX(CapturedAt), so it would then restore a
    -- fraction of the instance and report success.
    DECLARE @now datetime2(0) = SYSDATETIME();
    SET @sql = N'
    INSERT INTO ' + @db + N'.dbo.AgentJobState (CapturedAt, job_id, name, enabled)
    SELECT @now, job_id, name, enabled FROM msdb.dbo.sysjobs;';
    EXEC sp_executesql @sql, N'@now datetime2(0)', @now = @now;
    SET @rows = @@ROWCOUNT;

    PRINT 'Saved ' + CAST(@rows AS varchar(10)) + ' job(s) at ' + CONVERT(varchar(19), @now, 120)
          + ' into ' + @StateDatabase + '.dbo.AgentJobState.';

    SELECT @rows                                                     AS jobs_saved,
           (SELECT COUNT(*) FROM msdb.dbo.sysjobs WHERE enabled = 1) AS were_enabled,
           @now                                                      AS captured_at;
    RETURN;
END

-- ══ Disable ══════════════════════════════════════════════════════════════════
IF @Action = N'Disable'
BEGIN
    -- The safety property. Without a snapshot there is no way back, and "I will remember which
    -- ones were on" is not a rollback plan.
    IF @snapAt IS NULL
    BEGIN
        RAISERROR('No snapshot in %s.dbo.AgentJobState. Run @Action = Save before disabling.',
                  16, 1, @StateDatabase);
        RETURN;
    END

    DECLARE @job sysname, @disabled int = 0;

    -- Record WHAT is about to be turned off, before turning it off. Once the loop has run,
    -- msdb no longer knows which jobs were enabled a moment ago, and a count is not a record.
    -- The DBA gets the list, and an undo statement per job that works even if the state table
    -- is lost, the window runs into the next shift, or somebody restores over the database.
    IF OBJECT_ID('tempdb..#changed') IS NOT NULL DROP TABLE #changed;
    CREATE TABLE #changed (name sysname, category sysname);
    INSERT INTO #changed (name, category)
    SELECT j.name, c.name
    FROM   msdb.dbo.sysjobs j
    JOIN   msdb.dbo.syscategories c ON c.category_id = j.category_id
    WHERE  j.enabled = 1
    AND    NOT EXISTS (SELECT 1 FROM #excluded e WHERE e.job_id = j.job_id);

    DECLARE job_cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT j.name
        FROM   msdb.dbo.sysjobs j
        WHERE  j.enabled = 1
        AND    NOT EXISTS (SELECT 1 FROM #excluded e WHERE e.job_id = j.job_id);

    OPEN job_cur;
    FETCH NEXT FROM job_cur INTO @job;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC msdb.dbo.sp_update_job @job_name = @job, @enabled = 0;
        SET @disabled += 1;
        FETCH NEXT FROM job_cur INTO @job;
    END
    CLOSE job_cur;
    DEALLOCATE job_cur;

    DECLARE @stopped int = 0;
    IF @StopRunning = 1
    BEGIN
        DECLARE stop_cur CURSOR LOCAL FAST_FORWARD FOR
            SELECT j.name
            FROM   msdb.dbo.sysjobactivity ja
            JOIN   msdb.dbo.sysjobs j ON j.job_id = ja.job_id
            WHERE  ja.run_requested_date IS NOT NULL
            AND    ja.stop_execution_date IS NULL
            AND    NOT EXISTS (SELECT 1 FROM #excluded e WHERE e.job_id = j.job_id);
        OPEN stop_cur;
        FETCH NEXT FROM stop_cur INTO @job;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC msdb.dbo.sp_stop_job @job_name = @job;
            SET @stopped += 1;
            FETCH NEXT FROM stop_cur INTO @job;
        END
        CLOSE stop_cur;
        DEALLOCATE stop_cur;
    END

    DECLARE @exCount int = (SELECT COUNT(*) FROM #excluded);
    PRINT 'Disabled ' + CAST(@disabled AS varchar(10)) + ' job(s), stopped '
          + CAST(@stopped AS varchar(10)) + ', excluded '
          + CAST(@exCount AS varchar(10)) + '.';

    SELECT @disabled                                                    AS jobs_disabled,
           @stopped                                                     AS jobs_stopped,
           (SELECT COUNT(*) FROM #excluded)                             AS jobs_excluded,
           (SELECT COUNT(*) FROM msdb.dbo.sysjobs WHERE enabled = 1)    AS still_enabled;

    -- EXACTLY what was turned off, and the statement that puts each one back. Copy the last
    -- column out and you have a rollback script that depends on nothing but msdb - useful when
    -- the window runs into somebody else's shift, or the state database is itself being restored.
    SELECT c.name                                              AS job_disabled,
           c.category,
           N'EXEC msdb.dbo.sp_update_job @job_name = N'
             + QUOTENAME(c.name, '''') + N', @enabled = 1;'    AS undo_statement
    FROM   #changed c
    ORDER  BY c.category, c.name;

    SELECT name AS job_left_alone, reason FROM #excluded ORDER BY name;
    RETURN;
END

-- ══ Restore ══════════════════════════════════════════════════════════════════
IF @Action = N'Restore'
BEGIN
    IF @snapAt IS NULL
    BEGIN
        RAISERROR('No snapshot in %s.dbo.AgentJobState to restore from.', 16, 1, @StateDatabase);
        RETURN;
    END

    DECLARE @rjob sysname, @was tinyint, @changed int = 0;

    -- Same reasoning as Disable: capture the list before the loop changes it, so the DBA gets a
    -- record of what moved rather than a number.
    IF OBJECT_ID('tempdb..#restored') IS NOT NULL DROP TABLE #restored;
    CREATE TABLE #restored (name sysname, was tinyint, is_now tinyint);
    INSERT INTO #restored (name, was, is_now)
    SELECT s.name, j.enabled, s.enabled
    FROM   #snapshot s
    JOIN   msdb.dbo.sysjobs j ON j.job_id = s.job_id
    WHERE  j.enabled <> s.enabled;

    -- Only where the CURRENT state disagrees with the snapshot. Re-applying every row would
    -- undo anything you changed on purpose after taking it, and would report those as restored.
    DECLARE res_cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.name, s.enabled
        FROM   #snapshot s
        JOIN   msdb.dbo.sysjobs j ON j.job_id = s.job_id
        WHERE  j.enabled <> s.enabled;

    OPEN res_cur;
    FETCH NEXT FROM res_cur INTO @rjob, @was;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC msdb.dbo.sp_update_job @job_name = @rjob, @enabled = @was;
        SET @changed += 1;
        FETCH NEXT FROM res_cur INTO @rjob, @was;
    END
    CLOSE res_cur;
    DEALLOCATE res_cur;

    PRINT 'Restored ' + CAST(@changed AS varchar(10)) + ' job(s) to the snapshot taken '
          + CONVERT(varchar(19), @snapAt, 120) + '.';

    -- What actually moved, and in which direction.
    SELECT name        AS job_restored,
           was         AS state_before_restore,
           is_now      AS state_after_restore
    FROM   #restored
    ORDER  BY name;

    -- The proof. Anything returned here is a job that did NOT come back as recorded.
    SELECT s.name, s.enabled AS was, j.enabled AS [now]
    FROM   #snapshot s
    JOIN   msdb.dbo.sysjobs j ON j.job_id = s.job_id
    WHERE  j.enabled <> s.enabled;

    -- Jobs created since the snapshot. Not an error, but they are yours to decide on.
    SELECT j.name AS created_since_snapshot, j.enabled
    FROM   msdb.dbo.sysjobs j
    WHERE  NOT EXISTS (SELECT 1 FROM #snapshot s WHERE s.job_id = j.job_id)
    ORDER  BY j.name;

    SELECT @changed AS jobs_changed, @snapAt AS restored_from, @snapN AS jobs_in_snapshot;
    RETURN;
END

/*
Script Name : Get-LinkedServerConnectivity
Category    : monitoring
Purpose     : Inventories all linked servers and tests each one for connectivity using sp_testlinkedserver.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-get-linked-servers/)
Requires    : sysadmin or ALTER ANY LINKED SERVER
*/
-- SAFE:ReadOnly
-- IMPACT:Low
SET NOCOUNT ON;

/* Note: sys.linked_servers was removed in SQL Server 2025 — use sys.servers WHERE is_linked = 1 */

IF OBJECT_ID('tempdb..#LSResults') IS NOT NULL DROP TABLE #LSResults;
CREATE TABLE #LSResults (
    linked_server_name NVARCHAR(128) NOT NULL,
    product NVARCHAR(128),
    provider NVARCHAR(128),
    data_source NVARCHAR(4000),
    is_rpc_out_enabled BIT,
    is_remote_login_enabled BIT,
    modify_date DATETIME,
    connectivity VARCHAR(15) NOT NULL DEFAULT 'UNTESTED',
    error_detail NVARCHAR(2000)
);

INSERT INTO #LSResults (linked_server_name, product, provider, data_source,
                        is_rpc_out_enabled, is_remote_login_enabled, modify_date)
SELECT
    name,
    product,
    provider,
    data_source,
    is_rpc_out_enabled,
    is_remote_login_enabled,
    modify_date
FROM sys.servers
WHERE is_linked = 1;

/* ── Test connectivity for each linked server ────────────────────────────── */
DECLARE @ls NVARCHAR(128);
DECLARE @err NVARCHAR(2000);

DECLARE ls_cur CURSOR FAST_FORWARD FOR
    SELECT linked_server_name FROM #LSResults ORDER BY linked_server_name;

OPEN ls_cur; FETCH NEXT FROM ls_cur INTO @ls;
WHILE @@FETCH_STATUS = 0
BEGIN
    BEGIN TRY
        EXEC sp_testlinkedserver @ls;
        UPDATE #LSResults SET connectivity = 'REACHABLE' WHERE linked_server_name = @ls;
    END TRY
    BEGIN CATCH
        SET @err = LEFT(ERROR_MESSAGE(), 2000);
        UPDATE #LSResults
        SET connectivity = 'UNREACHABLE', error_detail = @err
        WHERE linked_server_name = @ls;
    END CATCH;
    FETCH NEXT FROM ls_cur INTO @ls;
END;
CLOSE ls_cur; DEALLOCATE ls_cur;

SELECT
    linked_server_name,
    product,
    provider,
    data_source,
    connectivity,
    is_rpc_out_enabled,
    is_remote_login_enabled,
    modify_date,
    error_detail
FROM #LSResults
ORDER BY CASE connectivity WHEN 'UNREACHABLE' THEN 1 WHEN 'REACHABLE' THEN 2 ELSE 3 END,
         linked_server_name;

DROP TABLE #LSResults;

/*
Script Name : Create-DecommissionAuditSession
Category    : traces
Purpose     : Creates an Extended Events session that captures all T-SQL batch, RPC, successful login, and failed login activity
              against a specific database (or all databases). Use before decommissioning or retiring a database to prove zero usage.
              Run for at least 5–7 business days to catch batch jobs and end-of-period activity.
Author      : Peter Whyte (https://sqldba.blog/dba-scripts-create-decommission-audit-session/)
Requires    : ALTER ANY EVENT SESSION, VIEW SERVER STATE
*/
-- SAFE:CreatesObjects
-- IMPACT:Low
SET NOCOUNT ON;

/* ── Configuration — edit these before running ───────────────────────────── */
DECLARE @SessionName NVARCHAR(128) = N'DecommissionAudit';
DECLARE @DatabaseName NVARCHAR(128) = N''; /* target database; blank = all databases (high volume on busy servers) */
DECLARE @TraceFolder NVARCHAR(260) = N'D:\SQLTrace';
    /* Folder must exist; SQL Server service account needs write access. */
DECLARE @MaxFileMB INT = 100; /* max size per .xel file in MB */
DECLARE @MaxFiles INT = 14; /* number of rollover files; oldest is overwritten first */
DECLARE @RetentionDays INT = 7;
    /* SQL Server 2025+ (v17+) only: session auto-stops after this many days.
       On older versions this has no effect — the session runs until you stop
       it manually. Run for at least 5–7 business days to catch batch jobs
       and end-of-period processing. */
/* ─────────────────────────────────────────────────────────────────────────── */

DECLARE @ProductMajorVersion INT = CAST(SERVERPROPERTY('ProductMajorVersion') AS INT);

/* Escape any single-quotes in the path so the dynamic SQL string stays valid */
DECLARE @FilePathRaw NVARCHAR(260) = @TraceFolder + N'\' + @SessionName + N'.xel';
DECLARE @FilePathEsc NVARCHAR(522) = REPLACE(@FilePathRaw, N'''', N'''''');

/* Database filter — applied to batch and RPC events; login events are server-level */
DECLARE @dbFilter NVARCHAR(500) = N'';
IF @DatabaseName <> N''
    SET @dbFilter = N'WHERE sqlserver.database_name = N''' + REPLACE(@DatabaseName, N'''', N'''''') + N'''';

DECLARE @sql NVARCHAR(MAX);

IF EXISTS (SELECT 1 FROM sys.server_event_sessions WHERE name = @SessionName)
BEGIN
    /* STOP only if it is actually running - ALTER ... STATE = STOP on an already
       stopped session raises Msg 25704 and prints a red error over a successful run */
    IF EXISTS (SELECT 1 FROM sys.dm_xe_sessions WHERE name = @SessionName)
    BEGIN
        SET @sql = N'ALTER EVENT SESSION ' + QUOTENAME(@SessionName) + N' ON SERVER STATE = STOP;';
        EXEC sp_executesql @sql;
    END;
    SET @sql = N'DROP EVENT SESSION ' + QUOTENAME(@SessionName) + N' ON SERVER;';
    EXEC sp_executesql @sql;
    PRINT 'Existing session ' + @SessionName + ' stopped and dropped.';
END;

/* Build WITH clause — MAX_DURATION is SQL Server 2025+ (v17+) only */
DECLARE @WithClause NVARCHAR(500) =
    N'WITH (
    MAX_DISPATCH_LATENCY = 15 SECONDS,
    STARTUP_STATE = ON';
IF @ProductMajorVersion >= 17
    SET @WithClause = @WithClause
        + N',
    MAX_DURATION = ' + CAST(@RetentionDays AS NVARCHAR(5)) + N' DAYS';
SET @WithClause = @WithClause + N'
)';

SET @sql = N'
CREATE EVENT SESSION ' + QUOTENAME(@SessionName) + N' ON SERVER
ADD EVENT sqlserver.sql_batch_completed (
    ACTION (
        sqlserver.client_hostname,
        sqlserver.client_app_name,
        sqlserver.username,
        sqlserver.nt_username,
        sqlserver.server_principal_name,
        sqlserver.database_name
    )
    ' + @dbFilter + N'
),
ADD EVENT sqlserver.rpc_completed (
    ACTION (
        sqlserver.client_hostname,
        sqlserver.client_app_name,
        sqlserver.username,
        sqlserver.nt_username,
        sqlserver.server_principal_name,
        sqlserver.database_name
    )
    ' + @dbFilter + N'
),
ADD EVENT sqlserver.login (
    ACTION (
        sqlserver.client_hostname,
        sqlserver.client_app_name,
        sqlserver.username,
        sqlserver.nt_username,
        sqlserver.server_principal_name,
        sqlserver.database_name
    )
    WHERE sqlserver.is_system = 0
),
ADD EVENT sqlserver.error_reported (
    /* error 18456 = Login failed; state field indicates the specific reason */
    ACTION (
        sqlserver.client_hostname,
        sqlserver.client_app_name,
        sqlserver.username,
        sqlserver.nt_username,
        sqlserver.server_principal_name,
        sqlserver.database_name
    )
    WHERE error_number = 18456
)
ADD TARGET package0.event_file (
    SET filename = N''' + @FilePathEsc + N''',
        max_file_size = ' + CAST(@MaxFileMB AS NVARCHAR(10)) + N',
        max_rollover_files = ' + CAST(@MaxFiles  AS NVARCHAR(10)) + N'
)
' + @WithClause + N';
ALTER EVENT SESSION ' + QUOTENAME(@SessionName) + N' ON SERVER STATE = START;';

BEGIN TRY
    EXEC sp_executesql @sql;

    SELECT
        @SessionName AS session_name,
        @FilePathRaw AS output_file,
        NULLIF(@DatabaseName, N'') AS database_filter,
        @MaxFileMB AS max_file_mb,
        @MaxFiles AS max_files,
        @MaxFileMB * @MaxFiles AS total_capacity_mb,
        CASE WHEN @ProductMajorVersion >= 17
             THEN CAST(@RetentionDays AS VARCHAR(5)) + ' days (MAX_DURATION)'
             ELSE 'manual stop (pre-2025)'
        END AS session_lifetime,
        'RUNNING' AS status,
        'IF EXISTS (SELECT 1 FROM sys.dm_xe_sessions WHERE name = ' + QUOTENAME(@SessionName, '''') + ') ALTER EVENT SESSION ' + QUOTENAME(@SessionName) + ' ON SERVER STATE = STOP; DROP EVENT SESSION ' + QUOTENAME(@SessionName) + ' ON SERVER;' AS remove_cmd;

    PRINT 'Session ' + @SessionName + ' created and started.';
    PRINT 'Output file : ' + @FilePathRaw;
    PRINT 'View data   : SSMS > Management > Extended Events > Sessions > ' + @SessionName + ' > right-click target > View Target Data';
END TRY
BEGIN CATCH
    PRINT 'ERROR creating session: ' + ERROR_MESSAGE();
    THROW;
END CATCH;

