﻿<#
.SYNOPSIS
Shows the largest folders on a drive, sorted by size.

.NOTES
ScriptType   : runner
TargetScope  : single server
RiskLevel    : SAFE
Purpose      : Find the largest folders on a drive to identify disk space candidates for cleanup.

.DESCRIPTION
Scans a drive letter (default: C:) and reports the biggest folders by total size.
Useful for quickly finding where disk space is being used.

.PARAMETER DriveLetter
Drive to inspect. Defaults to 'C'.

.PARAMETER Top
Number of folders to show. Defaults to 10.

.EXAMPLE
powershell -ExecutionPolicy Bypass -File .\powershell\inventory\Get-LargestFolders.ps1

.EXAMPLE
powershell -ExecutionPolicy Bypass -File .\powershell\inventory\Get-LargestFolders.ps1 -DriveLetter D -Top 20
#>

param(
    [string]$DriveLetter = 'C',
    [int]$Top = 10,
    [switch]$IncludeSystemFolders,
    [switch]$IncludeLargestFiles
)
$ErrorActionPreference = 'Stop'

$drive = "$DriveLetter`:\"

if (-not (Test-Path $drive)) {
    throw "Drive not found: $drive"
}

Write-Host "Scanning $drive for likely cleanup targets..." -ForegroundColor Cyan
Write-Host "(This may take a moment while size data is collected.)" -ForegroundColor DarkYellow

$candidateFolders = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

if ($IncludeSystemFolders) {
    Get-ChildItem -Path $drive -Directory -Force -ErrorAction SilentlyContinue |
        ForEach-Object { [void]$candidateFolders.Add($_.FullName) }
}
else {
    foreach ($p in @('ProgramData', 'Temp', 'tmp', 'Windows\Temp')) {
        $full = Join-Path $drive $p
        if (Test-Path -LiteralPath $full -ErrorAction SilentlyContinue) {
            [void]$candidateFolders.Add($full)
        }
    }
}

if (Test-Path (Join-Path $drive 'Users')) {
    Get-ChildItem -Path (Join-Path $drive 'Users') -Directory -Force -ErrorAction SilentlyContinue |
        ForEach-Object {
            foreach ($sub in @('Downloads', 'AppData', 'OneDrive')) {
                $p = Join-Path $_.FullName $sub
                try {
                    if (Test-Path -LiteralPath $p -ErrorAction Stop) {
                        [void]$candidateFolders.Add($p)
                    }
                }
                catch { $null = $_ }
            }
        }
}

function Get-FolderSizeGB([string]$Path) {
    try {
        $sum = 0
        $items = Get-ChildItem -LiteralPath $Path -Recurse -File -Force -ErrorAction SilentlyContinue |
            Where-Object { -not $_.Attributes.HasFlag([System.IO.FileAttributes]::ReparsePoint) }

        if ($items) {
            $sum = ($items | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum
        }

        return [math]::Round(($sum / 1GB), 2)
    }
    catch {
        return 0
    }
}

$allCandidates = $candidateFolders | Sort-Object -Unique
$total = $allCandidates.Count
$processed = 0

$folders = foreach ($path in $allCandidates) {
    $processed++
    $pct = [math]::Round(($processed / $total) * 100, 0)
    Write-Progress -Activity "Scanning folders" -Status "Processing $processed of $total" -PercentComplete $pct

    try {
        $sizeGB = Get-FolderSizeGB -Path $path
        [PSCustomObject]@{
            Folder = $path
            SizeGB = $sizeGB
            Priority = if ($path -match '\\Users\\.*\\(Downloads|AppData|OneDrive)$' -or $path -match '\\(Temp|tmp)\\?$' -or $path -match '\\Users\\[^\\]+$') { 'Yes' } else { 'No' }
        }
    }
    catch {
        [PSCustomObject]@{
            Folder = $path
            SizeGB = 0
            Priority = 'No'
        }
    }
}

$folders = $folders |
    Where-Object { ($_.Priority -eq 'Yes' -and $_.SizeGB -ge 0.05) -or $_.SizeGB -ge 1 } |
    Sort-Object -Property Priority, SizeGB -Descending |
    Select-Object -First $Top

Write-Progress -Activity "Scanning folders" -Completed

if (-not $folders) {
    Write-Host "No folders found to measure on $drive." -ForegroundColor Yellow
    return
}

$disk = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='${DriveLetter}:'"
$freeGB = [math]::Round(($disk.FreeSpace / 1GB), 2)
$totalGB = [math]::Round(($disk.Size / 1GB), 2)
$usedPct = if ($disk.Size -gt 0) { [math]::Round((($disk.Size - $disk.FreeSpace) / $disk.Size) * 100, 1) } else { 0 }

$topTotalGB = ($folders | Measure-Object -Property SizeGB -Sum).Sum
$topPctOfDrive = if ($totalGB -gt 0) { [math]::Round(($topTotalGB / $totalGB) * 100, 1) } else { 0 }

Write-Host "Top $Top likely cleanup targets on $drive" -ForegroundColor Green
Write-Host ("Drive usage: {0} GB used of {1} GB total ({2}% used)" -f ([math]::Round(($totalGB - $freeGB), 2)), $totalGB, $usedPct) -ForegroundColor Yellow
Write-Host ("Top candidates account for {0:N2} GB ({1}% of the drive)" -f $topTotalGB, $topPctOfDrive) -ForegroundColor Yellow
Write-Host ("=" * 100) -ForegroundColor DarkCyan
$folders | Format-Table -AutoSize -Property @{Label='Folder';Expression={$_.Folder}}, @{Label='Size GB';Expression={'{0:N2}' -f $_.SizeGB}}, @{Label='Share %';Expression={if ($topTotalGB -gt 0) { [math]::Round(($_.SizeGB / $topTotalGB) * 100, 1) } else { 0 }}} | Out-String | Write-Host

$subfolderSummary = @()
foreach ($item in $folders | Where-Object { $_.SizeGB -ge 5 } | Select-Object -First 3) {
    $subs = Get-ChildItem -LiteralPath $item.Folder -Directory -Force -ErrorAction SilentlyContinue |
        ForEach-Object {
            $sizeGB = Get-FolderSizeGB -Path $_.FullName
            [PSCustomObject]@{
                Parent = $item.Folder
                SubFolder = $_.FullName
                SizeGB = $sizeGB
            }
        } |
        Where-Object { $_.SizeGB -ge 0.1 } |
        Sort-Object -Property SizeGB -Descending |
        Select-Object -First 5

    if ($subs) { $subfolderSummary += $subs }
}

if ($subfolderSummary.Count -gt 0) {
    Write-Host "`nTop subfolders driving the largest candidates:" -ForegroundColor Yellow
    $subfolderSummary |
        Format-Table -AutoSize -Property Parent, SubFolder, @{Label='Size GB';Expression={'{0:N2}' -f $_.SizeGB}} | Out-String | Write-Host
}

if ($IncludeLargestFiles) {
    Write-Host "Largest files on the same drive:" -ForegroundColor Yellow
    Get-ChildItem -Path $drive -File -Recurse -Force -ErrorAction SilentlyContinue |
        Sort-Object -Property Length -Descending |
        Select-Object -First 5 |
        Format-Table -AutoSize -Property FullName, @{Label='Size GB';Expression={'{0:N2}' -f ($_.Length / 1GB)}} | Out-String | Write-Host
}

Write-Host ("=" * 100) -ForegroundColor DarkCyan

﻿<#
.SYNOPSIS
Apply sp_configure settings to an existing SQL Server instance.

.DESCRIPTION
Applies recommended or custom SQL Server configuration settings.
Shows a before/after comparison for every setting changed.
All changes use RECONFIGURE WITH OVERRIDE and are logged.

.PARAMETER ServerInstance
Target SQL Server instance. Default: . (local default instance).

.PARAMETER MaxMemoryGB
Max server memory in GB. Auto-calculated as (TotalRAM - 4 GB) if not supplied.

.PARAMETER MaxDOP
Max degree of parallelism. Auto-calculated from logical CPU count if not supplied.

.PARAMETER CostThreshold
Cost threshold for parallelism. Default: 50.

.PARAMETER BackupCompression
Enable backup compression by default. 1=on, 0=off. Default: 1.

.PARAMETER OptimizeAdHoc
Optimize for ad hoc workloads (plan cache). 1=on, 0=off. Default: 1.

.PARAMETER RemoteAdminConnections
Enable Dedicated Admin Connection (DAC). 1=on, 0=off. Default: 1.

.PARAMETER ApplyRecommended
Apply all recommended settings using hardware auto-detection. Ignores individual params.

.EXAMPLE
# Apply all recommended settings to local instance
.\admin\installation\configure-sql.ps1 -ApplyRecommended

# Apply to remote instance with specific values
.\admin\installation\configure-sql.ps1 -ServerInstance PROD01 -MaxMemoryGB 28 -MaxDOP 4

# Review current settings without changing anything (use -WhatIf)
.\admin\installation\configure-sql.ps1 -ApplyRecommended -WhatIf

.NOTES
RiskLevel   : HIGH IMPACT - runs sp_configure and RECONFIGURE against a live instance; some settings take effect immediately
#>
param(
    [string]$ServerInstance         = '.',
    [int]$MaxMemoryGB               = 0,
    [int]$MaxDOP                    = 0,
    [int]$CostThreshold             = 50,
    [ValidateSet(0,1)][int]$BackupCompression      = 1,
    [ValidateSet(0,1)][int]$OptimizeAdHoc          = 1,
    [ValidateSet(0,1)][int]$RemoteAdminConnections = 1,
    [switch]$ApplyRecommended,
    [switch]$WhatIf
)

$ErrorActionPreference = 'Stop'

if ($ServerInstance -eq '.' -and $env:DBASCRIPTS_SERVER) { $ServerInstance = $env:DBASCRIPTS_SERVER }

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$logDir   = Join-Path $repoRoot 'output-files\installation'
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$ts       = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile  = Join-Path $logDir "configure-$($ServerInstance -replace '[\\/:*]','-')-$ts.log"

function Write-DbaLog {
    param([string]$Msg, [string]$Color = 'White')
    $line = "[$(Get-Date -Format 'HH:mm:ss')] $Msg"
    Write-Host $line -ForegroundColor $Color
    Add-Content -Path $logFile -Value $line
}

# ── Hardware-based recommendations ───────────────────────────────────────────
if ($ApplyRecommended -or $MaxMemoryGB -eq 0 -or $MaxDOP -eq 0) {
    $totalRAMGB  = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
    $logicalCPUs = (Get-CimInstance Win32_ComputerSystem).NumberOfLogicalProcessors
    if ($MaxMemoryGB -eq 0) { $MaxMemoryGB = [math]::Max(1, [math]::Floor($totalRAMGB - 4)) }
    if ($MaxDOP -eq 0)      { $MaxDOP      = [math]::Min($logicalCPUs, 8) }
}

# Settings to apply: name → [sp_configure key, desired value, description]
$settings = [ordered]@{
    'max server memory (MB)'        = @{ Value = $MaxMemoryGB * 1024; Label = "Max server memory ($MaxMemoryGB GB)" }
    'max degree of parallelism'     = @{ Value = $MaxDOP;             Label = "MaxDOP ($MaxDOP)" }
    'cost threshold for parallelism'= @{ Value = $CostThreshold;      Label = "Cost threshold for parallelism ($CostThreshold)" }
    'backup compression default'    = @{ Value = $BackupCompression;   Label = "Backup compression ($(if ($BackupCompression) {'on'} else {'off'}))" }
    'optimize for ad hoc workloads' = @{ Value = $OptimizeAdHoc;       Label = "Optimize for ad hoc workloads ($(if ($OptimizeAdHoc) {'on'} else {'off'}))" }
    'remote admin connections'      = @{ Value = $RemoteAdminConnections; Label = "Remote admin connections / DAC ($(if ($RemoteAdminConnections) {'on'} else {'off'}))" }
}

Write-DbaLog "SQL Server configuration - $ServerInstance" 'Cyan'
Write-DbaLog "Log: $logFile" 'DarkGray'

# ── Read current settings ─────────────────────────────────────────────────────
$currentSql = "SELECT name, value_in_use FROM sys.configurations WHERE name IN ($( ($settings.Keys | ForEach-Object {"'$_'"}) -join ',' ))"
try {
    $current = Invoke-Sqlcmd -ServerInstance $ServerInstance -Query $currentSql `
                   -TrustServerCertificate -ErrorAction Stop
} catch {
    Write-DbaLog "ERROR: Cannot connect to $ServerInstance - $($_.Exception.Message)" 'Red'; exit 1
}

$currentMap = @{}
foreach ($row in $current) { $currentMap[$row.name] = $row.value_in_use }

# ── Show planned changes ──────────────────────────────────────────────────────
Write-DbaLog ''
Write-DbaLog 'Planned configuration changes:' 'Cyan'
Write-DbaLog ("{0,-42} {1,12}  →  {2}" -f 'Setting', 'Current', 'New') 'DarkGray'
Write-DbaLog ([string]::new('-', 72)) 'DarkGray'

$changed = @{}
foreach ($key in $settings.Keys) {
    $desired = $settings[$key].Value
    $current = if ($currentMap.ContainsKey($key)) { $currentMap[$key] } else { '?' }
    $isSame  = "$current" -eq "$desired"
    $color   = if ($isSame) {'DarkGray'} else {'White'}
    $note    = if ($isSame) {'(no change)'} else {''}
    Write-DbaLog ("{0,-42} {1,12}  →  {2}  {3}" -f $key, $current, $desired, $note) $color
    if (-not $isSame) { $changed[$key] = $settings[$key].Value }
}

if ($changed.Count -eq 0) {
    Write-DbaLog ''
    Write-DbaLog 'All settings already at desired values. Nothing to apply.' 'Green'
    return
}

if ($WhatIf) {
    Write-DbaLog ''
    Write-DbaLog "WhatIf: $($changed.Count) setting(s) would be applied." 'Yellow'
    return
}

# ── Apply ─────────────────────────────────────────────────────────────────────
Write-DbaLog ''
Write-DbaLog "Applying $($changed.Count) setting(s)..." 'Cyan'

$sql = "EXEC sys.sp_configure 'show advanced options', 1; RECONFIGURE WITH OVERRIDE;`n"
foreach ($key in $changed.Keys) {
    $sql += "EXEC sys.sp_configure '$key', $($changed[$key]);`n"
}
$sql += "RECONFIGURE WITH OVERRIDE;"

try {
    Invoke-Sqlcmd -ServerInstance $ServerInstance -Query $sql `
        -TrustServerCertificate -QueryTimeout 30 -ErrorAction Stop
    Write-DbaLog 'Settings applied successfully.' 'Green'
} catch {
    Write-DbaLog "ERROR applying settings: $($_.Exception.Message)" 'Red'; exit 1
}

# ── Verify ────────────────────────────────────────────────────────────────────
$verify = Invoke-Sqlcmd -ServerInstance $ServerInstance -Query $currentSql `
              -TrustServerCertificate -ErrorAction SilentlyContinue
$verifyMap = @{}
foreach ($row in $verify) { $verifyMap[$row.name] = $row.value_in_use }

Write-DbaLog ''
Write-DbaLog 'Verification:' 'Cyan'
foreach ($key in $changed.Keys) {
    $expected = $changed[$key]
    $actual   = $verifyMap[$key]
    $ok       = "$actual" -eq "$expected"
    $color    = if ($ok) {'Green'} else {'Red'}
    Write-DbaLog ("  {0,-42} {1}  {2}" -f $key, $actual, $(if ($ok) {'OK'} else {"MISMATCH (expected $expected)"})) $color
}

Write-DbaLog ''
Write-DbaLog 'Configuration complete.' 'Green'

﻿<#
.SYNOPSIS
Generate a summary report from SQL Server installation and configuration logs.

.DESCRIPTION
Reads install/configure/patch logs from output-files\ and produces a readable
summary showing what was installed, when, against which instances, and the outcome.

.PARAMETER LogRoot
Root folder to scan for logs. Default: output-files\ in the repo root.

.PARAMETER OutputFormat
'Table' (default) — writes to terminal. 'Csv' — also saves a CSV.

.EXAMPLE
.\admin\installation\generate-install-report.ps1
.\admin\installation\generate-install-report.ps1 -OutputFormat Csv

.NOTES
RiskLevel   : SAFE - reads setup logs; writes only a local report file
#>
param(
    [string]$LogRoot      = '',
    [ValidateSet('Table','Csv')]
    [string]$OutputFormat = 'Table'
)

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
if (-not $LogRoot) { $LogRoot = Join-Path $repoRoot 'output-files' }

$logDirs = @(
    @{ Dir = Join-Path $LogRoot 'installation'; Type = 'Install'  },
    @{ Dir = Join-Path $LogRoot 'patches';      Type = 'Patch'    }
)

$events = [System.Collections.Generic.List[PSObject]]::new()

foreach ($ld in $logDirs) {
    if (-not (Test-Path $ld.Dir)) { continue }
    $logs = Get-ChildItem -Path $ld.Dir -Filter '*.log' -File |
                Where-Object { $_.Name -notlike '*.stdout' -and $_.Name -notlike '*.stderr' } |
                Sort-Object LastWriteTime -Descending

    foreach ($log in $logs) {
        $lines   = Get-Content $log.FullName -ErrorAction SilentlyContinue
        $outcome = 'Unknown'
        $target  = ''

        foreach ($line in $lines) {
            if ($line -match 'succeeded|complete|Done') { $outcome = 'Success' }
            if ($line -match 'FAILED|failed|ERROR:')    { $outcome = 'Failed'  }
            if ($line -match 'cancelled')               { $outcome = 'Cancelled' }
            if ($line -match 'Server\s*:\s*(.+)')       { $target  = $Matches[1].Trim() }
            if ($line -match 'Instance\s*:\s*(.+)')     { $target  = $Matches[1].Trim() }
        }

        $events.Add([PSCustomObject]@{
            Timestamp  = $log.LastWriteTime.ToString('yyyy-MM-dd HH:mm')
            Type       = $ld.Type
            Target     = if ($target) { $target } else { '-' }
            Outcome    = $outcome
            LogFile    = $log.Name
        })
    }
}

Write-Host ""
Write-Host "  SQL Server Installation & Patch Report" -ForegroundColor Cyan
Write-Host ("  " + [string]::new('-', 70)) -ForegroundColor DarkCyan
Write-Host ""

if ($events.Count -eq 0) {
    Write-Host "  No install or patch logs found under: $LogRoot" -ForegroundColor Yellow
    Write-Host "  Run install-sql.ps1 or install-cu.ps1 first." -ForegroundColor DarkGray
    Write-Host ""
    return
}

foreach ($e in $events) {
    $outcomeColor = switch ($e.Outcome) {
        'Success'   { 'Green'  }
        'Failed'    { 'Red'    }
        'Cancelled' { 'Yellow' }
        default     { 'Gray'   }
    }
    Write-Host ("  {0}  {1,-10} {2,-24} " -f $e.Timestamp, $e.Type, $e.Target) -NoNewline
    Write-Host $e.Outcome -ForegroundColor $outcomeColor
}

Write-Host ""
Write-Host "  Total events: $($events.Count)" -ForegroundColor DarkGray

if ($OutputFormat -eq 'Csv') {
    $outDir  = Join-Path $LogRoot 'installation'
    New-Item -ItemType Directory -Path $outDir -Force | Out-Null
    $csvPath = Join-Path $outDir "install-report-$(Get-Date -Format 'yyyyMMdd-HHmmss').csv"
    $events | Export-Csv -Path $csvPath -NoTypeInformation
    Write-Host "  CSV: $csvPath" -ForegroundColor DarkGray
}
Write-Host ""

﻿<#
.SYNOPSIS
Run pre-installation checks before deploying SQL Server.

.DESCRIPTION
Validates the machine is ready for SQL Server installation. Reports PASS / WARN / FAIL
for each check. Does not make any changes to the system.

.PARAMETER InstanceName
Target instance name to check for existing installs. Default: MSSQLSERVER.

.PARAMETER InstallDir
Planned SQL Server binary directory — checked for disk space.

.PARAMETER DataDir
Planned data directory — checked for disk space.

.PARAMETER LogDir
Planned log directory — checked for disk space.

.PARAMETER SqlVersion
SQL Server version being installed (2016|2017|2019|2022). Default: 2022.

.EXAMPLE
.\admin\installation\pre-install-check.ps1
.\admin\installation\pre-install-check.ps1 -SqlVersion 2019 -DataDir D:\SQLData

.NOTES
RiskLevel   : SAFE - reads only; writes nothing to the machine or the instance
#>
param(
    [string]$InstanceName = 'MSSQLSERVER',
    [string]$InstallDir   = 'C:\Program Files\Microsoft SQL Server',
    [string]$DataDir      = 'C:\SQLData',
    [string]$LogDir       = 'C:\SQLLogs',
    [ValidateSet('2016','2017','2019','2022')]
    [string]$SqlVersion   = '2022'
)

$ErrorActionPreference = 'SilentlyContinue'

$pass  = 0; $warn = 0; $fail = 0
$results = [System.Collections.Generic.List[PSObject]]::new()

function Add-Check {
    param([string]$Category, [string]$Check, [string]$Status, [string]$Detail)
    $color = switch ($Status) { 'PASS'{'Green'} 'WARN'{'Yellow'} 'FAIL'{'Red'} default{'White'} }
    $results.Add([PSCustomObject]@{ Category=$Category; Check=$Check; Status=$Status; Detail=$Detail })
    Write-Host ("  [{0,-4}] {1,-38} {2}" -f $Status, $Check, $Detail) -ForegroundColor $color
    switch ($Status) { 'PASS'{$script:pass++} 'WARN'{$script:warn++} 'FAIL'{$script:fail++} }
}

Write-Host ""
Write-Host "  SQL Server $SqlVersion Pre-Install Checks" -ForegroundColor Cyan
Write-Host ("  " + [string]::new('-',60)) -ForegroundColor DarkCyan
Write-Host ""

# ── Admin elevation ───────────────────────────────────────────────────────────
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
               [Security.Principal.WindowsBuiltInRole]::Administrator)
Add-Check 'System' 'Running as Administrator' `
    $(if ($isAdmin) {'PASS'} else {'FAIL'}) `
    $(if ($isAdmin) {'Elevated'} else {'Re-run as Administrator'})

# ── OS version ────────────────────────────────────────────────────────────────
$os      = Get-CimInstance Win32_OperatingSystem
$osBuild = [int]$os.BuildNumber
$osName  = $os.Caption

$minBuild = switch ($SqlVersion) {
    '2022' { 17763 }  # Windows Server 2019
    '2019' { 14393 }  # Windows Server 2016
    '2017' { 14393 }  # Windows Server 2016
    '2016' { 9600  }  # Windows Server 2012 R2
}
$osStatus = if ($osBuild -ge $minBuild) {'PASS'} else {'FAIL'}
Add-Check 'System' 'OS version' $osStatus "$osName (Build $osBuild)"

# ── Pending reboot ────────────────────────────────────────────────────────────
$pendingReboot = $false
$rebootKeys = @(
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
    'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\PendingFileRenameOperations'
)
foreach ($key in $rebootKeys) {
    if (Test-Path $key) { $pendingReboot = $true; break }
}
Add-Check 'System' 'No pending reboot' `
    $(if ($pendingReboot) {'WARN'} else {'PASS'}) `
    $(if ($pendingReboot) {'Pending reboot detected - install may fail'} else {'Clean'})

# ── RAM ───────────────────────────────────────────────────────────────────────
$ramGB = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
$ramStatus = if ($ramGB -ge 8) {'PASS'} elseif ($ramGB -ge 4) {'WARN'} else {'FAIL'}
Add-Check 'Hardware' 'RAM' $ramStatus "$ramGB GB $(if ($ramGB -lt 8) {'(8 GB recommended)'})"

# ── CPU count ─────────────────────────────────────────────────────────────────
$cpus = (Get-CimInstance Win32_ComputerSystem).NumberOfLogicalProcessors
Add-Check 'Hardware' 'Logical CPUs' 'PASS' "$cpus processors"

# ── .NET Framework ────────────────────────────────────────────────────────────
$netKey = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction SilentlyContinue
$netVer = $netKey.Release
$netStatus = if ($netVer -ge 461808) {'PASS'} elseif ($netVer -ge 394802) {'WARN'} else {'FAIL'}
$netLabel  = if ($netVer -ge 528040) {'4.8+'} elseif ($netVer -ge 461808) {'4.7.2'} elseif ($netVer -ge 394802) {'4.6.2'} else {"$netVer (4.7.2+ required)"}
Add-Check 'Prerequisites' '.NET Framework' $netStatus $netLabel

# ── PowerShell version ────────────────────────────────────────────────────────
$psVer = $PSVersionTable.PSVersion
$psStatus = if ($psVer.Major -ge 5) {'PASS'} else {'WARN'}
Add-Check 'Prerequisites' 'PowerShell version' $psStatus "$($psVer.Major).$($psVer.Minor)"

# ── Disk space ────────────────────────────────────────────────────────────────
$diskChecks = @(
    @{ Path=$InstallDir; Label='Install dir';  MinGB=20 },
    @{ Path=$DataDir;    Label='Data dir';     MinGB=50 },
    @{ Path=$LogDir;     Label='Log dir';      MinGB=20 }
)
foreach ($dc in $diskChecks) {
    $drive   = Split-Path -Qualifier $dc.Path
    $psDrive = Get-PSDrive ($drive.TrimEnd(':')) -ErrorAction SilentlyContinue
    if ($psDrive) {
        $freeGB = [math]::Round($psDrive.Free / 1GB, 1)
        $status = if ($freeGB -ge $dc.MinGB) {'PASS'} elseif ($freeGB -ge ($dc.MinGB / 2)) {'WARN'} else {'FAIL'}
        Add-Check 'Disk' $dc.Label $status "$freeGB GB free on $drive (need $($dc.MinGB) GB)"
    } else {
        Add-Check 'Disk' $dc.Label 'WARN' "Drive $drive not found - will be created"
    }
}

# ── TCP port 1433 availability ────────────────────────────────────────────────
$port1433InUse = $false
try {
    $tcpConn = Get-NetTCPConnection -LocalPort 1433 -State Listen -ErrorAction SilentlyContinue
    if ($tcpConn) { $port1433InUse = $true }
} catch {
    Write-Error $_
    throw
}
Add-Check 'Network' 'TCP port 1433' `
    $(if ($port1433InUse) {'WARN'} else {'PASS'}) `
    $(if ($port1433InUse) {'Already in use - check existing SQL instance'} else {'Available'})

# ── Existing SQL Server instances ─────────────────────────────────────────────
$regInstances = @()
$regPath = 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL'
if (Test-Path $regPath) {
    $regInstances = Get-ItemProperty $regPath |
        Get-Member -MemberType NoteProperty |
        Where-Object { $_.Name -notmatch '^PS' } |
        Select-Object -ExpandProperty Name
}

if ($regInstances.Count -eq 0) {
    Add-Check 'SQL Server' 'Existing instances' 'PASS' 'None found'
} elseif ($regInstances -contains $InstanceName) {
    Add-Check 'SQL Server' 'Existing instances' 'FAIL' "Instance '$InstanceName' already exists: $($regInstances -join ', ')"
} else {
    Add-Check 'SQL Server' 'Existing instances' 'WARN' "Other instances present: $($regInstances -join ', ')"
}

# ── Windows Firewall ──────────────────────────────────────────────────────────
try {
    $fwProfile = (Get-NetFirewallProfile -ErrorAction Stop | Where-Object Enabled -eq $true | Select-Object -First 1).Name
    if ($fwProfile) {
        Add-Check 'Network' 'Windows Firewall' 'WARN' "Active profile: $fwProfile - ensure port 1433 rule is added post-install"
    } else {
        Add-Check 'Network' 'Windows Firewall' 'PASS' 'No active firewall profiles'
    }
} catch {
    Add-Check 'Network' 'Windows Firewall' 'WARN' 'Could not check firewall state'
}

# ── Summary ───────────────────────────────────────────────────────────────────
Write-Host ""
Write-Host ("  " + [string]::new('=',60)) -ForegroundColor DarkCyan
$summaryColor = if ($fail -gt 0) {'Red'} elseif ($warn -gt 0) {'Yellow'} else {'Green'}
$verdict      = if ($fail -gt 0) {'NOT READY - fix FAIL items before proceeding'} `
                elseif ($warn -gt 0) {'READY WITH WARNINGS - review WARN items'} `
                else {'READY - all checks passed'}
Write-Host "  $verdict" -ForegroundColor $summaryColor
Write-Host "  PASS: $pass   WARN: $warn   FAIL: $fail" -ForegroundColor $summaryColor
Write-Host ""

﻿<#
.SYNOPSIS
Uninstall a SQL Server instance with optional data directory cleanup.

.DESCRIPTION
Detects installed SQL Server instances, confirms the target, and runs setup.exe
/ACTION=Uninstall. Optionally removes data directories after uninstall.
All steps require explicit confirmation.

.PARAMETER SetupPath
Full path to SQL Server setup.exe for the version being removed.

.PARAMETER InstanceName
Instance to remove. If not specified, lists available instances and prompts.

.PARAMETER RemoveDataDirs
Also delete data and log directories after uninstall. Prompts for each path.

.PARAMETER WhatIf
Show what would run without executing.

.EXAMPLE
.\admin\installation\uninstall-sql.ps1 -SetupPath D:\SQL2022\setup.exe
.\admin\installation\uninstall-sql.ps1 -SetupPath D:\SQL2022\setup.exe -InstanceName SQL2022 -RemoveDataDirs

.NOTES
RiskLevel   : HIGH IMPACT - removes a SQL Server instance and can delete its data directories
#>
param(
    [string]$SetupPath,
    [string]$InstanceName,
    [switch]$RemoveDataDirs,
    [switch]$WhatIf
)

$ErrorActionPreference = 'Stop'

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host 'ERROR: This script must be run as Administrator.' -ForegroundColor Red; exit 1
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$logDir   = Join-Path $repoRoot 'output-files\installation'
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$ts       = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile  = Join-Path $logDir "uninstall-$ts.log"

function Write-DbaLog {
    param([string]$Msg, [string]$Color = 'White')
    $line = "[$(Get-Date -Format 'HH:mm:ss')] $Msg"
    Write-Host $line -ForegroundColor $Color
    Add-Content -Path $logFile -Value $line
}

Write-DbaLog "SQL Server uninstall log - $ts" 'Cyan'

# ── Detect installed instances ────────────────────────────────────────────────
$regPath   = 'HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL'
$instances = @()
if (Test-Path $regPath) {
    $instances = Get-ItemProperty $regPath |
        Get-Member -MemberType NoteProperty |
        Where-Object { $_.Name -notmatch '^PS' } |
        Select-Object -ExpandProperty Name
}

if ($instances.Count -eq 0) {
    Write-DbaLog 'No SQL Server instances found on this machine.' 'Yellow'; exit 0
}

Write-DbaLog 'Installed instances:' 'Cyan'
$instances | ForEach-Object { Write-DbaLog "  $_" }

if (-not $InstanceName) {
    $InstanceName = Read-Host "Instance to remove ($(($instances -join ', ')))"
}
if ($instances -notcontains $InstanceName) {
    Write-DbaLog "ERROR: Instance '$InstanceName' not found." 'Red'; exit 1
}

# ── Setup path ────────────────────────────────────────────────────────────────
if (-not $SetupPath) {
    do {
        $SetupPath = Read-Host 'Path to SQL Server setup.exe for this version'
    } until ($SetupPath -and (Test-Path $SetupPath))
}
if (-not (Test-Path $SetupPath)) {
    Write-DbaLog "ERROR: setup.exe not found at '$SetupPath'." 'Red'; exit 1
}

# ── Collect data dirs before uninstall ───────────────────────────────────────
$dataDirs = @()
if ($RemoveDataDirs) {
    $regBase = "HKLM:\SOFTWARE\Microsoft\Microsoft SQL Server"
    $instKey = Get-ItemProperty "$regBase\Instance Names\SQL" -ErrorAction SilentlyContinue
    $instId  = $instKey.$InstanceName

    if ($instId) {
        $setupKey = Get-ItemProperty "$regBase\$instId\Setup" -ErrorAction SilentlyContinue
        @('SQLDataRoot','SQLBinRoot','SQLUserDBDir','SQLUserDBLogDir','SQLTempDBDir','SQLTempDBLogDir') |
            ForEach-Object {
                $val = $setupKey.$_
                if ($val -and (Test-Path $val)) { $dataDirs += $val }
            }
        $dataDirs = $dataDirs | Sort-Object -Unique
    }
    if ($dataDirs.Count -gt 0) {
        Write-DbaLog 'Data directories that will be deleted:' 'Yellow'
        $dataDirs | ForEach-Object { Write-DbaLog "  $_" 'Yellow' }
    }
}

# ── Confirm ───────────────────────────────────────────────────────────────────
Write-DbaLog ''
Write-DbaLog "TARGET  : $InstanceName" 'Red'
Write-DbaLog "SETUP   : $SetupPath" 'Red'
if ($RemoveDataDirs -and $dataDirs.Count -gt 0) {
    Write-DbaLog "DATA DIRS WILL BE DELETED AFTER UNINSTALL" 'Red'
}
Write-DbaLog ''
Write-DbaLog 'WARNING: This is IRREVERSIBLE. Ensure you have backups of all databases.' 'Red'
Write-DbaLog ''

if ($WhatIf) {
    Write-DbaLog 'WhatIf - no changes made.' 'Yellow'; return
}

$confirm = Read-Host "Type the instance name '$InstanceName' to confirm uninstall"
if ($confirm -ne $InstanceName) {
    Write-DbaLog 'Confirmation did not match. Uninstall cancelled.' 'Yellow'; exit 0
}

# ── Run uninstall ─────────────────────────────────────────────────────────────
$uninstallArgs = @('/Q', '/ACTION=Uninstall', "/INSTANCENAME=$InstanceName", '/IACCEPTSQLSERVERLICENSETERMS')

Write-DbaLog 'Running SQL Server setup.exe /ACTION=Uninstall...' 'Cyan'
$proc = Start-Process -FilePath $SetupPath -ArgumentList $uninstallArgs `
            -Wait -PassThru `
            -RedirectStandardOutput "$logFile.stdout" `
            -RedirectStandardError  "$logFile.stderr"

$exitCode = $proc.ExitCode
Write-DbaLog "Exit code: $exitCode"

switch ($exitCode) {
    0    { Write-DbaLog 'Uninstall succeeded.' 'Green' }
    3010 { Write-DbaLog 'Uninstall succeeded - reboot required.' 'Yellow' }
    default {
        Write-DbaLog "Uninstall may have failed (exit $exitCode). Review: $logFile.stderr" 'Red'
        exit $exitCode
    }
}

# ── Optional data directory cleanup ──────────────────────────────────────────
if ($RemoveDataDirs -and $dataDirs.Count -gt 0) {
    Write-DbaLog ''
    Write-DbaLog 'Removing data directories...' 'Yellow'
    foreach ($dir in $dataDirs) {
        if (Test-Path $dir) {
            try {
                Remove-Item -Path $dir -Recurse -Force
                Write-DbaLog "  Removed: $dir" 'Green'
            } catch {
                Write-DbaLog "  Failed to remove $dir - $($_.Exception.Message)" 'Red'
            }
        }
    }
}

Write-DbaLog ''
Write-DbaLog 'Uninstall complete.' 'Green'
Write-DbaLog "Log: $logFile"

﻿<#
.SYNOPSIS
Returns a brief server identity and key configuration settings snapshot.

.NOTES
ScriptType   : runner
TargetScope  : single server
RiskLevel    : SAFE
Purpose      : Retrieve server name, edition, version, and core configuration settings for a quick health summary.
#>

param(
    [string]$SqlInstance = '.',
    [string]$Database = 'master'
)

$ErrorActionPreference = 'Stop'

try {
    $connectionString = "Server=$SqlInstance;Database=$Database;Integrated Security=True;Encrypt=False;TrustServerCertificate=True;"
    $connection = New-Object System.Data.SqlClient.SqlConnection($connectionString)
    $connection.Open()

    $sql = @'
SELECT
    @@SERVERNAME AS ServerName,
    SERVERPROPERTY('MachineName') AS MachineName,
    SERVERPROPERTY('InstanceName') AS InstanceName,
    SERVERPROPERTY('Edition') AS Edition,
    SERVERPROPERTY('ProductVersion') AS ProductVersion,
    SERVERPROPERTY('ProductLevel') AS ProductLevel;
'@

    $command = $connection.CreateCommand()
    $command.CommandText = $sql
    $reader = $command.ExecuteReader()
    $serverInfo = [ordered]@{}
    while ($reader.Read()) {
        for ($i = 0; $i -lt $reader.FieldCount; $i++) {
            $serverInfo[$reader.GetName($i)] = $reader.GetValue($i)
        }
    }
    $reader.Close()

    $sql = @'
SELECT
    name,
    value_in_use
FROM sys.configurations
WHERE name IN ('max degree of parallelism','max server memory (MB)','min server memory (MB)')
ORDER BY name;
'@
    $command.CommandText = $sql
    $configReader = $command.ExecuteReader()
    $configRows = New-Object System.Collections.Generic.List[object]
    while ($configReader.Read()) {
        $configRows.Add([pscustomobject]@{
            Name = $configReader['name']
            ValueInUse = $configReader['value_in_use']
        })
    }
    $configReader.Close()

    [pscustomobject]@{
        Server = $serverInfo
        Configuration = $configRows
    }
}
finally {
    if ($null -ne $connection -and $connection.State -eq 'Open') {
        $connection.Close()
    }
}

﻿<#
.SYNOPSIS
OS-level configuration checks not visible via SQL DMVs: power plan, page file, pending reboot.

.DESCRIPTION
Complements Get-OsConfigurationChecks.sql (which covers LPIM, NUMA, IFI via DMVs).
This script checks Windows-level settings that cause SQL Server performance issues
but are invisible from inside SQL: Balanced power plan throttles CPU under load,
undersized page file causes OS instability, pending reboot after Windows Update
leaves security patches unapplied and can cause unexpected restarts.

.NOTES
ScriptType  : automation
TargetScope : single server
RiskLevel   : SAFE
#>

param(
    [string]$ComputerName  = $env:COMPUTERNAME,
    [ValidateSet('Table', 'Csv')]
    [string]$OutputFormat  = 'Table',
    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'

$findings = [System.Collections.Generic.List[PSCustomObject]]::new()

function Add-Finding {
    param([string]$Check, [string]$CurrentValue, [string]$ExpectedValue, [string]$Status, [string]$Detail)
    $findings.Add([PSCustomObject]@{
        check          = $Check
        current_value  = $CurrentValue
        expected_value = $ExpectedValue
        status         = $Status
        detail         = $Detail
    })
}

# --- Power Plan ---
try {
    # For local machine, skip -ComputerName to avoid DCOM/WMI network path failures
    $isLocal    = $ComputerName -eq $env:COMPUTERNAME -or
                  $ComputerName -eq 'localhost'        -or
                  $ComputerName -eq '.'
    $cimSplat   = if ($isLocal) { @{} } else { @{ ComputerName = $ComputerName } }

    $activePlan = Get-CimInstance -ClassName Win32_PowerPlan -Namespace root\cimv2\power `
                      -Filter "IsActive = 'True'" @cimSplat -ErrorAction Stop |
                  Select-Object -First 1

    $planName = $activePlan.ElementName
    $status   = if ($planName -like '*High Performance*' -or $planName -like '*Ultimate Performance*') {
                    'OK'
                } elseif ($planName -like '*Balanced*') {
                    'CRITICAL'
                } else {
                    'WARN'
                }
    $detail   = if ($status -eq 'CRITICAL') {
                    'Balanced plan throttles CPU frequency under load - causes erratic query response times. Set to High Performance.'
                } elseif ($status -eq 'WARN') {
                    "Unknown plan '$planName' - verify it does not use CPU throttling."
                } else { 'No action required.' }

    Add-Finding 'Power Plan' $planName 'High Performance or Ultimate Performance' $status $detail
}
catch {
    Add-Finding 'Power Plan' 'Could not read' 'High Performance' 'WARN' "WMI query failed: $_"
}

# --- Page File ---
try {
    $pageFiles = Get-CimInstance -ClassName Win32_PageFileUsage @cimSplat -ErrorAction Stop

    if (-not $pageFiles) {
        Add-Finding 'Page File' 'None configured' 'System-managed or fixed' 'WARN' `
            'No page file detected. SQL Server requires a page file even with LPIM; absence can cause OS crashes under memory pressure.'
    }
    else {
        foreach ($pf in $pageFiles) {
            $currentMb  = [math]::Round($pf.CurrentUsage)
            $allocMb    = [math]::Round($pf.AllocatedBaseSize)
            $physMemGb  = [math]::Round((Get-CimInstance Win32_ComputerSystem @cimSplat).TotalPhysicalMemory / 1GB, 1)
            $minRecommendMb = [math]::Max(1024, [int]($physMemGb * 1024 * 0.1))  # at least 10% of RAM or 1 GB

            $status = if ($allocMb -lt $minRecommendMb) { 'WARN' } else { 'OK' }
            $detail = if ($status -eq 'WARN') {
                "Page file ($allocMb MB) may be too small for $physMemGb GB RAM. Recommend at least $minRecommendMb MB."
            } else { "Page file is $allocMb MB; current usage $currentMb MB." }

            Add-Finding 'Page File' "$allocMb MB on $($pf.Name)" "≥ $minRecommendMb MB" $status $detail
        }
    }
}
catch {
    Add-Finding 'Page File' 'Could not read' 'System-managed' 'WARN' "WMI query failed: $_"
}

# --- Pending Reboot ---
try {
    $pendingReboot = $false
    $rebootReasons = @()

    $cbsKey = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending"
    $wuKey  = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"
    $pfroKey= "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager"

    if (Test-Path $cbsKey) { $pendingReboot = $true; $rebootReasons += 'Windows component update' }
    if (Test-Path $wuKey)  { $pendingReboot = $true; $rebootReasons += 'Windows Update' }

    $pfro = Get-ItemProperty -Path $pfroKey -Name 'PendingFileRenameOperations' -ErrorAction SilentlyContinue
    if ($pfro) { $pendingReboot = $true; $rebootReasons += 'Pending file rename operations' }

    $status = if ($pendingReboot) { 'WARN' } else { 'OK' }
    $value  = if ($pendingReboot) { 'YES - ' + ($rebootReasons -join ', ') } else { 'No' }
    $detail = if ($pendingReboot) {
        'A reboot is pending. SQL Server will restart unexpectedly at next planned/unplanned reboot unless scheduled.'
    } else { 'No pending reboot detected.' }

    Add-Finding 'Pending Reboot' $value 'No' $status $detail
}
catch {
    Add-Finding 'Pending Reboot' 'Could not determine' 'No' 'WARN' "Registry check failed: $_"
}

# --- Output ---
$results = $findings | Sort-Object {
    switch ($_.status) { 'CRITICAL' { 1 } 'WARN' { 2 } 'INFO' { 3 } default { 4 } }
}

if ($OutputFormat -eq 'Csv') {
    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFile   = if ($OutputPath) { $OutputPath } else {
        $repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..') -ErrorAction SilentlyContinue
        $outDir   = if ($repoRoot) { Join-Path $repoRoot 'output-files\reviews\inventory' } else { $PWD }
        if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
        Join-Path $outDir "Test-OsConfiguration-$timestamp.csv"
    }
    $results | Export-Csv -Path $outFile -NoTypeInformation -Encoding UTF8
    Write-Host "Output saved: $outFile" -ForegroundColor Green
}
else {
    $results | Format-Table -AutoSize
}

﻿<#
.SYNOPSIS
Runs a pre-migration checklist covering network connectivity, SQL Server version/edition/collation
compatibility, disk space, and target server configuration.

.NOTES
ScriptType   : PowerShell-only
TargetScope  : source + target server pair
RiskLevel    : SAFE
Purpose      : Catch blockers before the migration window — connectivity, version mismatch,
               insufficient disk space, edition downgrade risk, and target misconfiguration.

.DESCRIPTION
Runs the following checks and prints a pass/warn/fail table:

  Network (from this machine):
    Source reachable on SQL port
    Target reachable on SQL port
    Backup share accessible (UNC)

  Network (source ↔ target, via WinRM if available):
    Source → Target on SQL port (1433 or custom)
    Target → Source on SQL port
    Source → Target on AG endpoint port (5022, if -CheckAG)
    Source and Target → Backup share on port 445 (SMB)

  SQL Server:
    Version: source ≤ target (backup/restore compatibility)
    Edition: flag downgrade risk if target is lower
    Collation: server-level collation match
    Target SQL Agent service running and auto-start

  Target configuration:
    max server memory configured (not at SQL Server default)
    TempDB file count vs logical CPU count
    Disk space on target: data volume free ≥ source total data size
    Disk space on target: log volume free ≥ source total log size

No SQL Server module required. Uses System.Data.SqlClient for SQL queries.
WinRM-based server-to-server port checks are attempted with Invoke-Command; if
WinRM is unavailable they are marked SKIPPED with an instruction to test manually.

.PARAMETER SourceInstance
Source SQL Server instance (e.g. PROD01 or PROD01\SQL2019). Required.

.PARAMETER TargetInstance
Target SQL Server instance (e.g. PROD02 or PROD02\SQL2019). Required.

.PARAMETER BackupPath
UNC or local path where backup files will be written. Optional but recommended.

.PARAMETER SqlPort
SQL Server TCP port to test. Defaults to 1433.

.PARAMETER CheckAG
Also test TCP port 5022 between source and target (AG Database Mirroring Endpoint).

.PARAMETER OutputPath
Optional CSV file path to save the check results.

.EXAMPLE
.\powershell\migration\Invoke-MigrationPreFlightCheck.ps1 -SourceInstance PROD01 -TargetInstance PROD02

.EXAMPLE
.\powershell\migration\Invoke-MigrationPreFlightCheck.ps1 -SourceInstance PROD01 -TargetInstance PROD02 `
    -BackupPath '\\BACKUPSRV\SQL-Backups' -CheckAG
#>

param(
    [Parameter(Mandatory)]
    [string]$SourceInstance,

    [Parameter(Mandatory)]
    [string]$TargetInstance,

    [string]$BackupPath,

    [int]$SqlPort = 1433,

    [switch]$CheckAG,

    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'

# ── Helpers ───────────────────────────────────────────────────────────────────

# Extract hostname from instance string (strip \INSTANCE)
function Get-Hostname([string]$instance) {
    ($instance -split '\\')[0]
}

# Test a TCP port from the local machine — returns $true/$false
function Test-Port([string]$hostName, [int]$port, [int]$timeout = 3000) {
    try {
        $tcp = [System.Net.Sockets.TcpClient]::new()
        $ar  = $tcp.BeginConnect($hostName, $port, $null, $null)
        $ok  = $ar.AsyncWaitHandle.WaitOne($timeout)
        if ($ok -and $tcp.Connected) { $tcp.Close(); return $true }
        $tcp.Close()
        return $false
    }
    catch { return $false }
}

# Resolve a hostname to its first IPv4 address
function Resolve-Ip([string]$hostName) {
    try {
        $addrs = [System.Net.Dns]::GetHostAddresses($hostName) |
            Where-Object { $_.AddressFamily -eq 'InterNetwork' }
        if ($addrs) { return $addrs[0].ToString() }
        return $null
    }
    catch { return $null }
}

# Run a SQL scalar query — no SMO, no SqlServer module required
function Invoke-SqlScalar([string]$instance, [string]$query, [int]$timeout = 10) {
    try {
        $cs   = "Server=$instance;Database=master;Integrated Security=True;Connect Timeout=$timeout;Application Name=MigrationPreFlightCheck"
        $conn = [System.Data.SqlClient.SqlConnection]::new($cs)
        $conn.Open()
        $cmd  = $conn.CreateCommand()
        $cmd.CommandText    = $query
        $cmd.CommandTimeout = $timeout
        $val  = $cmd.ExecuteScalar()
        $conn.Close()
        return $val
    }
    catch { return $null }
}

# Run a SQL query returning a DataTable
function Invoke-SqlDataTable([string]$instance, [string]$query, [int]$timeout = 15) {
    try {
        $cs      = "Server=$instance;Database=master;Integrated Security=True;Connect Timeout=$timeout;Application Name=MigrationPreFlightCheck"
        $conn    = [System.Data.SqlClient.SqlConnection]::new($cs)
        $conn.Open()
        $cmd     = $conn.CreateCommand()
        $cmd.CommandText    = $query
        $cmd.CommandTimeout = $timeout
        $adapter = [System.Data.SqlClient.SqlDataAdapter]::new($cmd)
        $dt      = [System.Data.DataTable]::new()
        [void]$adapter.Fill($dt)
        $conn.Close()
        return $dt
    }
    catch { return $null }
}

# Test a TCP port via Invoke-Command on a remote machine (requires WinRM/PSRemoting)
function Test-RemotePort([string]$fromHost, [int]$port, [string]$toHost, [int]$timeout = 3000) {
    try {
        $result = Invoke-Command -ComputerName $fromHost -ScriptBlock {
            try {
                $tcp = [System.Net.Sockets.TcpClient]::new()
                $ar  = $tcp.BeginConnect($Using:toHost, $Using:port, $null, $null)
                $ok  = $ar.AsyncWaitHandle.WaitOne($Using:timeout)
                if ($ok -and $tcp.Connected) { $tcp.Close(); return $true }
                $tcp.Close(); return $false
            } catch { return $false }
        } -ErrorAction Stop
        return [PSCustomObject]@{ Success = $result; Skipped = $false; Error = '' }
    }
    catch {
        return [PSCustomObject]@{ Success = $false; Skipped = $true; Error = $_.Exception.Message -replace "`r?`n",' ' }
    }
}

# Add a finding to the results table
function Add-Check {
    param(
        [string]$Category,
        [string]$Check,
        [ValidateSet('PASS','WARN','FAIL','SKIP','INFO')]
        [string]$Result,
        [string]$Detail
    )
    $script:checks.Add([PSCustomObject]@{
        Category = $Category
        Check    = $Check
        Result   = $Result
        Detail   = $Detail
    })
}

$script:checks = [System.Collections.Generic.List[PSObject]]::new()

$srcHost = Get-Hostname $SourceInstance
$tgtHost = Get-Hostname $TargetInstance

# ── Header ────────────────────────────────────────────────────────────────────

Write-Host ''
Write-Host ('=' * 60) -ForegroundColor Cyan
Write-Host '  Migration Pre-Flight Check' -ForegroundColor Cyan
Write-Host ('=' * 60) -ForegroundColor Cyan
Write-Host "  Source : $SourceInstance"
Write-Host "  Target : $TargetInstance"
if ($BackupPath) { Write-Host "  Backup : $BackupPath" }
Write-Host "  Time   : $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
Write-Host ('-' * 60)
Write-Host ''

# ══════════════════════════════════════════════════════════════
# SECTION 1 — DNS RESOLUTION
# ══════════════════════════════════════════════════════════════

$srcIp = Resolve-Ip $srcHost
$tgtIp = Resolve-Ip $tgtHost

Add-Check 'DNS' "Resolve source hostname ($srcHost)" `
    $(if ($srcIp) { 'PASS' } else { 'FAIL' }) `
    $(if ($srcIp) { "Resolved to $srcIp" } else { "Cannot resolve $srcHost - check DNS or use IP directly" })

Add-Check 'DNS' "Resolve target hostname ($tgtHost)" `
    $(if ($tgtIp) { 'PASS' } else { 'FAIL' }) `
    $(if ($tgtIp) { "Resolved to $tgtIp" } else { "Cannot resolve $tgtHost - check DNS or use IP directly" })

# ══════════════════════════════════════════════════════════════
# SECTION 2 — NETWORK CONNECTIVITY (from this machine)
# ══════════════════════════════════════════════════════════════

$srcPortOk = Test-Port $srcHost $SqlPort
$tgtPortOk = Test-Port $tgtHost $SqlPort

Add-Check 'Network (local→source)' "SQL port $SqlPort on $srcHost" `
    $(if ($srcPortOk) { 'PASS' } else { 'FAIL' }) `
    $(if ($srcPortOk) { "Port $SqlPort reachable" } else { "Port $SqlPort NOT reachable from this machine - check firewall rules" })

Add-Check 'Network (local→target)' "SQL port $SqlPort on $tgtHost" `
    $(if ($tgtPortOk) { 'PASS' } else { 'FAIL' }) `
    $(if ($tgtPortOk) { "Port $SqlPort reachable" } else { "Port $SqlPort NOT reachable from this machine - check firewall rules" })

if ($BackupPath -and $BackupPath.StartsWith('\\')) {
    $shareParts   = $BackupPath.TrimStart('\').Split('\')
    $backupHost   = $shareParts[0]
    $smbOk        = Test-Port $backupHost 445
    $localShareOk = Test-Path $BackupPath -ErrorAction SilentlyContinue

    Add-Check 'Network (local→backup)' "SMB port 445 on $backupHost" `
        $(if ($smbOk) { 'PASS' } else { 'FAIL' }) `
        $(if ($smbOk) { "Port 445 reachable" } else { "Port 445 not reachable - backup share may be inaccessible" })

    Add-Check 'Network (local→backup)' "UNC path accessible ($BackupPath)" `
        $(if ($localShareOk) { 'PASS' } else { 'WARN' }) `
        $(if ($localShareOk) { "Path is accessible from this machine" } else { "Path not accessible from this machine - verify SQL Server service account has access" })
}

# ══════════════════════════════════════════════════════════════
# SECTION 3 — NETWORK CONNECTIVITY (server-to-server via WinRM)
# ══════════════════════════════════════════════════════════════

$srcToTgt = Test-RemotePort $srcHost $SqlPort $tgtHost
$tgtToSrc = Test-RemotePort $tgtHost $SqlPort $srcHost

if ($srcToTgt.Skipped) {
    Add-Check 'Network (source→target)' "SQL port $SqlPort : $srcHost → $tgtHost" 'SKIP' `
        "WinRM not available on $srcHost - test manually: Test-NetConnection -ComputerName $tgtHost -Port $SqlPort"
} else {
    Add-Check 'Network (source→target)' "SQL port $SqlPort : $srcHost → $tgtHost" `
        $(if ($srcToTgt.Success) { 'PASS' } else { 'FAIL' }) `
        $(if ($srcToTgt.Success) { "Port $SqlPort reachable from $srcHost" } else { "Port $SqlPort NOT reachable from $srcHost - check firewall on target" })
}

if ($tgtToSrc.Skipped) {
    Add-Check 'Network (target→source)' "SQL port $SqlPort : $tgtHost → $srcHost" 'SKIP' `
        "WinRM not available on $tgtHost - test manually: Test-NetConnection -ComputerName $srcHost -Port $SqlPort"
} else {
    Add-Check 'Network (target→source)' "SQL port $SqlPort : $tgtHost → $srcHost" `
        $(if ($tgtToSrc.Success) { 'PASS' } else { 'FAIL' }) `
        $(if ($tgtToSrc.Success) { "Port $SqlPort reachable from $tgtHost" } else { "Port $SqlPort NOT reachable from $tgtHost - check firewall on source" })
}

if ($CheckAG) {
    $srcToTgtAG = Test-RemotePort $srcHost 5022 $tgtHost
    $tgtToSrcAG = Test-RemotePort $tgtHost 5022 $srcHost
    $label = 'AG endpoint port 5022'

    if ($srcToTgtAG.Skipped) {
        Add-Check 'Network (AG endpoint)' "$label : $srcHost → $tgtHost" 'SKIP' `
            "WinRM not available - test manually: Test-NetConnection -ComputerName $tgtHost -Port 5022"
    } else {
        Add-Check 'Network (AG endpoint)' "$label : $srcHost → $tgtHost" `
            $(if ($srcToTgtAG.Success) { 'PASS' } else { 'FAIL' }) `
            $(if ($srcToTgtAG.Success) { "Port 5022 reachable" } else { "Port 5022 NOT reachable - AG mirroring endpoint will fail. Check firewall and that endpoint is created on both nodes." })
    }

    if ($tgtToSrcAG.Skipped) {
        Add-Check 'Network (AG endpoint)' "$label : $tgtHost → $srcHost" 'SKIP' `
            "WinRM not available - test manually: Test-NetConnection -ComputerName $srcHost -Port 5022"
    } else {
        Add-Check 'Network (AG endpoint)' "$label : $tgtHost → $srcHost" `
            $(if ($tgtToSrcAG.Success) { 'PASS' } else { 'FAIL' }) `
            $(if ($tgtToSrcAG.Success) { "Port 5022 reachable" } else { "Port 5022 NOT reachable" })
    }
}

if ($BackupPath -and $BackupPath.StartsWith('\\')) {
    $shareParts = $BackupPath.TrimStart('\').Split('\')
    $backupHost = $shareParts[0]

    foreach ($srv in @($srcHost, $tgtHost)) {
        $res = Test-RemotePort $srv 445 $backupHost
        if ($res.Skipped) {
            Add-Check 'Network (backup share)' "SMB 445 : $srv → $backupHost" 'SKIP' `
                "WinRM not available - test manually on $srv"
        } else {
            Add-Check 'Network (backup share)' "SMB 445 : $srv → $backupHost" `
                $(if ($res.Success) { 'PASS' } else { 'FAIL' }) `
                $(if ($res.Success) { "SMB 445 reachable from $srv" } else { "SMB 445 NOT reachable from $srv - backup/restore will fail. Check firewall and share permissions." })
        }
    }
}

# ══════════════════════════════════════════════════════════════
# SECTION 4 — SQL SERVER VERSION AND EDITION
# ══════════════════════════════════════════════════════════════

$srcVersion   = Invoke-SqlScalar $SourceInstance "SELECT CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(20))"
$tgtVersion   = Invoke-SqlScalar $TargetInstance "SELECT CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(20))"
$srcEdition   = Invoke-SqlScalar $SourceInstance "SELECT CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128))"
$tgtEdition   = Invoke-SqlScalar $TargetInstance "SELECT CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128))"
$srcCollation = Invoke-SqlScalar $SourceInstance "SELECT CAST(SERVERPROPERTY('Collation') AS NVARCHAR(128))"
$tgtCollation = Invoke-SqlScalar $TargetInstance "SELECT CAST(SERVERPROPERTY('Collation') AS NVARCHAR(128))"

# Version comparison (major.minor.build.revision)
function Compare-SqlVersions([string]$src, [string]$tgt) {
    if (-not $src -or -not $tgt) { return 'UNKNOWN' }
    $s = [version]$src; $t = [version]$tgt
    if ($s.Major -gt $t.Major) { return 'SRC_NEWER' }
    if ($s.Major -eq $t.Major -and $s.Minor -gt $t.Minor) { return 'SRC_NEWER' }
    if ($s.Major -eq $t.Major) { return 'SAME_MAJOR' }
    return 'TGT_NEWER'
}

$versionComparison = Compare-SqlVersions $srcVersion $tgtVersion

if (-not $srcVersion) {
    Add-Check 'SQL Server' "Connect to source ($SourceInstance)" 'FAIL' "Cannot connect - check instance name, port, and permissions"
} else {
    Add-Check 'SQL Server' "Source version" 'INFO' "$srcVersion ($srcEdition)"
}

if (-not $tgtVersion) {
    Add-Check 'SQL Server' "Connect to target ($TargetInstance)" 'FAIL' "Cannot connect - check instance name, port, and permissions"
} else {
    Add-Check 'SQL Server' "Target version" 'INFO' "$tgtVersion ($tgtEdition)"
}

if ($srcVersion -and $tgtVersion) {
    $srcMajor = [int]($srcVersion -split '\.')[0]
    $tgtMajor = [int]($tgtVersion -split '\.')[0]

    if ($srcMajor -gt $tgtMajor) {
        Add-Check 'SQL Server' 'Version compatibility' 'FAIL' `
            "Source ($srcVersion) is NEWER than target ($tgtVersion). Databases cannot be restored to an older SQL Server version. Target must be same version or newer."
    } elseif ($srcMajor -eq $tgtMajor) {
        Add-Check 'SQL Server' 'Version compatibility' 'PASS' `
            "Same major version ($srcMajor). Backup/restore compatible."
    } else {
        Add-Check 'SQL Server' 'Version compatibility' 'PASS' `
            "Target ($tgtMajor) is newer than source ($srcMajor). Backup/restore compatible."
    }
}

# Edition rank (lower = less capable)
function Get-EditionRank([string]$edition) {
    if ($edition -match 'Enterprise')    { return 4 }
    if ($edition -match 'Standard')      { return 3 }
    if ($edition -match 'Developer')     { return 4 }
    if ($edition -match 'Web')           { return 2 }
    if ($edition -match 'Express')       { return 1 }
    return 0
}

if ($srcEdition -and $tgtEdition) {
    $srcRank = Get-EditionRank $srcEdition
    $tgtRank = Get-EditionRank $tgtEdition

    if ($srcRank -gt $tgtRank) {
        Add-Check 'SQL Server' 'Edition compatibility' 'WARN' `
            "Downgrading: $srcEdition → $tgtEdition. Run Get-EditionFeatureUsage.sql on source to audit Enterprise-only features before migration."
    } elseif ($srcRank -eq $tgtRank) {
        Add-Check 'SQL Server' 'Edition compatibility' 'PASS' `
            "Same edition tier: $srcEdition → $tgtEdition"
    } else {
        Add-Check 'SQL Server' 'Edition compatibility' 'PASS' `
            "Upgrading edition: $srcEdition → $tgtEdition"
    }
}

# Collation check
if ($srcCollation -and $tgtCollation) {
    $collMatch = $srcCollation -eq $tgtCollation
    Add-Check 'SQL Server' 'Server collation match' `
        $(if ($collMatch) { 'PASS' } else { 'WARN' }) `
        $(if ($collMatch) {
            "Both: $srcCollation"
        } else {
            "Source: $srcCollation | Target: $tgtCollation - collation mismatch. Databases can still be restored but string comparisons between server collations may behave differently. Ensure application does not rely on server-level collation for dynamic SQL."
        })
}

# ══════════════════════════════════════════════════════════════
# SECTION 5 — TARGET SERVER CONFIGURATION
# ══════════════════════════════════════════════════════════════

if ($tgtVersion) {

    # SQL Agent running
    $agentStatus = Invoke-SqlScalar $TargetInstance `
        "SELECT status_desc FROM sys.dm_server_services WHERE servicename LIKE '%Agent%'"

    Add-Check 'Target Config' 'SQL Agent status' `
        $(if ($agentStatus -eq 'Running') { 'PASS' } elseif ($agentStatus) { 'WARN' } else { 'SKIP' }) `
        $(if ($agentStatus) { "SQL Server Agent: $agentStatus" } else { "Could not determine - check SQL Agent is installed and running on target" })

    # max server memory
    $maxMem = Invoke-SqlScalar $TargetInstance `
        "SELECT value_in_use FROM sys.configurations WHERE name = 'max server memory (MB)'"

    Add-Check 'Target Config' 'Max server memory configured' `
        $(if ([long]$maxMem -ge 2147483647) { 'WARN' } elseif ([long]$maxMem -gt 0) { 'PASS' } else { 'SKIP' }) `
        $(if ([long]$maxMem -ge 2147483647) {
            "max server memory = $maxMem MB (SQL Server default - unconfigured). Set this before production load to prevent memory pressure."
        } else {
            "max server memory = $maxMem MB"
        })

    # TempDB file count vs CPU count
    $tempdbFiles = Invoke-SqlScalar $TargetInstance `
        "SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0"
    $cpuCount = Invoke-SqlScalar $TargetInstance `
        "SELECT CASE WHEN cpu_count > 8 THEN 8 ELSE cpu_count END FROM sys.dm_os_sys_info"

    Add-Check 'Target Config' 'TempDB data file count' `
        $(if ([int]$tempdbFiles -ge [int]$cpuCount) { 'PASS' } elseif ($tempdbFiles) { 'WARN' } else { 'SKIP' }) `
        $(if ($tempdbFiles -and $cpuCount) {
            "TempDB files: $tempdbFiles | Recommended: $cpuCount (min(CPUs,8)). $(if ([int]$tempdbFiles -lt [int]$cpuCount) { "Add $(([int]$cpuCount - [int]$tempdbFiles)) more data file(s) before migration." })"
        } else {
            "Could not determine TempDB file count"
        })

    # optimize for ad hoc workloads
    $adHoc = Invoke-SqlScalar $TargetInstance `
        "SELECT value_in_use FROM sys.configurations WHERE name = 'optimize for ad hoc workloads'"

    Add-Check 'Target Config' 'Optimize for ad hoc workloads' `
        $(if ([int]$adHoc -eq 1) { 'PASS' } else { 'WARN' }) `
        $(if ([int]$adHoc -eq 1) {
            'Enabled - reduces single-use plan cache bloat'
        } else {
            "Not enabled. Enable before go-live: sp_configure 'optimize for ad hoc workloads', 1; RECONFIGURE"
        })

}

# ══════════════════════════════════════════════════════════════
# SECTION 6 — DISK SPACE (source data size vs target free space)
# ══════════════════════════════════════════════════════════════

if ($srcVersion -and $tgtVersion) {
    $diskQuery = @"
SELECT
    CAST(SUM(CASE WHEN type=0 THEN size ELSE 0 END)*8.0/1024/1024 AS DECIMAL(12,1)) AS data_gb,
    CAST(SUM(CASE WHEN type=1 THEN size ELSE 0 END)*8.0/1024/1024 AS DECIMAL(12,1)) AS log_gb
FROM sys.master_files WHERE database_id > 4
"@
    $srcSizes = Invoke-SqlDataTable $SourceInstance $diskQuery

    if ($srcSizes -and $srcSizes.Rows.Count -gt 0) {
        $srcDataGb = [double]$srcSizes.Rows[0].data_gb
        $srcLogGb  = [double]$srcSizes.Rows[0].log_gb

        Add-Check 'Disk (source)' 'Total source data size' 'INFO' `
            "Data: $srcDataGb GB | Log: $srcLogGb GB | Total: $([Math]::Round($srcDataGb+$srcLogGb,1)) GB"
    }

    # Get disk space from target
    $tgtDiskQuery = @"
SELECT
    volume_mount_point,
    CAST(total_bytes/1073741824.0 AS DECIMAL(12,1)) AS total_gb,
    CAST(available_bytes/1073741824.0 AS DECIMAL(12,1)) AS free_gb
FROM sys.dm_os_volume_stats(1,1)
UNION
SELECT volume_mount_point,
    CAST(total_bytes/1073741824.0 AS DECIMAL(12,1)),
    CAST(available_bytes/1073741824.0 AS DECIMAL(12,1))
FROM sys.dm_os_volume_stats(2,1)
"@
    $tgtDisks = Invoke-SqlDataTable $TargetInstance $tgtDiskQuery

    if ($tgtDisks -and $tgtDisks.Rows.Count -gt 0) {
        $minFree = ($tgtDisks.Rows | Measure-Object { [double]$_.free_gb } -Minimum).Minimum
        foreach ($row in $tgtDisks.Rows) {
            Add-Check 'Disk (target)' "Volume $($row.volume_mount_point)" 'INFO' `
                "Free: $($row.free_gb) GB / $($row.total_gb) GB total"
        }

        if ($srcSizes -and $srcSizes.Rows.Count -gt 0 -and $minFree -lt $srcDataGb) {
            Add-Check 'Disk (target)' 'Disk space sufficient' 'WARN' `
                "Smallest target volume has $minFree GB free. Source data is $srcDataGb GB. Verify target drive layout has enough free space on each volume for data and log files."
        } elseif ($srcSizes -and $srcSizes.Rows.Count -gt 0) {
            Add-Check 'Disk (target)' 'Disk space sufficient' 'PASS' `
                "Target volumes have adequate free space relative to source data size ($srcDataGb GB)"
        }
    }
}

# ══════════════════════════════════════════════════════════════
# OUTPUT
# ══════════════════════════════════════════════════════════════

$failCount = @($script:checks | Where-Object Result -eq 'FAIL').Count
$warnCount = @($script:checks | Where-Object Result -eq 'WARN').Count
$passCount = @($script:checks | Where-Object Result -eq 'PASS').Count
$skipCount = @($script:checks | Where-Object Result -eq 'SKIP').Count

foreach ($c in $script:checks) {
    $color = switch ($c.Result) {
        'PASS' { 'Green' }
        'WARN' { 'Yellow' }
        'FAIL' { 'Red' }
        'SKIP' { 'DarkGray' }
        default { 'Cyan' }
    }
    Write-Host ("  [{0,-4}] {1,-38} {2}" -f $c.Result, $c.Check, $c.Detail) -ForegroundColor $color
}

Write-Host ''
Write-Host ('-' * 60) -ForegroundColor DarkCyan
Write-Host ("  PASS: $passCount  |  WARN: $warnCount  |  FAIL: $failCount  |  SKIP: $skipCount") `
    -ForegroundColor $(if ($failCount -gt 0) { 'Red' } elseif ($warnCount -gt 0) { 'Yellow' } else { 'Green' })

if ($failCount -gt 0) {
    Write-Host ''
    Write-Host '  BLOCKED - resolve all FAIL items before scheduling the migration window.' -ForegroundColor Red
} elseif ($warnCount -gt 0) {
    Write-Host ''
    Write-Host '  CAUTION - review WARN items before proceeding.' -ForegroundColor Yellow
} else {
    Write-Host ''
    Write-Host '  GO - pre-flight checks passed. Proceed with Invoke-MigrationExport.ps1.' -ForegroundColor Green
}

Write-Host ('-' * 60) -ForegroundColor DarkCyan
Write-Host ''

if ($OutputPath) {
    $script:checks | Export-Csv -LiteralPath $OutputPath -NoTypeInformation -Encoding UTF8
    Write-Host "  Results saved: $OutputPath" -ForegroundColor DarkGray
    Write-Host ''
}

# install-ssms.ps1 - Install or update SQL Server Management Studio
# RiskLevel   : MEDIUM - installs or upgrades SSMS on this machine; does not touch the database engine
# Guide       : https://sqldba.blog/sql-server-management-studio-complete-guide/
#
# SSMS 22+   (default) : downloads vs_SSMS.exe from aka.ms/ssms/22/release/vs_SSMS.exe
# SSMS 17-20 (winget)  : winget install Microsoft.SQLServerManagementStudio
#
# Cannot upgrade SSMS 17-20 in-place to SSMS 22 - run uninstall-ssms.ps1 first.
#
# Parameters:
#   -Method download|winget  : 'download' = SSMS 22 (default), 'winget' = SSMS 20
#   -Url <url>               : override download URL
#   -DownloadDir <path>      : folder to save installer (default: output-files\patches\ssms)
#   -Passive                 : show VS Installer progress window instead of silent
#   -UsePreview              : use winget preview package (winget method only)
#   -WhatIf                  : show what would run, no changes
#
# Examples:
#   .\install-ssms.ps1                          # install SSMS 22
#   .\install-ssms.ps1 -Passive                 # install with progress window
#   .\install-ssms.ps1 -Method winget           # install SSMS 20
#   .\install-ssms.ps1 -WhatIf                  # dry run
param(
    [ValidateSet('winget', 'download')]
    [string]$Method      = 'download',

    [string]$Url,

    [string]$DownloadDir,

    [switch]$UsePreview,

    [switch]$Passive,

    [switch]$WhatIf
)

$ErrorActionPreference = 'Stop'

# -- Admin check ---------------------------------------------------------------
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin -and -not $WhatIf) {
    Write-Host 'ERROR: This script must be run as Administrator (or use -WhatIf to preview without installing).' -ForegroundColor Red; exit 1
}

# -- Logging -------------------------------------------------------------------
# When run from the repo the log goes to output-files\patches\ssms\.
# When run standalone (copied to any folder) it falls back to a logs\ subfolder
# next to the script. Handles empty $PSScriptRoot (copy-pasted into console).
$_scriptRoot    = if ($PSScriptRoot) { $PSScriptRoot } else { $PWD.Path }
$_repoOutputDir = [System.IO.Path]::GetFullPath((Join-Path $_scriptRoot '..\..\..\output-files'))
$logDir = if (Test-Path $_repoOutputDir) {
    Join-Path $_repoOutputDir 'patches\ssms'
} else {
    Join-Path $_scriptRoot 'logs'
}
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$ts       = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile  = Join-Path $logDir "ssms-install-$ts.log"

function Write-DbaLog {
    param([string]$Msg, [string]$Color = 'White')
    $line = "[$(Get-Date -Format 'HH:mm:ss')] $Msg"
    Write-Host $line -ForegroundColor $Color
    Add-Content -Path $logFile -Value $line
}

Write-DbaLog "SSMS install log - $ts" 'Cyan'

# -- Detect current SSMS version -----------------------------------------------
function Get-InstalledSsms {
    $paths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($p in $paths) {
        $found = Get-ItemProperty $p -ErrorAction SilentlyContinue |
            Where-Object { $_.DisplayName -like '*SQL Server Management Studio*' } |
            Select-Object -First 1
        if ($found) { return $found }
    }
    return $null
}

$current = Get-InstalledSsms
if ($current) {
    $currentMajor = [int]($current.DisplayVersion -split '\.')[0]
    Write-DbaLog "Installed : $($current.DisplayName)  v$($current.DisplayVersion)" 'White'
    if ($currentMajor -ge 22) {
        Write-DbaLog "           (SSMS 22+ - VS Installer framework)" 'DarkGray'
    }
}
else {
    Write-DbaLog 'SSMS not detected - will perform a fresh install.' 'Yellow'
    $currentMajor = 0
}

# -- winget method -------------------------------------------------------------
if ($Method -eq 'winget') {
    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $winget) {
        Write-DbaLog 'winget not available - switching to download method.' 'Yellow'
        $Method = 'download'
    }
    else {
        $packageId = if ($UsePreview) {
            'Microsoft.SQLServerManagementStudio.Preview'
        } else {
            'Microsoft.SQLServerManagementStudio'
        }

        # Note: winget 'Microsoft.SQLServerManagementStudio' resolves to SSMS 20 (legacy stable).
        # SSMS 22 is not in the winget source catalog - use -Method download for SSMS 22.

        # Use 'install' for fresh installs, 'upgrade' when already present
        $wingetVerb = if ($current) { 'upgrade' } else { 'install' }

        Write-DbaLog "Method    : winget $wingetVerb  ($packageId)" 'Cyan'

        if ($WhatIf) {
            Write-DbaLog "WhatIf: winget $wingetVerb --id $packageId --silent --accept-source-agreements" 'Yellow'
            return
        }

        Write-DbaLog "Running: winget $wingetVerb --id $packageId ..." 'Cyan'
        $wingetArgs = @(
            $wingetVerb,
            '--id', $packageId,
            '--silent',
            '--accept-source-agreements'
        )
        $proc = Start-Process -FilePath $winget.Source -ArgumentList $wingetArgs `
                    -Wait -PassThru -NoNewWindow

        switch ($proc.ExitCode) {
            0            { Write-DbaLog "winget $wingetVerb completed." 'Green' }
            -1978335212  {
                # No package found in winget source
                if ($current) {
                    Write-DbaLog 'winget could not find a newer package. If running SSMS 22+, use -Method download for VS Installer updates.' 'Yellow'
                } else {
                    Write-DbaLog 'winget could not find the package. Use -Method download to install SSMS 22.' 'Yellow'
                }
            }
            -1978335189  {
                # Package found but no newer version in winget catalog
                if ($currentMajor -ge 22) {
                    Write-DbaLog 'SSMS 22+ is not updated via winget. Use -Method download for in-place VS Installer updates.' 'Yellow'
                } else {
                    Write-DbaLog 'SSMS is at the latest version available in the winget catalog.' 'Green'
                }
            }
            default      { Write-DbaLog "winget exited with code $($proc.ExitCode) - check output above." 'Yellow' }
        }
    }
}

# -- Download method -----------------------------------------------------------
if ($Method -eq 'download') {
    # SSMS 22+ (VS Installer bootstrapper):
    #   URL  : https://aka.ms/ssms/22/release/vs_SSMS.exe  (always latest SSMS 22.x)
    #   Flags: --quiet --norestart --wait
    #   Ref  : https://learn.microsoft.com/en-us/ssms/install/install
    #
    # SSMS 20 and below (legacy WiX installer):
    #   URL  : https://aka.ms/ssmsfullsetup  (resolves to latest SSMS 20.x)
    #   Flags: /install /quiet /norestart
    $downloadUrl = if ($Url) { $Url } else { 'https://aka.ms/ssms/22/release/vs_SSMS.exe' }

    $saveDir = if ($DownloadDir) { $DownloadDir } else { $logDir }
    New-Item -ItemType Directory -Path $saveDir -Force | Out-Null

    # Preserve the original filename so installer type can be detected from it
    $installerFileName = Split-Path $downloadUrl -Leaf
    if ($installerFileName -notmatch '\.exe$') { $installerFileName = "SSMS-Setup-$ts.exe" }
    $installerPath = Join-Path $saveDir $installerFileName

    # Detect installer type by filename:
    # vs_SSMS.exe = VS Installer bootstrapper (SSMS 22+) -> uses -- style flags
    # SSMS-Setup-ENU.exe = legacy WiX installer (SSMS 20 and below) -> uses / style flags
    $isVsBootstrapper = $installerFileName -like 'vs_*.exe'

    Write-DbaLog "Method    : download" 'Cyan'
    Write-DbaLog "URL       : $downloadUrl"
    Write-DbaLog "Installer : $installerFileName ($( if ($isVsBootstrapper) { 'VS bootstrapper - SSMS 22+' } else { 'legacy WiX - SSMS 20 and below' } ))" 'DarkGray'

    # Cross-framework upgrade check:
    # SSMS 20->22 cannot upgrade in-place - the installer framework changed entirely.
    # SSMS 22->22.x can update in-place via the VS bootstrapper.
    if ($current -and $currentMajor -lt 22 -and $isVsBootstrapper) {
        # Covers SSMS 17, 18, 19, 20 - all use the legacy WiX installer framework.
        # SSMS 22+ (VS Installer) cannot upgrade over the top of any of these.
        Write-DbaLog ''
        Write-DbaLog "SSMS $($current.DisplayName) v$($current.DisplayVersion) is installed (legacy WiX installer - versions 17-20)." 'Yellow'
        Write-DbaLog "SSMS 22+ uses the VS Installer framework and cannot upgrade in-place over a legacy SSMS install." 'Yellow'
        Write-DbaLog "Run .\uninstall-ssms.ps1 first, then re-run this script to install SSMS 22." 'Yellow'
        exit 0
    }

    if ($current -and $currentMajor -ge 22 -and $isVsBootstrapper) {
        Write-DbaLog "SSMS $($current.DisplayVersion) detected (VS Installer framework) - bootstrapper will perform an in-place update." 'DarkGray'
    }

    if ($WhatIf) {
        $flags = if ($isVsBootstrapper) { '--quiet --norestart --wait' } else { '/install /quiet /norestart' }
        Write-DbaLog "WhatIf: download '$downloadUrl' -> '$installerPath'" 'Yellow'
        Write-DbaLog "WhatIf: Start-Process '$installerPath' $flags" 'Yellow'
        return
    }

    Write-DbaLog 'Downloading SSMS installer...' 'Cyan'
    try {
        Start-BitsTransfer -Source $downloadUrl -Destination $installerPath -DisplayName "SSMS: $installerFileName"
        $sizeMB = [math]::Round((Get-Item $installerPath).Length / 1MB, 1)
        Write-DbaLog "Downloaded : $installerFileName ($sizeMB MB)" 'Green'
    }
    catch {
        Write-DbaLog "ERROR: Download failed - $($_.Exception.Message)" 'Red'
        exit 1
    }

    $installArgs = if ($isVsBootstrapper) {
        $uiFlag = if ($Passive) { '--passive' } else { '--quiet' }
        # --wait is required for the bootstrapper: vs_SSMS.exe launches the real VS Installer
        # as a child process and exits immediately without it. --wait holds it open until done.
        @($uiFlag, '--norestart', '--wait')
    } else {
        @('/install', '/quiet', '/norestart')
    }

    Write-DbaLog "Installing SSMS ($($installArgs -join ' '))..." 'Cyan'
    $proc = Start-Process -FilePath $installerPath -ArgumentList $installArgs -PassThru `
        -RedirectStandardOutput "$logFile.vs-stdout.txt" `
        -RedirectStandardError  "$logFile.vs-stderr.txt"
    $sw   = [System.Diagnostics.Stopwatch]::StartNew()
    while (-not $proc.HasExited) {
        Write-Host ("`r    ... {0:mm\:ss} elapsed" -f $sw.Elapsed) -NoNewline -ForegroundColor DarkGray
        Start-Sleep -Seconds 2
    }
    Write-Host ''

    switch ($proc.ExitCode) {
        0    { Write-DbaLog 'SSMS install completed.' 'Green' }
        3010 { Write-DbaLog 'SSMS install completed - reboot required.' 'Yellow' }
        default { Write-DbaLog "Installer exited with code $($proc.ExitCode) - verify manually." 'Yellow' }
    }
}

# -- Verify new version --------------------------------------------------------
Write-DbaLog ''
Write-DbaLog 'Checking installed SSMS version...' 'Cyan'
$updated = Get-InstalledSsms
if ($updated) {
    if ($current -and $updated.DisplayVersion -ne $current.DisplayVersion) {
        Write-DbaLog "SSMS updated : v$($current.DisplayVersion)  ->  v$($updated.DisplayVersion)" 'Green'
    }
    else {
        Write-DbaLog "SSMS version : v$($updated.DisplayVersion)" 'Green'
    }
}
else {
    Write-DbaLog 'Could not read SSMS version from registry - verify manually.' 'Yellow'
}

# -- Add SSMS to PATH ----------------------------------------------------------
$ssmsExe = $null

# SSMS 22+: use vswhere to get the install path
$vswhere = 'C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe'
if (Test-Path $vswhere) {
    try {
        $vsProducts = & $vswhere -all -products '*' -format json 2>&1 | ConvertFrom-Json
        $ssmsProduct = $vsProducts |
            Where-Object { $_.displayName -like '*SQL Server Management Studio*' } |
            Select-Object -First 1
        if ($ssmsProduct) {
            $candidate = Join-Path $ssmsProduct.installationPath 'Common7\IDE\Ssms.exe'
            if (Test-Path $candidate) { $ssmsExe = $candidate }
        }
    } catch { }
}

# Legacy SSMS (17-20): try registry InstallLocation then known default paths
if (-not $ssmsExe -and $updated -and $updated.InstallLocation) {
    $candidate = Join-Path $updated.InstallLocation 'Common7\IDE\Ssms.exe'
    if (Test-Path $candidate) { $ssmsExe = $candidate }
}
if (-not $ssmsExe) {
    $knownPaths = @(
        'C:\Program Files\Microsoft SQL Server Management Studio 22\Common7\IDE\Ssms.exe',
        'C:\Program Files (x86)\Microsoft SQL Server Management Studio 20\Common7\IDE\Ssms.exe',
        'C:\Program Files (x86)\Microsoft SQL Server Management Studio 19\Common7\IDE\Ssms.exe',
        'C:\Program Files (x86)\Microsoft SQL Server Management Studio 18\Common7\IDE\Ssms.exe'
    )
    $ssmsExe = $knownPaths | Where-Object { Test-Path $_ } | Select-Object -First 1
}

if ($ssmsExe) {
    $ssmsDir     = Split-Path $ssmsExe
    $machinePath = [System.Environment]::GetEnvironmentVariable('PATH', 'Machine')
    if ($machinePath -notlike "*$ssmsDir*") {
        [System.Environment]::SetEnvironmentVariable('PATH', "$machinePath;$ssmsDir", 'Machine')
        $env:PATH += ";$ssmsDir"
        Write-DbaLog "PATH updated  : added $ssmsDir" 'Green'
        Write-DbaLog "              Type 'ssms' to launch (current terminal already updated)." 'DarkGray'
    }
    else {
        Write-DbaLog "PATH          : 'ssms' command already available." 'DarkGray'
    }
}

Write-DbaLog ''
Write-DbaLog 'Done.' 'Green'
Write-DbaLog "Log: $logFile"

# uninstall-ssms.ps1 - Silently uninstall SQL Server Management Studio
# RiskLevel   : MEDIUM - removes SSMS from this machine; does not touch the database engine
#
# SSMS 17-20  : WiX installer - reads UninstallString, appends /uninstall /quiet /norestart
# SSMS 21+    : VS Installer  - uses vswhere to find productId, runs setup.exe uninstall -q
#               winget is tried as a fallback if vswhere fails
#
# Parameters:
#   -WhatIf   : show what would run, no changes
#   -Force    : skip confirmation prompts
#   -Passive  : show VS Installer progress window (default is silent with console timer)
#
# Examples:
#   .\uninstall-ssms.ps1 -WhatIf
#   .\uninstall-ssms.ps1
#   .\uninstall-ssms.ps1 -Force
param(
    [switch]$WhatIf,
    [switch]$Force,
    [switch]$Passive
)

$ErrorActionPreference = 'Stop'

# -- Pending reboot check ------------------------------------------------------
$rebootKeys = @(
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootInProgress'
)
$rebootPending = ($rebootKeys | Where-Object { Test-Path $_ }) -or
    (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations

if ($rebootPending -and -not $WhatIf) {
    Write-Host 'NOTE: A system reboot is pending on this machine.' -ForegroundColor Yellow
}

# -- Admin check ---------------------------------------------------------------
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin -and -not $WhatIf) {
    Write-Host 'ERROR: This script must be run as Administrator (or use -WhatIf to preview without uninstalling).' -ForegroundColor Red; exit 1
}

# -- Logging -------------------------------------------------------------------
# Falls back to a logs\ folder next to the script when run standalone (not in the repo)
$_repoOutputDir = Join-Path $PSScriptRoot '..\..\..\output-files'
$logDir = [System.IO.Path]::GetFullPath($(if (Test-Path $_repoOutputDir) {
    Join-Path $_repoOutputDir 'patches\ssms'
} else {
    Join-Path $PSScriptRoot 'logs'
}))
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$ts       = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile  = Join-Path $logDir "ssms-uninstall-$ts.log"

function Write-DbaLog {
    param([string]$Msg, [string]$Color = 'White')
    $line = "[$(Get-Date -Format 'HH:mm:ss')] $Msg"
    Write-Host $line -ForegroundColor $Color
    Add-Content -Path $logFile -Value $line
}

Write-DbaLog "SSMS uninstall log - $ts" 'Cyan'

# -- Find all installed SSMS entries ------------------------------------------
$regPaths = @(
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
)

$ssmsEntries = @(
    foreach ($p in $regPaths) {
        Get-ItemProperty $p -ErrorAction SilentlyContinue |
            Where-Object {
                $_.DisplayName -like '*SQL Server Management Studio*' -and
                # Skip MSI sub-component registrations (Language Pack, base MSI entries).
                # UninstallString starting with 'MsiExec.exe /I{' means it's an install-mode
                # registration - the main bootstrapper already removes these sub-components.
                $_.UninstallString -notmatch '^MsiExec\.exe /I\{'
            }
    }
) | Sort-Object { [version]($_.DisplayVersion -replace '[^0-9.]') } -Descending

if ($ssmsEntries.Count -eq 0) {
    Write-DbaLog 'No SSMS installation detected. Nothing to uninstall.' 'Yellow'
    exit 0
}

$script:uninstallCompletedCleanly = $false
$script:anyAttempted = $false
$script:attemptedNames = [System.Collections.Generic.List[string]]::new()

foreach ($entry in $ssmsEntries) {
    $version = $entry.DisplayVersion
    $name    = $entry.DisplayName
    $major   = [int]($version -split '\.')[0]

    Write-DbaLog ''
    Write-DbaLog "Found : $name  v$version" 'White'

    if ($WhatIf) {
        $method = if ($major -ge 21) { 'VS Installer CLI or winget' } else { 'WiX /uninstall /quiet /norestart' }
        Write-DbaLog "  [WhatIf] Would uninstall '$name' via $method." 'Yellow'
        continue
    }

    if (-not $Force) {
        $answer = (Read-Host "  Uninstall '$name' v$version now? (yes/no)").Trim()
        if ($answer -notmatch '^(yes|y)$') {
            Write-DbaLog '  Skipped by user.' 'Yellow'
            continue
        }
    }

    # -- Check if SSMS is running ----------------------------------------------
    $ssmsProc  = Get-Process -Name 'ssms' -ErrorAction SilentlyContinue
    $forceClose = $false
    if ($ssmsProc) {
        $pidList = ($ssmsProc | ForEach-Object { $_.Id }) -join ', '
        Write-DbaLog "  WARNING: SSMS is currently running (PID $pidList)." 'Yellow'
        if ($Force) {
            Write-DbaLog "  -Force specified - will close SSMS automatically." 'Yellow'
            $forceClose = $true
        }
        else {
            $closeAnswer = (Read-Host "  Force close SSMS before uninstalling? (yes/no)").Trim()
            if ($closeAnswer -notmatch '^(yes|y)$') {
                Write-DbaLog "  Skipped - close SSMS manually and re-run." 'Yellow'
                continue
            }
            $forceClose = $true
        }
    }

    # -- SSMS 21+ (Visual Studio Installer) -----------------------------------
    if ($major -ge 21) {
        $script:anyAttempted = $true
        $script:attemptedNames.Add($name)
        Write-DbaLog "  Uninstalling '$name'..." 'Cyan'
        $uninstalled = $false
        $forceFlag   = if ($forceClose) { ' --force' } else { '' }
        $uiFlag      = if ($Passive)    { '--passive' } else { '--quiet' }

        $vswhere     = 'C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe'
        $vsInstaller = 'C:\Program Files (x86)\Microsoft Visual Studio\Installer\setup.exe'

        # Helper: run setup.exe, wait, stream elapsed, check result
        function Invoke-VsUninstall {
            param([string]$Exe, [string]$CmdArgs, [string]$EntryName)
            $fullCmd = "  Running: $Exe $CmdArgs"
            Write-Host "[$(Get-Date -Format 'HH:mm:ss')] $fullCmd" -ForegroundColor DarkGray
            Add-Content -Path $logFile -Value "[$(Get-Date -Format 'HH:mm:ss')] $fullCmd"
            $proc = Start-Process -FilePath $Exe -ArgumentList $CmdArgs -PassThru `
                -RedirectStandardOutput "$logFile.vs-stdout.txt" `
                -RedirectStandardError  "$logFile.vs-stderr.txt"
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            while (-not $proc.HasExited) {
                Write-Host ("`r    ... {0:mm\:ss} elapsed" -f $sw.Elapsed) -NoNewline -ForegroundColor DarkGray
                Start-Sleep -Seconds 2
            }
            Write-Host ''
            if (Test-Path "$logFile.vs-stderr.txt") {
                $vsErr = (Get-Content "$logFile.vs-stderr.txt" -Raw)
                if ($vsErr) { Write-DbaLog "  VS Installer: $($vsErr.Trim())" 'DarkGray' }
            }
            # Check only for this specific entry, not all SSMS installs
            $stillThere = @(foreach ($p in $regPaths) {
                Get-ItemProperty $p -ErrorAction SilentlyContinue |
                    Where-Object { $_.DisplayName -eq $EntryName -and $_.UninstallString -notmatch '^MsiExec\.exe /I\{' }
            })
            return ($stillThere.Count -eq 0)
        }

        # 1. vswhere - productId + channelId (avoids --installPath entirely)
        if ((Test-Path $vswhere) -and (Test-Path $vsInstaller)) {
            try {
                $vsJson      = & $vswhere -all -products '*' -format json
                $vsProducts  = $vsJson | ConvertFrom-Json
                # Match by installationPath extracted from registry UninstallString so we
                # pick the right entry when multiple SSMS versions are installed side-by-side.
                $regInstallPath = $null
                $rawCmdForMatch = if ($entry.QuietUninstallString) { $entry.QuietUninstallString } else { $entry.UninstallString }
                if ($rawCmdForMatch -match '--installPath\s+"([^"]+)"') { $regInstallPath = $Matches[1] }
                $ssmsProduct = @($vsProducts) |
                    Where-Object {
                        $_.displayName -like '*SQL Server Management Studio*' -and
                        (-not $regInstallPath -or $_.installationPath -eq $regInstallPath)
                    } |
                    Select-Object -First 1

                if ($ssmsProduct) {
                    $channelPart = if ($ssmsProduct.channelId) { " --channelId $($ssmsProduct.channelId)" } else { '' }
                    $vsArgs = "uninstall --productId $($ssmsProduct.productId)$channelPart $uiFlag --norestart$forceFlag"
                    if (Invoke-VsUninstall -Exe $vsInstaller -CmdArgs $vsArgs -EntryName $name) {
                        $script:uninstallCompletedCleanly = $true
                        $uninstalled = $true
                    }
                } else {
                    Write-DbaLog '  vswhere: SSMS not found in VS Installer catalogue - trying registry fallback.' 'DarkGray'
                }
            }
            catch { Write-DbaLog "  vswhere error: $($_.Exception.Message)" 'DarkGray' }
        }

        # 2. Registry passthrough - use the stored VS Installer command but swap --installPath
        #    for --productId when the installer rejects it (seen on SSMS 21 Preview builds)
        if (-not $uninstalled) {
            $rawCmd = if ($entry.QuietUninstallString) { $entry.QuietUninstallString } else { $entry.UninstallString }
            if ($rawCmd -match 'setup\.exe') {
                $regExe  = $null; $regArgs = $null
                if ($rawCmd -match '^"([^"]+)"(.*)$')  { $regExe = $Matches[1]; $regArgs = $Matches[2].Trim() }
                elseif ($rawCmd -match '^(\S+)(.*)$')   { $regExe = $Matches[1]; $regArgs = $Matches[2].Trim() }

                if ($regExe -and (Test-Path $regExe)) {
                    # If --installPath is present, try replacing with --productId derived from path
                    if ($regArgs -match '--installPath\s+"[^"]+"') {
                        $derivedId  = 'Microsoft.VisualStudio.Product.Ssms'
                        $regArgs    = $regArgs -replace '--installPath\s+"[^"]+"', "--productId $derivedId"
                        Write-DbaLog '  Registry fallback: replaced --installPath with --productId.' 'DarkGray'
                    }
                    if ($regArgs -notmatch '--quiet|--passive') { $regArgs += " $uiFlag" }
                    if ($regArgs -notmatch '--norestart')       { $regArgs += ' --norestart' }
                    if ($forceClose -and $regArgs -notmatch '--force') { $regArgs += ' --force' }
                    if (Invoke-VsUninstall -Exe $regExe -CmdArgs $regArgs.Trim() -EntryName $name) {
                        $script:uninstallCompletedCleanly = $true
                        $uninstalled = $true
                    }
                }
            }
        }

        # 3. Winget fallback (tries stable ID then preview ID then display name)
        if (-not $uninstalled) {
            $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
            if ($winget) {
                $wingetAttempts = @(
                    @('uninstall', '--id', 'Microsoft.SQLServerManagementStudio',         '-e', '--silent', '--accept-source-agreements'),
                    @('uninstall', '--id', 'Microsoft.SQLServerManagementStudio.Preview',  '-e', '--silent', '--accept-source-agreements'),
                    @('uninstall', '--name', "`"$name`"",                                  '-e', '--silent', '--accept-source-agreements')
                )
                foreach ($wingetArgs in $wingetAttempts) {
                    $proc = Start-Process -FilePath $winget.Source -ArgumentList $wingetArgs -Wait -PassThru -NoNewWindow
                    if ($proc.ExitCode -in 0, 3010) {
                        $script:uninstallCompletedCleanly = $true
                        $uninstalled = $true
                        break
                    }
                }
            }
        }

        if ($uninstalled) {
            Write-DbaLog '  Uninstall completed.' 'Green'
        } else {
            Write-DbaLog '  Uninstall failed - remove manually via Settings -> Apps or:' 'Red'
            Write-DbaLog '    winget uninstall --id Microsoft.SQLServerManagementStudio.Preview -e' 'DarkGray'
            Write-DbaLog '    winget uninstall --id Microsoft.SQLServerManagementStudio -e' 'DarkGray'
        }
        continue
    }

    # -- SSMS 20 and below (WiX installer) ------------------------------------
    $rawCmd = if ($entry.QuietUninstallString) { $entry.QuietUninstallString } else { $entry.UninstallString }

    if (-not $rawCmd) {
        Write-DbaLog "  ERROR: No uninstall command in registry for '$name'. Use Settings -> Apps." 'Red'
        continue
    }

    if ($rawCmd -match '^"([^"]+)"(.*)$') {
        $exePath      = $Matches[1]
        $existingArgs = $Matches[2].Trim()
    }
    elseif ($rawCmd -match '^(\S+)(.*)$') {
        $exePath      = $Matches[1]
        $existingArgs = $Matches[2].Trim()
    }
    else {
        Write-DbaLog "  ERROR: Cannot parse uninstall command." 'Red'; continue
    }

    if (-not (Test-Path $exePath)) {
        Write-DbaLog "  ERROR: Uninstall EXE not found: $exePath" 'Red'; continue
    }

    $silentArgs = [System.Collections.Generic.List[string]]::new()
    if ($existingArgs -notmatch '/uninstall') { $silentArgs.Add('/uninstall') }
    if ($existingArgs -notmatch '/quiet')     { $silentArgs.Add('/quiet') }
    if ($existingArgs -notmatch '/norestart') { $silentArgs.Add('/norestart') }
    $finalArgs = ($existingArgs + ' ' + ($silentArgs -join ' ')).Trim()

    $script:anyAttempted = $true
    $script:attemptedNames.Add($name)
    Write-DbaLog "  Uninstalling '$name'..." 'Cyan'
    Write-DbaLog "  Running: $exePath $finalArgs" 'DarkGray'
    $wixOk = $false
    try {
        $proc = Start-Process -FilePath $exePath -ArgumentList $finalArgs -PassThru
        $sw   = [System.Diagnostics.Stopwatch]::StartNew()
        while (-not $proc.HasExited) {
            Write-Host ("`r    ... {0:mm\:ss} elapsed" -f $sw.Elapsed) -NoNewline -ForegroundColor DarkGray
            Start-Sleep -Seconds 2
        }
        Write-Host ''
        switch ($proc.ExitCode) {
            0    { Write-DbaLog '  Uninstall completed.' 'Green'; $wixOk = $true }
            3010 { Write-DbaLog '  Uninstall completed - reboot required.' 'Yellow'; $wixOk = $true }
            1626 { Write-DbaLog "  Exit 1626 - reboot this machine and retry, or use appwiz.cpl to remove manually." 'Yellow' }
            default { Write-DbaLog "  Uninstall exited with code $($proc.ExitCode) - trying winget fallback..." 'Yellow' }
        }
    }
    catch {
        Write-DbaLog "  ERROR during uninstall: $($_.Exception.Message)" 'Red'
    }

    if (-not $wixOk) {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $wingetAttempts = @(
                @('uninstall', '--id',   'Microsoft.SQLServerManagementStudio',   '-e', '--silent', '--accept-source-agreements'),
                @('uninstall', '--name', "`"$name`"",                              '-e', '--silent', '--accept-source-agreements')
            )
            foreach ($wingetArgs in $wingetAttempts) {
                $wp = Start-Process -FilePath $winget.Source -ArgumentList $wingetArgs -Wait -PassThru -NoNewWindow
                if ($wp.ExitCode -in 0, 3010) {
                    Write-DbaLog '  Uninstall completed via winget.' 'Green'
                    $wixOk = $true
                    break
                }
            }
        }
        if (-not $wixOk) {
            # Last resort: find MSI product code directly from registry and call MsiExec /X
            # bypasses the Burn bootstrapper entirely, useful when Package Cache is corrupt
            $productCode = $null
            foreach ($p in $regPaths) {
                $match = Get-ItemProperty $p -ErrorAction SilentlyContinue |
                    Where-Object {
                        $_.DisplayName -eq $name -and
                        $_.PSChildName -match '^\{[0-9A-F-]+\}$'
                    } | Select-Object -First 1
                if ($match) { $productCode = $match.PSChildName; break }
            }
            if ($productCode) {
                Write-DbaLog "  Trying MsiExec direct removal (product code $productCode)..." 'DarkGray'
                $mp = Start-Process -FilePath 'MsiExec.exe' -ArgumentList "/X$productCode /qn /norestart" -Wait -PassThru
                if ($mp.ExitCode -in 0, 3010) {
                    Write-DbaLog '  Uninstall completed via MsiExec.' 'Green'
                    $wixOk = $true
                } else {
                    Write-DbaLog "  MsiExec exited with code $($mp.ExitCode)." 'Yellow'
                }
            }
        }
        if (-not $wixOk) {
            Write-DbaLog '  Uninstall failed - remove manually via Settings -> Apps or:' 'Red'
            Write-DbaLog "    winget uninstall --name `"$name`" -e" 'DarkGray'
        }
    }
}

# -- Confirm removal -----------------------------------------------------------
if (-not $WhatIf -and $script:anyAttempted) {
    Write-DbaLog ''
    Write-DbaLog 'Verifying removal...' 'Cyan'
    $stillInstalled = @(
        foreach ($p in $regPaths) {
            Get-ItemProperty $p -ErrorAction SilentlyContinue |
                Where-Object {
                    $script:attemptedNames -contains $_.DisplayName -and
                    $_.UninstallString -notmatch '^MsiExec\.exe /I\{'
                }
        }
    )
    if ($stillInstalled.Count -eq 0) {
        Write-DbaLog 'SSMS successfully removed.' 'Green'
    }
    else {
        foreach ($e in $stillInstalled) {
            Write-DbaLog "Still detected: $($e.DisplayName) v$($e.DisplayVersion)" 'Yellow'
            if ($script:uninstallCompletedCleanly) {
                Write-DbaLog "  Uninstaller exited cleanly - a reboot is likely required to finish removal." 'Yellow'
            }
            else {
                Write-DbaLog "  The uninstall may have been cancelled." 'Yellow'
                Write-DbaLog "  Re-run this script to try again, or use: Settings -> Apps -> Uninstall" 'DarkGray'
            }
        }
    }
}

Write-DbaLog ''
Write-DbaLog 'Done.' 'Green'
Write-DbaLog "Log: $logFile"

﻿<#
.SYNOPSIS
Compare current sp_configure and key database settings against a saved baseline.

.DESCRIPTION
Run with -SaveBaseline to capture a point-in-time snapshot of sp_configure values and
key database properties to a JSON file. Run without it (or with -BaselineFile) to compare
current state against the saved baseline and report drift. Designed for change tracking:
run after maintenance windows to confirm only expected settings changed.

.NOTES
ScriptType  : hybrid
TargetScope : single server
RiskLevel   : SAFE

.EXAMPLE
# Save a baseline
.\Compare-ConfigurationBaseline.ps1 -ServerInstance PROD01 -SaveBaseline

# Compare current state to saved baseline
.\Compare-ConfigurationBaseline.ps1 -ServerInstance PROD01

# Compare to a specific baseline file
.\Compare-ConfigurationBaseline.ps1 -ServerInstance PROD01 -BaselineFile .\output-files\baselines\PROD01-baseline.json
#>

param(
    [string]$ServerInstance = '.',
    [switch]$SaveBaseline,
    [string]$BaselineFile,
    [ValidateSet('Table', 'Csv')]
    [string]$OutputFormat = 'Table',
    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'

$repoRoot   = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$runner     = Join-Path $repoRoot 'tools\local-sql\Invoke-RepoSql.ps1'
$baselineDir = Join-Path $repoRoot 'output-files\baselines'

$resolvedName = if ($ServerInstance -in @('.','localhost')) { $env:COMPUTERNAME } else { $ServerInstance }
$safeName     = ($resolvedName -replace '[\\,\.:]+', '-').Trim('-')
$defaultBaseline = Join-Path $baselineDir "$safeName-baseline.json"

# ── Collect current state ──────────────────────────────────────────────────────
function Get-CurrentSnapshot {
    param([string]$Server)

    $configSql = @"
SELECT name, CAST(value_in_use AS NVARCHAR(100)) AS current_value
FROM sys.configurations
ORDER BY name;
"@
    $dbPropSql = @"
SELECT name AS database_name,
       recovery_model_desc, compatibility_level,
       CAST(is_auto_shrink_on  AS VARCHAR(5)) AS auto_shrink,
       CAST(is_auto_close_on   AS VARCHAR(5)) AS auto_close,
       page_verify_option_desc,
       CAST(is_encrypted       AS VARCHAR(5)) AS is_tde
FROM sys.databases
WHERE database_id > 4
ORDER BY name;
"@
    $useModule = $null -ne (Get-Module -Name SqlServer -ListAvailable | Select-Object -First 1)

    $configRows = if ($useModule) {
        Invoke-Sqlcmd -ServerInstance $Server -Query $configSql -TrustServerCertificate
    } else {
        & sqlcmd -S $Server -Q $configSql -s "," -W -h -1 2>$null |
            ConvertFrom-Csv -Header 'name','current_value'
    }

    $dbRows = if ($useModule) {
        Invoke-Sqlcmd -ServerInstance $Server -Query $dbPropSql -TrustServerCertificate
    } else {
        & sqlcmd -S $Server -Q $dbPropSql -s "," -W -h -1 2>$null |
            ConvertFrom-Csv -Header 'database_name','recovery_model_desc','compatibility_level',
                                    'auto_shrink','auto_close','page_verify_option_desc','is_tde'
    }

    return @{
        captured_at    = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
        server_instance = $Server
        sp_configure   = @($configRows  | ForEach-Object { @{ name=$_.name; value=$_.current_value } })
        db_properties  = @($dbRows      | ForEach-Object {
            @{  database_name         = $_.database_name
                recovery_model        = $_.recovery_model_desc
                compatibility_level   = $_.compatibility_level
                auto_shrink           = $_.auto_shrink
                auto_close            = $_.auto_close
                page_verify           = $_.page_verify_option_desc
                tde                   = $_.is_tde
            }
        })
    }
}

$snapshot = Get-CurrentSnapshot -Server $ServerInstance

# ── Save baseline mode ─────────────────────────────────────────────────────────
if ($SaveBaseline) {
    if (-not (Test-Path $baselineDir)) { New-Item -ItemType Directory -Path $baselineDir -Force | Out-Null }
    $outFile = if ($BaselineFile) { $BaselineFile } else { $defaultBaseline }
    $snapshot | ConvertTo-Json -Depth 5 | Set-Content -Path $outFile -Encoding UTF8
    Write-Host "Baseline saved: $outFile" -ForegroundColor Green
    Write-Host "  Captured: $($snapshot.captured_at) | Server: $ServerInstance" -ForegroundColor Gray
    Write-Host "  sp_configure entries: $($snapshot.sp_configure.Count) | Databases: $($snapshot.db_properties.Count)" -ForegroundColor Gray
    return
}

# ── Compare mode ──────────────────────────────────────────────────────────────
$baseFile = if ($BaselineFile) { $BaselineFile } else { $defaultBaseline }

if (-not (Test-Path $baseFile)) {
    Write-Warning "No baseline found at: $baseFile"
    Write-Host "Run with -SaveBaseline to capture a baseline first." -ForegroundColor Yellow
    return
}

$baseline = Get-Content $baseFile -Raw | ConvertFrom-Json

Write-Host "Comparing $ServerInstance against baseline from $($baseline.captured_at)" -ForegroundColor Cyan

$diffs = [System.Collections.Generic.List[PSCustomObject]]::new()

# sp_configure drift
$baseConfig = @{}
$baseline.sp_configure | ForEach-Object { $baseConfig[$_.name] = $_.value }

foreach ($row in $snapshot.sp_configure) {
    $baseVal = $baseConfig[$row.name]
    if ($null -eq $baseVal) {
        $diffs.Add([PSCustomObject]@{
            section       = 'sp_configure'
            item          = $row.name
            baseline_value = '(not in baseline)'
            current_value  = $row.value
            change_type    = 'ADDED'
        })
    } elseif ($baseVal -ne $row.value) {
        $diffs.Add([PSCustomObject]@{
            section        = 'sp_configure'
            item           = $row.name
            baseline_value = $baseVal
            current_value  = $row.value
            change_type    = 'CHANGED'
        })
    }
}

# Database property drift
$baseDbMap = @{}
$baseline.db_properties | ForEach-Object { $baseDbMap[$_.database_name] = $_ }

foreach ($db in $snapshot.db_properties) {
    $base = $baseDbMap[$db.database_name]
    if ($null -eq $base) {
        $diffs.Add([PSCustomObject]@{
            section        = 'database'
            item           = $db.database_name
            baseline_value = '(new database)'
            current_value  = "recovery=$($db.recovery_model) compat=$($db.compatibility_level)"
            change_type    = 'NEW_DB'
        })
        continue
    }
    $props = @('recovery_model','compatibility_level','auto_shrink','auto_close','page_verify','tde')
    foreach ($p in $props) {
        if ($base.$p -ne $db.$p) {
            $diffs.Add([PSCustomObject]@{
                section        = "database.$($db.database_name)"
                item           = $p
                baseline_value = $base.$p
                current_value  = $db.$p
                change_type    = 'CHANGED'
            })
        }
    }
}

if ($diffs.Count -eq 0) {
    Write-Host "`nNo configuration drift detected vs baseline from $($baseline.captured_at)" -ForegroundColor Green
    return
}

Write-Host "`n$($diffs.Count) difference(s) found:" -ForegroundColor Yellow

if ($OutputFormat -eq 'Csv') {
    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFile   = if ($OutputPath) { $OutputPath } else {
        $outDir = Join-Path $repoRoot 'output-files\reviews\reporting'
        if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
        Join-Path $outDir "Compare-ConfigurationBaseline-$safeName-$timestamp.csv"
    }
    $diffs | Export-Csv -Path $outFile -NoTypeInformation -Encoding UTF8
    Write-Host "Output saved: $outFile" -ForegroundColor Green
} else {
    $diffs | Format-Table section, item, baseline_value, current_value, change_type -AutoSize
}

﻿<#
.SYNOPSIS
Projects days-to-full for databases and drives from collector historical data.

.DESCRIPTION
Reads database-growth and disk-space collector CSVs and computes a linear growth rate
over the last 30/60/90 days per database and per drive. Projects how many days until
the drive fills at the current rate. Flags anything projected to fill within 30 days.

Requires the database-growth and storage-io collectors to have been running for at
least 14 days to produce a meaningful projection.

.NOTES
ScriptType  : hybrid
TargetScope : single server
RiskLevel   : SAFE

.EXAMPLE
.\Get-CapacityProjection.ps1

.\Get-CapacityProjection.ps1 -LookbackDays 60 -OutputFormat Csv
#>

param(
    [int]$LookbackDays    = 30,
    [int]$WarnDaysToFull  = 30,
    [int]$CritDaysToFull  = 14,
    [ValidateSet('Table', 'Csv')]
    [string]$OutputFormat = 'Table',
    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'

$repoRoot   = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$collectDir = Join-Path $repoRoot 'output-files\collectors'

function Get-LinearGrowthRate {
    param([double[]]$Sizes, [int[]]$DayOffsets)
    # Simple linear regression: slope = (n*Σxy - Σx*Σy) / (n*Σx² - (Σx)²)
    $n   = $Sizes.Count
    if ($n -lt 2) { return 0 }
    $sumX   = ($DayOffsets | Measure-Object -Sum).Sum
    $sumY   = ($Sizes      | Measure-Object -Sum).Sum
    $sumXY  = 0; $sumX2 = 0
    for ($i = 0; $i -lt $n; $i++) {
        $sumXY += $DayOffsets[$i] * $Sizes[$i]
        $sumX2 += $DayOffsets[$i] * $DayOffsets[$i]
    }
    $denom = $n * $sumX2 - $sumX * $sumX
    if ($denom -eq 0) { return 0 }
    return ($n * $sumXY - $sumX * $sumY) / $denom
}

$results = [System.Collections.Generic.List[PSCustomObject]]::new()
$cutoff  = (Get-Date).AddDays(-$LookbackDays)

# ── Database growth projection ─────────────────────────────────────────────────
$dbGrowthDir = Join-Path $collectDir 'database-growth'
if (Test-Path $dbGrowthDir) {
    $csvFiles = Get-ChildItem $dbGrowthDir -Filter '*.csv' | Sort-Object LastWriteTime

    if ($csvFiles) {
        $allRows = $csvFiles | ForEach-Object { Import-Csv $_.FullName } |
                   Where-Object {
                       $_.collected_at -and
                       [datetime]::TryParse($_.collected_at, [ref]$null) -and
                       [datetime]$_.collected_at -ge $cutoff
                   }

        $dbGroups = $allRows | Group-Object database_name

        foreach ($grp in $dbGroups) {
            $pts = $grp.Group |
                   Sort-Object { [datetime]$_.collected_at } |
                   Select-Object collected_at,
                       @{n='size_mb'; e={ [double]((@($_.data_size_mb, $_.total_size_mb, 0) | Where-Object { $null -ne $_ })[0]) }}

            if ($pts.Count -lt 3) { continue }

            $refDate    = [datetime]$pts[0].collected_at
            $dayOffsets = $pts | ForEach-Object { ([datetime]$_.collected_at - $refDate).TotalDays }
            $sizes      = $pts | ForEach-Object { $_.size_mb }

            $ratePerDay  = Get-LinearGrowthRate -Sizes $sizes -DayOffsets $dayOffsets
            $latestSize  = $sizes[-1]
            $daysToFull  = $null
            $status      = 'OK'

            if ($ratePerDay -le 0) {
                $status = 'OK - stable or shrinking'
            } else {
                # Days until some threshold — use disk free if available, else just show rate
                $status = 'INFO - growing at ' + [math]::Round($ratePerDay, 1) + ' MB/day'
                if ($ratePerDay -gt 0) {
                    $daysToFull = $null  # set per-drive below
                }
            }

            $results.Add([PSCustomObject]@{
                type             = 'DATABASE'
                name             = $grp.Name
                drive            = $null
                current_size_mb  = [math]::Round($latestSize, 1)
                free_mb          = $null
                growth_mb_per_day = [math]::Round($ratePerDay, 2)
                data_points      = $pts.Count
                lookback_days    = $LookbackDays
                days_to_full     = $null
                status           = $status
            })
        }
    }
    else {
        Write-Warning "No database-growth collector CSVs found in $dbGrowthDir"
    }
}
else {
    Write-Warning "Collector directory not found: $dbGrowthDir - install the DatabaseGrowth collector job first (sql\collectors\Generate-CollectorJob-DatabaseGrowth.sql)."
}

# ── Disk space projection ──────────────────────────────────────────────────────
$diskDir = Join-Path $collectDir 'storage-io'
if (Test-Path $diskDir) {
    $csvFiles = Get-ChildItem $diskDir -Filter '*.csv' | Sort-Object LastWriteTime

    if ($csvFiles) {
        $allRows = $csvFiles | ForEach-Object { Import-Csv $_.FullName } |
                   Where-Object {
                       $_.collected_at -and
                       [datetime]::TryParse($_.collected_at, [ref]$null) -and
                       [datetime]$_.collected_at -ge $cutoff
                   }

        # Group by drive letter or volume name
        $driveCol = if ($allRows | Select-Object -First 1 | Get-Member -Name 'drive_letter') { 'drive_letter' }
                    elseif ($allRows | Select-Object -First 1 | Get-Member -Name 'volume')    { 'volume' }
                    else { 'logical_disk' }

        $driveGroups = $allRows | Where-Object { $_.$driveCol } | Group-Object $driveCol

        foreach ($grp in $driveGroups) {
            $pts = $grp.Group |
                   Sort-Object { [datetime]$_.collected_at } |
                   Select-Object collected_at,
                       @{n='free_mb'; e={ [double]((@($_.free_space_mb, $_.free_mb, 0) | Where-Object { $null -ne $_ })[0]) }},
                       @{n='total_mb'; e={ [double]((@($_.total_size_mb, $_.total_mb, 0) | Where-Object { $null -ne $_ })[0]) }}

            if ($pts.Count -lt 3) { continue }

            $refDate    = [datetime]$pts[0].collected_at
            $dayOffsets = $pts | ForEach-Object { ([datetime]$_.collected_at - $refDate).TotalDays }
            $freeSizes  = $pts | ForEach-Object { $_.free_mb }

            # Negative rate means free space is shrinking (disk filling)
            $ratePerDay  = Get-LinearGrowthRate -Sizes $freeSizes -DayOffsets $dayOffsets
            $latestFree  = $freeSizes[-1]
            $latestTotal = ($pts[-1]).total_mb

            $daysToFull = $null
            $status     = 'OK'

            if ($ratePerDay -lt 0 -and $latestFree -gt 0) {
                $daysToFull = [math]::Round($latestFree / [math]::Abs($ratePerDay), 0)
                $status = if ($daysToFull -le $CritDaysToFull) {
                    "CRITICAL - drive fills in ~$daysToFull days at current rate"
                } elseif ($daysToFull -le $WarnDaysToFull) {
                    "WARN - drive fills in ~$daysToFull days"
                } else {
                    "OK - ~$daysToFull days of capacity remaining"
                }
            } elseif ($ratePerDay -ge 0) {
                $status = 'OK - free space stable or increasing'
            }

            $results.Add([PSCustomObject]@{
                type              = 'DRIVE'
                name              = $grp.Name
                drive             = $grp.Name
                current_size_mb   = [math]::Round($latestTotal, 1)
                free_mb           = [math]::Round($latestFree, 1)
                growth_mb_per_day = [math]::Round($ratePerDay, 2)  # negative = filling
                data_points       = $pts.Count
                lookback_days     = $LookbackDays
                days_to_full      = $daysToFull
                status            = $status
            })
        }
    }
}
else {
    Write-Warning "Collector directory not found: $diskDir - install the StorageIO collector job first (sql\collectors\Generate-CollectorJob-StorageIO.sql)."
}

if ($results.Count -eq 0) {
    Write-Warning "No projection data available. Ensure collectors have been running for at least 14 days."
    return
}

Write-Host "Capacity Projection - $LookbackDays-day lookback ($($results.Count) items)" -ForegroundColor Cyan

$sorted = $results | Sort-Object {
    switch -Wildcard ($_.status) {
        'CRITICAL*' { 1 }
        'WARN*'     { 2 }
        default     { 3 }
    }
}, { (@($_.days_to_full, 9999) | Where-Object { $null -ne $_ })[0] }

if ($OutputFormat -eq 'Csv') {
    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFile   = if ($OutputPath) { $OutputPath } else {
        $outDir = Join-Path $repoRoot 'output-files\reviews\reporting'
        if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
        Join-Path $outDir "Get-CapacityProjection-$timestamp.csv"
    }
    $sorted | Export-Csv -Path $outFile -NoTypeInformation -Encoding UTF8
    Write-Host "Output saved: $outFile" -ForegroundColor Green
} else {
    $sorted | Format-Table type, name, current_size_mb, free_mb, growth_mb_per_day,
                            data_points, days_to_full, status -AutoSize
}

﻿<#
.SYNOPSIS
Runs a full instance assessment and generates a structured markdown report.

.NOTES
ScriptType   : runner
TargetScope  : single server
RiskLevel    : SAFE

.DESCRIPTION
Orchestrates the healthcheck collection, configuration scoring, and findings review,
then generates a formatted markdown report suitable for a client handover or ownership review.

Reuses all existing monitoring scripts — adds a configuration score and report document.

Output: output-files\assessment\<server>-<timestamp>.md

Workflow:
  1. Runs Invoke-HealthCheckCollection.ps1 (or reads an existing folder via -FolderPath)
  2. Runs Get-InstanceConfigurationScore.sql — scores ~16 key configuration checks
  3. Runs Review-HealthCheckOutput.ps1 — generates findings.csv from thresholds
  4. Reads CSVs and writes a structured markdown report

.PARAMETER ServerInstance
SQL Server instance to query. Defaults to '.'.

.PARAMETER FolderPath
Path to an existing healthcheck CSV folder. If omitted, a fresh collection is run.

.PARAMETER AssessedBy
Name to include in the report header. Defaults to the current Windows user.

.PARAMETER OutputRoot
Parent folder for the report file. Defaults to output-files\assessment under the repo root.

.EXAMPLE
.\powershell\reporting\Invoke-AssessmentReport.ps1 -ServerInstance PROD01\SQL2019

.EXAMPLE
# Reuse an existing collection folder
.\powershell\reporting\Invoke-AssessmentReport.ps1 -FolderPath ".\output-files\healthcheck\PROD01-20260531-140000" -AssessedBy "Peter Whyte"
#>

param(
    [string]$ServerInstance = '.',
    [string]$FolderPath,
    [string]$AssessedBy,
    [string]$OutputRoot
)

$ErrorActionPreference = 'Stop'

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$runner   = Join-Path $repoRoot 'tools\local-sql\Invoke-RepoSql.ps1'

if (-not $AssessedBy) { $AssessedBy = $env:USERNAME }
if (-not $OutputRoot) { $OutputRoot = Join-Path $repoRoot 'output-files\assessment' }

New-Item -ItemType Directory -Path $OutputRoot -Force | Out-Null

Write-Host ''
Write-Host '============================================' -ForegroundColor Cyan
Write-Host '  SQL Server Assessment Report' -ForegroundColor Cyan
Write-Host '============================================' -ForegroundColor Cyan

# ── Step 1: Collect data ────────────────────────────────────────────────────
if ($FolderPath) {
    if (-not (Test-Path -LiteralPath $FolderPath)) { throw "Folder not found: $FolderPath" }
    Write-Host "  Using existing folder: $FolderPath" -ForegroundColor Yellow
}
else {
    Write-Host "  Server     : $ServerInstance"
    Write-Host "  Step 1/3   : Running healthcheck collection..." -ForegroundColor DarkGray
    $hcScript = Join-Path $repoRoot 'powershell\reporting\Invoke-HealthCheckCollection.ps1'
    & $hcScript -ServerInstance $ServerInstance -Quiet
    $hcRoot   = Join-Path $repoRoot 'output-files\healthcheck'
    $FolderPath = (Get-ChildItem -LiteralPath $hcRoot -Directory | Sort-Object LastWriteTime -Descending | Select-Object -First 1).FullName
    Write-Host "  Collection : $FolderPath" -ForegroundColor Green
}

# ── Step 2: Configuration score ─────────────────────────────────────────────
Write-Host "  Step 2/3   : Running configuration score..." -ForegroundColor DarkGray
$scoreSql = Join-Path $repoRoot 'sql\monitoring\instance\Get-InstanceConfigurationScore.sql'
$scoreCsv = Join-Path $FolderPath 'score.csv'
if (Test-Path -LiteralPath $scoreSql) {
    try {
        & $runner -ScriptPath $scoreSql -ServerInstance $ServerInstance -Database 'master' `
                  -OutputFormat 'Csv' -OutputPath $scoreCsv *>$null
    }
    catch { Write-Warning "Config score failed: $_" }
}

# ── Step 3: Findings ─────────────────────────────────────────────────────────
Write-Host "  Step 3/3   : Generating findings..." -ForegroundColor DarkGray
$findingsCsv = Join-Path $FolderPath 'findings.csv'
if (-not (Test-Path -LiteralPath $findingsCsv)) {
    $reviewScript = Join-Path $repoRoot 'powershell\reporting\Review-HealthCheckOutput.ps1'
    & $reviewScript -FolderPath $FolderPath *>$null
}

# ── Read CSVs ────────────────────────────────────────────────────────────────
function Read-Safe { param([string]$Name)
    $p = Join-Path $FolderPath "$Name.csv"
    if (Test-Path -LiteralPath $p) { return @(Import-Csv -LiteralPath $p -ErrorAction SilentlyContinue) }
    return @()
}

$serverInfo  = Read-Safe 'server-info'
$osHardware  = Read-Safe 'os-hardware'
$dbHealth    = Read-Safe 'database-health'
$dbSizes     = Read-Safe 'database-sizes'
$backupTimes = Read-Safe 'backup-times'
$diskSpace   = Read-Safe 'disk-space'
$findings    = Read-Safe 'findings'
$score       = Read-Safe 'score'

# ── Derive headline values ────────────────────────────────────────────────────
$sv          = if ($serverInfo.Count) { $serverInfo[0] } else { $null }
$hw          = if ($osHardware.Count)  { $osHardware[0]  } else { $null }

$serverName   = if ($sv) { $sv.server_name }          else { $ServerInstance }
$edition      = if ($hw) { $hw.sql_edition }           else { if ($sv) { $sv.edition } else { 'Unknown' } }
$sqlVersion   = if ($hw) { $hw.sql_version }           else { if ($sv) { $sv.product_version } else { 'Unknown' } }
$sqlLevel     = if ($hw) { "$($hw.sql_product_level) $($hw.sql_cu_level)".Trim() } else { '' }
$osRelease    = if ($hw) { $hw.os_release }            else { 'Unknown' }
$cpuCount     = if ($hw) { $hw.logical_cpu_count }     else { 'Unknown' }
$ramGb        = if ($hw) { $hw.physical_memory_gb }    else { 'Unknown' }
$uptimeDays   = if ($hw) { $hw.uptime_days }           else { 'Unknown' }
$isClustered  = if ($hw) { if ($hw.is_clustered -eq '1') { 'Yes (FCI)' } else { 'No' } } else { 'Unknown' }

$critCount    = @($findings | Where-Object Severity -eq 'CRITICAL').Count
$warnCount    = @($findings | Where-Object Severity -eq 'WARNING').Count
$infoCount    = @($findings | Where-Object Severity -eq 'INFO').Count
$userDbCount  = @($dbHealth | Where-Object { $_.database_name -notin @('master','model','msdb','tempdb') }).Count

# Score calculation: PASS = full, WARN = half, FAIL = none; INFO is neutral
$scoreItems   = @($score | Where-Object { $_.status -in @('PASS','WARN','FAIL') })
$passCount    = @($score | Where-Object status -eq 'PASS').Count
$warnSCount   = @($score | Where-Object status -eq 'WARN').Count
$failCount    = @($score | Where-Object status -eq 'FAIL').Count
$totalItems   = $scoreItems.Count
$instanceScore = if ($totalItems -gt 0) {
    [int](($passCount + ($warnSCount * 0.5)) / $totalItems * 100)
} else { 0 }

$scoreLabel = switch ($true) {
    ($instanceScore -ge 90) { 'Good' }
    ($instanceScore -ge 70) { 'Fair' }
    ($instanceScore -ge 50) { 'Needs Attention' }
    default                 { 'Critical' }
}

# Folder timestamp for collection date
$folderLeaf    = Split-Path -Leaf $FolderPath
$collectedDate = if ($folderLeaf -match '(\d{8}-\d{6})$') {
    [DateTime]::ParseExact($Matches[1], 'yyyyMMdd-HHmmss', $null).ToString('yyyy-MM-dd HH:mm')
} else { (Get-Date).ToString('yyyy-MM-dd HH:mm') }

# ── Build markdown report ─────────────────────────────────────────────────────
$lines = [System.Collections.Generic.List[string]]::new()

$lines.Add("# SQL Server Instance Assessment")
$lines.Add("")
$lines.Add("| | |")
$lines.Add("|-|-|")
$lines.Add("| **Server** | $serverName |")
$lines.Add("| **SQL Version** | $sqlVersion $sqlLevel |")
$lines.Add("| **Edition** | $edition |")
$lines.Add("| **OS** | $osRelease |")
$lines.Add("| **CPU** | $cpuCount logical processors |")
$lines.Add("| **RAM** | $ramGb GB |")
$lines.Add("| **Clustered** | $isClustered |")
$lines.Add("| **Uptime** | $uptimeDays days |")
$lines.Add("| **User databases** | $userDbCount |")
$lines.Add("| **Data collected** | $collectedDate |")
$lines.Add("| **Assessed by** | $AssessedBy |")
$lines.Add("")
$lines.Add("---")
$lines.Add("")
$lines.Add("## Executive Summary")
$lines.Add("")
$lines.Add("### Instance Score: $instanceScore / 100 - $scoreLabel")
$lines.Add("")
$lines.Add("| Severity | Count |")
$lines.Add("|----------|-------|")
if ($totalItems -gt 0) {
    $lines.Add("| FAIL (config) | $failCount |")
    $lines.Add("| WARN (config) | $warnSCount |")
    $lines.Add("| PASS (config) | $passCount |")
}
$lines.Add("| CRITICAL (findings) | $critCount |")
$lines.Add("| WARNING (findings) | $warnCount |")
$lines.Add("| INFO (findings) | $infoCount |")
$lines.Add("")

# Critical findings summary
$criticalFindings = @($findings | Where-Object Severity -eq 'CRITICAL')
if ($criticalFindings.Count -gt 0) {
    $lines.Add("### Critical Issues - Resolve Before Handover")
    $lines.Add("")
    foreach ($f in $criticalFindings) {
        $lines.Add("- **[$($f.Category)]** $($f.Subject) - $($f.Detail)")
    }
    $lines.Add("")
}

# FAIL config items summary
$failItems = @($score | Where-Object status -eq 'FAIL')
if ($failItems.Count -gt 0) {
    $lines.Add("### Configuration Failures")
    $lines.Add("")
    foreach ($f in $failItems) {
        $lines.Add("- **[$($f.weight)]** $($f.check_name) - $($f.finding)")
    }
    $lines.Add("")
}

$lines.Add("---")
$lines.Add("")

# ── Configuration score table ─────────────────────────────────────────────────
if ($score.Count -gt 0) {
    $lines.Add("## Configuration Score")
    $lines.Add("")
    $lines.Add("| Check | Weight | Status | Finding |")
    $lines.Add("|-------|--------|--------|---------|")
    foreach ($row in $score) {
        $statusIcon = switch ($row.status) {
            'PASS' { 'PASS' }
            'WARN' { 'WARN' }
            'FAIL' { 'FAIL' }
            'INFO' { 'INFO' }
            default { $row.status }
        }
        $finding = $row.finding -replace '\|', '/' -replace "`r?`n", ' '
        $lines.Add("| $($row.check_name) | $($row.weight) | $statusIcon | $finding |")
    }
    $lines.Add("")
    $lines.Add("---")
    $lines.Add("")
}

# ── All findings ────────────────────────────────────────────────────────────
if ($findings.Count -gt 0) {
    $lines.Add("## Findings")
    $lines.Add("")
    foreach ($sev in @('CRITICAL','WARNING','INFO')) {
        $group = @($findings | Where-Object Severity -eq $sev)
        if ($group.Count -eq 0) { continue }
        $lines.Add("### $sev")
        $lines.Add("")
        $lines.Add("| Category | Subject | Detail |")
        $lines.Add("|----------|---------|--------|")
        foreach ($f in $group) {
            $detail = $f.Detail -replace '\|', '/' -replace "`r?`n", ' '
            $lines.Add("| $($f.Category) | $($f.Subject) | $detail |")
        }
        $lines.Add("")
    }
    $lines.Add("---")
    $lines.Add("")
}

# ── Database inventory ────────────────────────────────────────────────────────
if ($dbHealth.Count -gt 0) {
    $lines.Add("## Database Inventory")
    $lines.Add("")
    $lines.Add("| Database | State | Recovery | Auto-Shrink | Last Full Backup |")
    $lines.Add("|----------|-------|----------|-------------|-----------------|")
    foreach ($db in ($dbHealth | Where-Object { $_.database_name -notin @('master','model','msdb','tempdb') } | Sort-Object database_name)) {
        $lastFull = ($backupTimes | Where-Object database_name -eq $db.database_name | Select-Object -First 1).last_full_backup
        if (-not $lastFull) { $lastFull = 'None' }
        $shrink = if ($db.is_auto_shrink_on -in @('True','1','YES')) { 'YES' } else { 'No' }
        $lines.Add("| $($db.database_name) | $($db.state_desc) | $($db.recovery_model_desc) | $shrink | $lastFull |")
    }
    $lines.Add("")
    $lines.Add("---")
    $lines.Add("")
}

# ── Storage ───────────────────────────────────────────────────────────────────
if ($diskSpace.Count -gt 0) {
    $lines.Add("## Storage")
    $lines.Add("")
    $lines.Add("| Volume | Total (GB) | Free (GB) | Free % |")
    $lines.Add("|--------|-----------|-----------|---------|")
    foreach ($vol in $diskSpace) {
        $freePct = if ($vol.free_gb -and $vol.total_gb -and [double]$vol.total_gb -gt 0) {
            "$([Math]::Round([double]$vol.free_gb / [double]$vol.total_gb * 100, 1))%"
        } else { 'N/A' }
        $volName = if ($vol.PSObject.Properties['volume_mount_point']) { $vol.volume_mount_point }
                   elseif ($vol.PSObject.Properties['mount_point']) { $vol.mount_point }
                   else { 'Unknown' }
        $lines.Add("| $volName | $($vol.total_gb) | $($vol.free_gb) | $freePct |")
    }
    $lines.Add("")
    $lines.Add("---")
    $lines.Add("")
}

# ── Recommendations ──────────────────────────────────────────────────────────
$recLines = [System.Collections.Generic.List[string]]::new()
$critRecs  = @($score | Where-Object { $_.status -eq 'FAIL' -and $_.weight -in @('CRITICAL','HIGH') } | Sort-Object { @('CRITICAL','HIGH','MEDIUM','LOW').IndexOf($_.weight) })
$warnRecs  = @($score | Where-Object { $_.status -in @('FAIL','WARN') -and $_.weight -eq 'MEDIUM' })
$lowRecs   = @($score | Where-Object { $_.status -in @('FAIL','WARN') -and $_.weight -eq 'LOW' })

$lines.Add("## Recommendations")
$lines.Add("")
if ($critRecs.Count -gt 0) {
    $lines.Add("### Immediate")
    $lines.Add("")
    $n = 1
    foreach ($r in $critRecs) {
        $rec = $r.recommendation -replace '\|', '/' -replace "`r?`n", ' '
        $lines.Add("$n. **$($r.check_name)** - $rec")
        $n++
    }
    $lines.Add("")
}
if ($warnRecs.Count -gt 0) {
    $lines.Add("### Short-Term")
    $lines.Add("")
    $n = 1
    foreach ($r in $warnRecs) {
        $rec = $r.recommendation -replace '\|', '/' -replace "`r?`n", ' '
        $lines.Add("$n. **$($r.check_name)** - $rec")
        $n++
    }
    $lines.Add("")
}
if ($lowRecs.Count -gt 0) {
    $lines.Add("### Best Practice")
    $lines.Add("")
    $n = 1
    foreach ($r in $lowRecs) {
        $rec = $r.recommendation -replace '\|', '/' -replace "`r?`n", ' '
        $lines.Add("$n. **$($r.check_name)** - $rec")
        $n++
    }
    $lines.Add("")
}

$lines.Add("---")
$lines.Add("")
$lines.Add("*Report generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm') | Data collected: $collectedDate | Source: $FolderPath*")

# ── Write report ──────────────────────────────────────────────────────────────
$safeName   = ($serverName -replace '[\\/:*?"<>|]', '-').Trim('-')
$timestamp  = Get-Date -Format 'yyyyMMdd-HHmmss'
$reportPath = Join-Path $OutputRoot "$safeName-$timestamp.md"

$lines -join "`n" | Set-Content -LiteralPath $reportPath -Encoding UTF8

Write-Host ''
Write-Host ('─' * 64) -ForegroundColor DarkCyan
Write-Host "  Score   : $instanceScore/100 - $scoreLabel" -ForegroundColor $(if ($instanceScore -ge 80) { 'Green' } elseif ($instanceScore -ge 60) { 'Yellow' } else { 'Red' })
Write-Host "  CRITICAL: $critCount  |  WARNING: $warnCount  |  FAIL config: $failCount"
Write-Host ''
Write-Host "  Report  : $reportPath" -ForegroundColor Green
Write-Host "  Data    : $FolderPath" -ForegroundColor DarkGray
Write-Host ('─' * 64) -ForegroundColor DarkCyan
Write-Host ''

﻿<#
.SYNOPSIS
Runs a full DBA health-check collection and saves each result as a named CSV in a timestamped folder.

.NOTES
ScriptType   : PowerShell-only
TargetScope  : single server
RiskLevel    : SAFE
Purpose      : Collect all key health-check data in one pass for offline review or archiving.

.DESCRIPTION
Orchestrates the core monitoring and inventory SQL scripts against a single SQL Server instance.
Each script's output is saved as a named CSV under output-files\healthcheck\<server>-<timestamp>\.

Run this first, then pass the output folder to Review-HealthCheckOutput.ps1 to surface findings.

Scripts collected:
  server-info           - SQL version, edition, instance name
  os-hardware           - OS release, CPU count, RAM, uptime
  database-health       - database state, recovery model, auto-shrink flags
  database-sizes        - data/log sizes and free space per database
  database-files        - per-file paths, sizes, growth settings
  backup-times          - last full/diff/log backup per database
  backup-coverage       - databases with missing or stale backups (with status flag)
  tlog-usage            - transaction log size and space used
  memory-config         - max server memory, current committed, buffer pool
  wait-stats            - top wait types since last restart (benign waits filtered)
  active-sessions       - currently connected users and requests
  tempdb-usage          - tempdb file usage per file with free space
  job-failures          - SQL Agent job failures from the last 7 days
  recent-errors         - error log entries from the last 24 hours
  dbcc-checkdb          - last successful DBCC CHECKDB per database
  suspect-pages         - any pages in msdb.dbo.suspect_pages
  io-usage              - per-database I/O totals with read/write latency
  disk-space            - volume mount points with total/used/free GB (SQL-hosting drives only)
  growth-risk           - databases flagged OK / NEAR_LIMIT / AT_LIMIT vs configured file limits
  security-surface-area - xp_cmdshell, CLR, Database Mail enabled state
  weak-logins           - SQL logins with policy/expiration off or sa enabled
  missing-indexes       - top missing index candidates ranked by DMV impact score (resets on restart)
  tempdb-config         - TempDB file count, sizing parity, and autogrowth type
  plan-cache            - plan cache composition — single-use plan ratio and ad-hoc bloat
  linked-server-security - linked server login mappings with risk level assessment
  vlf-count             - virtual log file count per database (high counts degrade recovery)
  maintenance-jobs      - DBA maintenance job deployment and last-run status
  failed-logins         - failed login attempts from current error log with lockout status
  query-store-status    - Query Store state (enabled, READ_ONLY, fill %) per database
  extended-events       - active XE sessions — targets and estimated overhead
  cdc-and-ct            - CDC and Change Tracking enabled databases with retention settings
  service-broker        - Service Broker enabled databases with queue/transmission health
  sysadmin-members      - members of the sysadmin fixed server role
  instance-config       - full sp_configure snapshot with non-default flags
  top-cpu-queries       - top 20 CPU-consuming queries from the plan cache
  agent-jobs-overview   - all SQL Agent jobs with schedule and last-run status
  orphaned-users        - database users with no matching server login
  certificate-expiry    - certificates with expiry status and key-backup state
  autogrowth-history    - recent autogrowth events from the default trace
  ag-replica-state      - AG replica health, connection and synchronization state
  ag-failover-readiness - per-database failover readiness, redo queues, estimated RTO
  ag-latency            - AG synchronization timing, queue sizes and rates
  mirroring-endpoint-health - mirroring/AG endpoint state, port and authentication
  replication-status    - publications and subscriptions from the distribution database
  last-node-blip        - failover-related error log entries + instance start time (FCI)

.PARAMETER ServerInstance
SQL Server instance to query. Defaults to '.'.

.PARAMETER OutputRoot
Parent folder for healthcheck output folders. Defaults to output-files\healthcheck under the repo root.

.PARAMETER OutputFolder
Exact output folder to write into (created if missing). Overrides OutputRoot and the generated
<server>-<timestamp> name. Used by the web UI so it knows the folder to poll before the run starts.

.EXAMPLE
pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Invoke-HealthCheckCollection.ps1

.EXAMPLE
pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Invoke-HealthCheckCollection.ps1 -ServerInstance MYSERVER\INST01

.EXAMPLE
# Collect then immediately review
$folder = pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Invoke-HealthCheckCollection.ps1 -ServerInstance . 6>&1 | Select-String 'Output folder' | ForEach-Object { $_.Line -replace '.*: ' }
pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Review-HealthCheckOutput.ps1 -FolderPath $folder
#>

param(
    [string]$ServerInstance = '.',
    [string]$OutputRoot,
    [string]$OutputFolder,
    [switch]$Quiet
)

$ErrorActionPreference = 'Stop'

# Respect the session default set by Initialize-Environment or Set-SqlConnection
if ($ServerInstance -eq '.' -and $env:DBASCRIPTS_SERVER) { $ServerInstance = $env:DBASCRIPTS_SERVER }

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$runner   = Join-Path $repoRoot 'tools\local-sql\Invoke-RepoSql.ps1'

if (-not (Test-Path -LiteralPath $runner)) { throw "Runner not found: $runner" }

$env:DBASCRIPTS_BATCH = '1'  # tells Invoke-RepoSql not to open a browser tab per script

if (-not $OutputRoot) {
    $OutputRoot = Join-Path $repoRoot 'output-files\healthcheck'
}

if ($OutputFolder) {
    $outFolder = $OutputFolder
} else {
    $safeName  = ($ServerInstance -replace '[\\/:*?"<>|]', '-').Trim('-')
    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFolder = Join-Path $OutputRoot "$safeName-$timestamp"
}
New-Item -ItemType Directory -Path $outFolder -Force | Out-Null

# Per-script progress manifest — rewritten after every status change so pollers
# (web UI /api/status) always see a complete, current picture. Temp+move keeps
# each write atomic for concurrent readers.
function Write-HcManifest([object[]]$Rows, [string]$Folder) {
    $tmp = Join-Path $Folder '.manifest.tmp'
    $Rows | Export-Csv -LiteralPath $tmp -NoTypeInformation
    Move-Item -LiteralPath $tmp -Destination (Join-Path $Folder 'manifest.csv') -Force
}

try {

Write-Host ''
Write-Host '============================================' -ForegroundColor Cyan
Write-Host '  DBA Health Check Collection' -ForegroundColor Cyan
Write-Host '============================================' -ForegroundColor Cyan
Write-Host "  Server : $ServerInstance"
Write-Host "  Output : $outFolder"
Write-Host "  Time   : $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
Write-Host '--------------------------------------------'
Write-Host ''

# Each entry: Label (becomes CSV filename) and relative path to the SQL script.
# Paths are tried in order — first match wins, remaining are skipped.
$scripts = @(
    [PSCustomObject]@{
        Label = 'server-info'
        Paths = @('sql\inventory\Get-VersionAndEdition.sql')
    }
    [PSCustomObject]@{
        Label = 'os-hardware'
        Paths = @('sql\inventory\Get-OsAndHardwareInfo.sql')
    }
    [PSCustomObject]@{
        Label = 'database-health'
        Paths = @('sql\monitoring\databases\Get-DatabaseHealth.sql')
    }
    [PSCustomObject]@{
        Label = 'database-sizes'
        Paths = @('sql\monitoring\disk-space\Get-DatabaseSizesAndFreeSpace.sql')
    }
    [PSCustomObject]@{
        Label = 'database-files'
        Paths = @('sql\monitoring\disk-space\Get-DatabaseFilesDetail.sql')
    }
    [PSCustomObject]@{
        Label = 'backup-times'
        Paths = @('sql\backups\Get-LastDatabaseBackupTimes.sql')
    }
    [PSCustomObject]@{
        Label = 'backup-coverage'
        Paths = @('sql\backups\Get-BackupCoverage.sql')
    }
    [PSCustomObject]@{
        Label = 'tlog-usage'
        Paths = @('sql\monitoring\disk-space\Get-TransactionLogSizeAndUsage.sql')
    }
    [PSCustomObject]@{
        Label = 'memory-config'
        Paths = @('sql\monitoring\instance\Get-MemoryConfigurationAndUsage.sql')
    }
    [PSCustomObject]@{
        Label = 'wait-stats'
        Paths = @('sql\performance\Get-WaitStatistics.sql')
    }
    [PSCustomObject]@{
        Label = 'active-sessions'
        Paths = @('sql\performance\active-sessions\Get-ActiveSessions.sql')
    }
    [PSCustomObject]@{
        Label = 'tempdb-usage'
        Paths = @('sql\monitoring\tempdb\Get-TempdbUsage.sql')
    }
    [PSCustomObject]@{
        Label = 'job-failures'
        Paths = @('sql\monitoring\jobs\Get-SqlAgentJobFailureSummary.sql')
    }
    [PSCustomObject]@{
        Label = 'recent-errors'
        Paths = @('sql\monitoring\error-log\Get-RecentErrorLogEntries.sql')
    }
    [PSCustomObject]@{
        Label = 'dbcc-checkdb'
        Paths = @('sql\monitoring\databases\Get-LastDbccCheckdb.sql')
    }
    [PSCustomObject]@{
        Label = 'suspect-pages'
        Paths = @('sql\monitoring\databases\Get-SuspectPages.sql')
    }
    [PSCustomObject]@{
        Label = 'io-usage'
        Paths = @('sql\performance\Get-DatabaseIoUsage.sql')
    }
    [PSCustomObject]@{
        Label = 'disk-space'
        Paths = @('sql\monitoring\disk-space\Get-DiskSpace.sql')
    }
    [PSCustomObject]@{
        Label = 'growth-risk'
        Paths = @('sql\monitoring\disk-space\Get-DatabaseGrowthRisk.sql')
    }
    [PSCustomObject]@{
        Label = 'security-surface-area'
        Paths = @('sql\security\Get-DatabaseMailAndXpCmdShell.sql')
    }
    [PSCustomObject]@{
        Label = 'weak-logins'
        Paths = @('sql\security\access\Get-WeakLoginSettings.sql')
    }
    [PSCustomObject]@{
        Label = 'missing-indexes'
        Paths = @('sql\performance\indexes\Get-MissingIndexes.sql')
    }
    [PSCustomObject]@{
        Label = 'tempdb-config'
        Paths = @('sql\monitoring\tempdb\Get-TempDbConfiguration.sql')
    }
    [PSCustomObject]@{
        Label = 'plan-cache'
        Paths = @('sql\performance\queries\Get-PlanCacheHealth.sql')
    }
    [PSCustomObject]@{
        Label = 'linked-server-security'
        Paths = @('sql\security\Get-LinkedServerSecurity.sql')
    }
    [PSCustomObject]@{
        Label = 'vlf-count'
        Paths = @('sql\monitoring\disk-space\Get-VlfCount.sql')
    }
    [PSCustomObject]@{
        Label    = 'maintenance-jobs'
        Paths    = @('sql\maintenance\Get-MaintenanceJobStatus.sql')
        Database = 'msdb'
    }
    [PSCustomObject]@{
        Label = 'failed-logins'
        Paths = @('sql\security\access\Get-FailedLoginSummary.sql')
    }
    [PSCustomObject]@{
        Label = 'query-store-status'
        Paths = @('sql\monitoring\features\Get-QueryStoreStatus.sql')
    }
    [PSCustomObject]@{
        Label = 'extended-events'
        Paths = @('sql\monitoring\features\Get-ExtendedEventsSessions.sql')
    }
    [PSCustomObject]@{
        Label = 'cdc-and-ct'
        Paths = @('sql\monitoring\features\Get-CdcAndChangeTracking.sql')
    }
    [PSCustomObject]@{
        Label = 'service-broker'
        Paths = @('sql\monitoring\features\Get-ServiceBrokerHealth.sql')
    }
    [PSCustomObject]@{
        Label = 'sysadmin-members'
        Paths = @('sql\security\access\Get-SysadminMembers.sql')
    }
    [PSCustomObject]@{
        Label = 'instance-config'
        Paths = @('sql\monitoring\instance\Get-InstanceConfigurationSnapshot.sql')
    }
    [PSCustomObject]@{
        Label = 'top-cpu-queries'
        Paths = @('sql\performance\queries\Get-TopCpuQueries.sql')
    }
    [PSCustomObject]@{
        Label = 'agent-jobs-overview'
        Paths = @('sql\monitoring\jobs\Get-SqlAgentJobOverview.sql')
    }
    [PSCustomObject]@{
        Label = 'orphaned-users'
        Paths = @('sql\security\access\Get-OrphanedUsers.sql')
    }
    [PSCustomObject]@{
        Label = 'certificate-expiry'
        Paths = @('sql\security\encryption\Get-CertificateExpiryWarnings.sql')
    }
    [PSCustomObject]@{
        Label = 'autogrowth-history'
        Paths = @('sql\monitoring\disk-space\Get-AutogrowthHistory.sql')
    }
    [PSCustomObject]@{
        Label = 'ag-replica-state'
        Paths = @('sql\high-availability\always-on\Get-AvailabilityGroupReplicaState.sql')
    }
    [PSCustomObject]@{
        Label = 'ag-failover-readiness'
        Paths = @('sql\high-availability\always-on\Get-AgFailoverReadiness.sql')
    }
    [PSCustomObject]@{
        Label = 'ag-latency'
        Paths = @('sql\high-availability\always-on\Get-AvailabilityGroupLatency.sql')
    }
    [PSCustomObject]@{
        Label = 'mirroring-endpoint-health'
        Paths = @('sql\high-availability\mirroring\Get-MirroringEndpointHealth.sql')
    }
    [PSCustomObject]@{
        Label = 'replication-status'
        Paths = @('sql\high-availability\replication\Get-ReplicationStatus.sql')
    }
    [PSCustomObject]@{
        Label = 'last-node-blip'
        Paths = @('sql\high-availability\fci\Get-LastNodeBlip.sql')
    }
)

# All planned scripts go into the manifest as PENDING up front, so pollers know
# the total and the full script list from the first write.
$manifest = [System.Collections.Generic.List[PSObject]]::new()
foreach ($s in $scripts) {
    $manifest.Add([PSCustomObject]@{
        Script      = $s.Label
        Status      = 'PENDING'
        Started     = ''
        Finished    = ''
        DurationSec = ''
        Note        = ''
    })
}
Write-HcManifest $manifest $outFolder

foreach ($s in $scripts) {
    $resolvedSql = $null
    foreach ($p in $s.Paths) {
        $candidate = Join-Path $repoRoot $p
        if (Test-Path -LiteralPath $candidate) {
            $resolvedSql = $candidate
            break
        }
    }

    $csvPath = Join-Path $outFolder "$($s.Label).csv"
    $status  = 'OK'
    $note    = ''
    $db      = if ($s.PSObject.Properties['Database'] -and $s.Database) { $s.Database } else { 'master' }

    $mRow = $manifest | Where-Object Script -eq $s.Label | Select-Object -First 1
    $mRow.Status  = 'RUNNING'
    $mRow.Started = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    Write-HcManifest $manifest $outFolder
    $swScript = [System.Diagnostics.Stopwatch]::StartNew()

    if (-not $resolvedSql) {
        $status = 'SKIPPED'
        $note   = 'SQL file not found'
    }
    else {
        try {
            if ($Quiet) {
                & $runner -ScriptPath $resolvedSql `
                          -ServerInstance $ServerInstance `
                          -Database $db `
                          -OutputFormat 'Csv' `
                          -OutputPath $csvPath *>$null
            }
            else {
                & $runner -ScriptPath $resolvedSql `
                          -ServerInstance $ServerInstance `
                          -Database $db `
                          -OutputFormat 'Csv' `
                          -OutputPath $csvPath
            }
        }
        catch {
            $status = 'FAILED'
            $note   = $_.Exception.Message -replace "`r?`n", ' '
        }
    }

    $swScript.Stop()
    $mRow.Status      = $status
    $mRow.Finished    = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $mRow.DurationSec = [math]::Round($swScript.Elapsed.TotalSeconds, 1)
    $mRow.Note        = $note
    Write-HcManifest $manifest $outFolder

    $color = switch ($status) {
        'OK'      { 'Green' }
        'SKIPPED' { 'Yellow' }
        default   { 'Red' }
    }
    Write-Host ("  [{0,-8}] {1}" -f $status, $s.Label) -ForegroundColor $color
    if ($status -eq 'FAILED' -and $note) {
        $shortNote = if ($note.Length -gt 140) { $note.Substring(0, 140) + '…' } else { $note }
        Write-Host "             $shortNote" -ForegroundColor DarkRed
    }
}

Write-Host ''
Write-Host '--------------------------------------------'
$ok      = @($manifest | Where-Object Status -eq 'OK').Count
$failed  = @($manifest | Where-Object Status -eq 'FAILED').Count
$skipped = @($manifest | Where-Object Status -eq 'SKIPPED').Count
Write-Host "  OK: $ok  |  Failed: $failed  |  Skipped: $skipped" -ForegroundColor Cyan
Write-Host ''

$uiUp = $false
try { $tcp = [System.Net.Sockets.TcpClient]::new('localhost', 8787); $tcp.Close(); $uiUp = $true } catch { $null = $_ }
$folderEnc  = [Uri]::EscapeDataString($outFolder)
$reviewUrl  = "http://localhost:8787/review?folder=$folderEnc"

Write-Host ('─' * 64) -ForegroundColor DarkCyan
Write-Host "  Folder  : $outFolder" -ForegroundColor Green
if ($uiUp) {
    Write-Host "  Dashboard: $reviewUrl" -ForegroundColor Cyan
} else {
    Write-Host "  Dashboard: $reviewUrl" -ForegroundColor DarkGray
    Write-Host "             (web UI not running - start with: .\web-ui\Start-WebUi.ps1)" -ForegroundColor DarkGray
}
Write-Host ''
Write-Host "  CLI review: .\powershell\reporting\Review-HealthCheckOutput.ps1" -ForegroundColor DarkGray
Write-Host ('─' * 64) -ForegroundColor DarkCyan
Write-Host ''

} finally {
    Remove-Item Env:DBASCRIPTS_BATCH -ErrorAction SilentlyContinue
}

﻿<#
.SYNOPSIS
Runs the health check collection across multiple SQL Server instances and surfaces
aggregated CRITICAL/WARNING findings across the estate.

.NOTES
ScriptType   : automation
TargetScope  : multi-server
RiskLevel    : SAFE
Purpose      : Estate-wide health check — one command to flag which servers need
               attention and why. Calls the existing per-server health check scripts
               rather than duplicating their logic.

.DESCRIPTION
For each server: runs Invoke-HealthCheckCollection.ps1 (45 scripts) then
Review-HealthCheckOutput.ps1 (17 rule categories). Aggregates findings across all
servers sorted by severity. Saves a combined findings CSV.

.PARAMETER Servers
Comma-separated SQL Server instances. Takes precedence over -ServerListFile.

.PARAMETER ServerListFile
Path to a text file with one server per line. Lines starting with # are ignored.

.PARAMETER Parallel
Run collection against all servers simultaneously (PS7+). Default: sequential.

.PARAMETER ThrottleLimit
Max concurrent collection jobs when -Parallel is used. Default: 4 (collection
is I/O heavy — more than 4 simultaneous usually doesn't help).

.EXAMPLE
.\powershell\reporting\Invoke-MultiServerHealthCheck.ps1 -Servers "SVR01,SVR02,SVR03"
.\powershell\reporting\Invoke-MultiServerHealthCheck.ps1 -ServerListFile servers.txt -Parallel
#>

[CmdletBinding()]
param(
    [string]$Servers,
    [string]$ServerListFile,
    [switch]$Parallel,
    [int]$ThrottleLimit = 4
)

$ErrorActionPreference = 'Stop'

$repoRoot    = Resolve-Path (Join-Path $PSScriptRoot '..\..')
$collectScript = Join-Path $repoRoot 'powershell\reporting\Invoke-HealthCheckCollection.ps1'
$reviewScript  = Join-Path $repoRoot 'powershell\reporting\Review-HealthCheckOutput.ps1'

if (-not (Test-Path $collectScript)) { throw "Invoke-HealthCheckCollection.ps1 not found at $collectScript" }
if (-not (Test-Path $reviewScript))  { throw "Review-HealthCheckOutput.ps1 not found at $reviewScript" }

# ---------------------------------------------------------------------------
# Build server list
# ---------------------------------------------------------------------------

$serverList = @()
if ($Servers) {
    $serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ }
}
if ($ServerListFile -and (Test-Path $ServerListFile)) {
    $fileServers = Get-Content $ServerListFile |
        Where-Object { $_ -notmatch '^\s*#' -and $_.Trim() -ne '' } |
        ForEach-Object { $_.Trim() }
    $serverList = @($serverList) + @($fileServers) | Select-Object -Unique
}
if ($serverList.Count -eq 0) {
    throw "No servers specified. Use -Servers or -ServerListFile."
}

Write-Host ''
Write-Host "  Multi-server health check - $($serverList.Count) server(s)" -ForegroundColor Cyan
Write-Host ("  " + ("─" * 56)) -ForegroundColor DarkCyan
Write-Host ''

# ---------------------------------------------------------------------------
# Run collection per server — captures the output folder path from stdout
# ---------------------------------------------------------------------------

function Invoke-CollectionForServer {
    param([string]$Server)
    $output = & pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass `
        -File $using:collectScript -ServerInstance $Server -Quiet 2>&1
    $folderLine = $output | Where-Object { $_ -match '^\s+Folder\s+:' } | Select-Object -Last 1
    if ($folderLine -match ':\s+(.+)$') {
        return $Matches[1].Trim()
    }
    return $null
}

$collectionFolders = [System.Collections.Generic.Dictionary[string,string]]::new()

if ($Parallel) {
    Write-Host "  Running parallel collection (ThrottleLimit $ThrottleLimit)..." -ForegroundColor DarkGray
    $results = $serverList | ForEach-Object -Parallel {
        $srv    = $_
        $cs     = $using:collectScript
        $output = & pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass `
            -File $cs -ServerInstance $srv -Quiet 2>&1
        $folderLine = $output | Where-Object { $_ -match '^\s+Folder\s+:' } | Select-Object -Last 1
        $folder = if ($folderLine -match ':\s+(.+)$') { $Matches[1].Trim() } else { $null }
        [PSCustomObject]@{ Server = $srv; Folder = $folder }
    } -ThrottleLimit $ThrottleLimit

    foreach ($r in $results) {
        if ($r.Folder) {
            $collectionFolders[$r.Server] = $r.Folder
            Write-Host "  [OK]  $($r.Server) → $($r.Folder)" -ForegroundColor Green
        } else {
            Write-Host "  [FAIL] $($r.Server) - collection failed or folder not found" -ForegroundColor Red
        }
    }
} else {
    foreach ($server in $serverList) {
        Write-Host "  Collecting: $server..." -ForegroundColor DarkGray -NoNewline
        try {
            $output = & pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass `
                -File $collectScript -ServerInstance $server -Quiet 2>&1
            $folderLine = $output | Where-Object { $_ -match '^\s+Folder\s+:' } | Select-Object -Last 1
            if ($folderLine -match ':\s+(.+)$') {
                $folder = $Matches[1].Trim()
                $collectionFolders[$server] = $folder
                Write-Host " OK" -ForegroundColor Green
            } else {
                Write-Host " folder not found in output" -ForegroundColor Yellow
            }
        } catch {
            Write-Host " FAILED: $($_.Exception.Message)" -ForegroundColor Red
        }
    }
}

Write-Host ''

# ---------------------------------------------------------------------------
# Run review per folder and load findings.csv
# ---------------------------------------------------------------------------

$allFindings = [System.Collections.Generic.List[PSObject]]::new()

foreach ($kv in $collectionFolders.GetEnumerator()) {
    $server = $kv.Key
    $folder = $kv.Value
    Write-Host "  Reviewing: $server..." -ForegroundColor DarkGray -NoNewline
    try {
        & pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass `
            -File $reviewScript -FolderPath $folder -OutputFormat Csv 2>&1 | Out-Null

        $findingsCsv = Join-Path $folder 'findings.csv'
        if (Test-Path $findingsCsv) {
            $rows = @(Import-Csv $findingsCsv -ErrorAction SilentlyContinue)
            foreach ($row in $rows) {
                $allFindings.Add([PSCustomObject]@{
                    Server   = $server
                    Severity = $row.Severity
                    Category = $row.Category
                    Subject  = $row.Subject
                    Detail   = $row.Detail
                })
            }
            $crit = @($rows | Where-Object { $_.Severity -eq 'CRITICAL' }).Count
            $warn = @($rows | Where-Object { $_.Severity -eq 'WARNING'  }).Count
            $info = @($rows | Where-Object { $_.Severity -eq 'INFO'     }).Count
            Write-Host " $($rows.Count) findings (CRIT:$crit WARN:$warn INFO:$info)" -ForegroundColor $(
                if ($crit -gt 0) { 'Red' } elseif ($warn -gt 0) { 'Yellow' } else { 'Green' }
            )
        } else {
            Write-Host " no findings" -ForegroundColor Green
        }
    } catch {
        Write-Host " review failed: $($_.Exception.Message)" -ForegroundColor Red
    }
}

# ---------------------------------------------------------------------------
# Aggregate summary
# ---------------------------------------------------------------------------

Write-Host ''
Write-Host ("  " + ("─" * 56)) -ForegroundColor DarkCyan
Write-Host "  Summary by server" -ForegroundColor Cyan

$serverSummary = $allFindings | Group-Object Server | ForEach-Object {
    $grp = $_.Group
    [PSCustomObject]@{
        Server   = $_.Name
        CRITICAL = @($grp | Where-Object { $_.Severity -eq 'CRITICAL' }).Count
        WARNING  = @($grp | Where-Object { $_.Severity -eq 'WARNING'  }).Count
        INFO     = @($grp | Where-Object { $_.Severity -eq 'INFO'     }).Count
        Total    = $grp.Count
    }
}
$serverSummary | Sort-Object CRITICAL -Descending | Format-Table -AutoSize

# Print CRITICAL findings across all servers
$criticals = @($allFindings | Where-Object { $_.Severity -eq 'CRITICAL' })
if ($criticals.Count -gt 0) {
    Write-Host "  CRITICAL findings" -ForegroundColor Red
    $criticals | Sort-Object Server, Category | Format-Table Server, Category, Subject, Detail -AutoSize
}

# ---------------------------------------------------------------------------
# Save aggregated CSV
# ---------------------------------------------------------------------------

if ($allFindings.Count -gt 0) {
    $outDir  = Join-Path $repoRoot 'output-files\healthcheck'
    New-Item -ItemType Directory -Path $outDir -Force | Out-Null
    $ts      = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFile = Join-Path $outDir "multi-server-$ts.csv"
    $allFindings | Sort-Object {
        @{ CRITICAL=0; WARNING=1; INFO=2 }[$_.Severity]
    }, Server, Category | Export-Csv -LiteralPath $outFile -NoTypeInformation -Encoding UTF8
    Write-Host "  Saved: $outFile" -ForegroundColor Green
}

Write-Host ''

﻿<#
.SYNOPSIS
Cross-server sp_configure drift detection — finds settings where any server differs from the majority.

.DESCRIPTION
Runs sp_configure across all servers in -ServerList and identifies settings where any server
deviates from the peer majority. Does not require a saved baseline — uses statistical peer
comparison. Useful for fleet-wide consistency audits (50+ instances).

.NOTES
ScriptType  : automation
TargetScope : multi-server
RiskLevel   : SAFE

.EXAMPLE
.\MultiServer-Compare-Configuration.ps1 -ServerList PROD01,PROD02,PROD03,PROD04

.\MultiServer-Compare-Configuration.ps1 -ServerFile .\servers.txt -OutputFormat Csv
#>

param(
    [string[]]$ServerList,
    [string]$ServerFile,
    [ValidateSet('Table', 'Csv')]
    [string]$OutputFormat = 'Table',
    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..\..')

# Resolve server list
$servers = if ($ServerList) {
    $ServerList
} elseif ($ServerFile -and (Test-Path $ServerFile)) {
    Get-Content $ServerFile | Where-Object { $_ -and $_.Trim() -notmatch '^#' } | ForEach-Object { $_.Trim() }
} else {
    throw 'Provide -ServerList or -ServerFile.'
}

Write-Host "Collecting sp_configure from $($servers.Count) server(s)..." -ForegroundColor Cyan

$configSql = @"
SELECT
    CAST(SERVERPROPERTY('ServerName') AS NVARCHAR(256)) AS server_name,
    name                                                AS setting_name,
    CAST(value_in_use AS NVARCHAR(100))                 AS running_value,
    CAST(value       AS NVARCHAR(100))                  AS configured_value,
    CASE WHEN value <> value_in_use THEN 'PENDING_RESTART' ELSE 'OK' END AS restart_state
FROM sys.configurations
ORDER BY name;
"@

$allRows = [System.Collections.Generic.List[PSCustomObject]]::new()

foreach ($srv in $servers) {
    try {
        $useModule = $null -ne (Get-Module -Name SqlServer -ListAvailable | Select-Object -First 1)
        $rows = if ($useModule) {
            Invoke-Sqlcmd -ServerInstance $srv -Query $configSql -TrustServerCertificate -ErrorAction Stop
        } else {
            & sqlcmd -S $srv -Q $configSql -s "~" -W -h -1 2>$null |
                Where-Object { $_ -match '~' } |
                ForEach-Object {
                    $parts = $_ -split '~'
                    [PSCustomObject]@{
                        server_name      = $parts[0].Trim()
                        setting_name     = $parts[1].Trim()
                        running_value    = $parts[2].Trim()
                        configured_value = $parts[3].Trim()
                        restart_state    = $parts[4].Trim()
                    }
                }
        }
        foreach ($r in $rows) { $allRows.Add($r) }
        Write-Host "  OK  $srv ($(@($rows).Count) settings)" -ForegroundColor Green
    }
    catch {
        Write-Warning "  FAIL $srv - $_"
        $allRows.Add([PSCustomObject]@{
            server_name      = $srv
            setting_name     = '(connection failed)'
            running_value    = $_.ToString()
            configured_value = ''
            restart_state    = 'ERROR'
        })
    }
}

if ($allRows.Count -eq 0) {
    Write-Warning 'No data collected.'; return
}

# Find the majority value per setting (most common value across servers)
$grouped = $allRows |
    Where-Object { $_.setting_name -ne '(connection failed)' } |
    Group-Object setting_name

$driftRows = [System.Collections.Generic.List[PSCustomObject]]::new()

foreach ($g in $grouped) {
    $settingName = $g.Name
    $values      = $g.Group

    # Majority value
    $majorityVal = $values |
        Group-Object running_value |
        Sort-Object Count -Descending |
        Select-Object -First 1 -ExpandProperty Name

    $majorityCount = ($values | Where-Object { $_.running_value -eq $majorityVal }).Count
    $totalCount    = $values.Count

    # Servers that differ
    $outliers = $values | Where-Object { $_.running_value -ne $majorityVal }
    foreach ($o in $outliers) {
        $driftRows.Add([PSCustomObject]@{
            setting_name    = $settingName
            server          = $o.server_name
            server_value    = $o.running_value
            majority_value  = $majorityVal
            majority_count  = "$majorityCount / $totalCount servers"
            restart_pending = $o.restart_state -eq 'PENDING_RESTART'
        })
    }
}

Write-Host "`nServers compared: $($servers.Count) | Settings checked: $($grouped.Count)" -ForegroundColor Cyan

if ($driftRows.Count -eq 0) {
    Write-Host 'No configuration drift detected across fleet.' -ForegroundColor Green
    return
}

Write-Host "$($driftRows.Count) setting(s) with drift:" -ForegroundColor Yellow

$results = $driftRows | Sort-Object setting_name, server

if ($OutputFormat -eq 'Csv') {
    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $outFile   = if ($OutputPath) { $OutputPath } else {
        $outDir = Join-Path $repoRoot 'output-files\reviews\reporting'
        if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
        Join-Path $outDir "MultiServer-Compare-Configuration-$timestamp.csv"
    }
    $results | Export-Csv -Path $outFile -NoTypeInformation -Encoding UTF8
    Write-Host "Output saved: $outFile" -ForegroundColor Green
} else {
    $results | Format-Table setting_name, server, server_value, majority_value, majority_count, restart_pending -AutoSize
}

﻿﻿<#
Script Name : MultiServer-GetBackupStatus
Category    : multi-server-scripts/sql
Purpose     : Check backup coverage across multiple SQL Server instances. Shows last full, diff, and log backup age with coverage status.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -Database master          Connection database. Default: master.
              -WarnFullAgeHours 25     Flag databases whose last full backup exceeds this age. Default: 25.
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
Output      : Server, database_name, recovery_model_desc, coverage_status,
              full_backup_age_hours, last_full_backup, last_diff_backup, last_log_backup
              coverage_status: OK | FULL_STALE | NO_FULL_BACKUP | NO_LOG_BACKUP
Example     : .\MultiServer-GetBackupStatus.ps1 -Servers "SVR01,SVR02,SVR03" -WarnFullAgeHours 12
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$Database = 'master',
    [int]$WarnFullAgeHours = 25,
    [switch]$SqlAuth,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host '  SqlServer module required: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Yellow
    exit 1
}
Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
$credential = if ($SqlAuth) { Get-Credential -Message "SQL credentials for: $($serverList -join ', ')" } else { $null }

$sql = @"
SELECT
    d.name                                                                          AS database_name,
    d.recovery_model_desc,
    MAX(CASE bs.type WHEN 'D' THEN bs.backup_finish_date END)                      AS last_full_backup,
    MAX(CASE bs.type WHEN 'I' THEN bs.backup_finish_date END)                      AS last_diff_backup,
    MAX(CASE bs.type WHEN 'L' THEN bs.backup_finish_date END)                      AS last_log_backup,
    CAST(DATEDIFF(MINUTE,
        MAX(CASE bs.type WHEN 'D' THEN bs.backup_finish_date END),
        GETDATE()) / 60.0 AS DECIMAL(10,1))                                        AS full_backup_age_hours,
    CASE
        WHEN MAX(CASE bs.type WHEN 'D' THEN bs.backup_finish_date END) IS NULL
            THEN 'NO_FULL_BACKUP'
        WHEN DATEDIFF(HOUR,
                MAX(CASE bs.type WHEN 'D' THEN bs.backup_finish_date END),
                GETDATE()) > $WarnFullAgeHours
            THEN 'FULL_STALE'
        WHEN d.recovery_model_desc IN ('FULL','BULK_LOGGED')
             AND MAX(CASE bs.type WHEN 'L' THEN bs.backup_finish_date END) IS NULL
            THEN 'NO_LOG_BACKUP'
        ELSE 'OK'
    END                                                                             AS coverage_status
FROM sys.databases d
LEFT JOIN msdb.dbo.backupset bs
    ON bs.database_name = d.name
   AND bs.backup_finish_date >= DATEADD(DAY, -14, GETDATE())
WHERE d.database_id > 4
  AND d.state_desc  = 'ONLINE'
GROUP BY d.name, d.recovery_model_desc
ORDER BY full_backup_age_hours DESC;
"@

function Invoke-BackupQuery([string]$server) {
    try {
        $p = @{ ServerInstance = $server; Database = $Database; Query = $sql; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
        if ($credential) { $p.Username = $credential.UserName; $p.Password = $credential.GetNetworkCredential().Password }
        $rows = Invoke-Sqlcmd @p
        if ($rows) { foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $server }} } }
    } catch {
        [PSCustomObject]@{ Server = $server; database_name = 'ERROR'; coverage_status = $_.Exception.Message }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_; $q = $using:sql; $db = $using:Database; $cr = $using:credential
        try {
            $p = @{ ServerInstance = $srv; Database = $db; Query = $q; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $rows = Invoke-Sqlcmd @p
            foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $srv }} }
        } catch {
            [PSCustomObject]@{ Server = $srv; database_name = 'ERROR'; coverage_status = $_.Message }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Invoke-BackupQuery $server)
        $issues = @($rows | Where-Object { $_.coverage_status -ne 'OK' })
        foreach ($r in $rows) { $allResults.Add($r) }
        if ($issues.Count -gt 0) {
            Write-Host "  $($issues.Count) database(s) with coverage issues:" -ForegroundColor Yellow
            $issues | Format-Table database_name, coverage_status, full_backup_age_hours, last_full_backup -AutoSize
        } else {
            Write-Host "  All $($rows.Count) database(s) OK" -ForegroundColor Green
        }
    }
}

Write-Host "`n── Full results ─────────────────────────────────────────" -ForegroundColor DarkGray
$allResults | Sort-Object Server, { [double]((@($_.full_backup_age_hours, 9999) | Where-Object { $null -ne $_ })[0]) } -Descending |
    Format-Table Server, database_name, recovery_model_desc, coverage_status, full_backup_age_hours, last_full_backup, last_log_backup -AutoSize

Write-Host "`nDone." -ForegroundColor Green

﻿﻿<#
Script Name : MultiServer-GetBlockingSessions
Category    : multi-server-scripts/sql
Purpose     : Check for active blocking sessions across multiple SQL Server instances. Zero rows means no blocking.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -Database master          Connection database. Default: master.
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
Output      : Server, session_id, blocking_session_id, wait_type, wait_sec,
              database_name, login_name, host_name, current_statement
              Zero rows returned means no active blocking on that server.
Example     : .\MultiServer-GetBlockingSessions.ps1 -Servers "SVR01,SVR02,SVR03"
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$Database = 'master',
    [switch]$SqlAuth,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host '  SqlServer module required: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Yellow
    exit 1
}
Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
$credential = if ($SqlAuth) { Get-Credential -Message "SQL credentials for: $($serverList -join ', ')" } else { $null }

$sql = @'
SELECT
    r.session_id,
    r.blocking_session_id,
    r.wait_type,
    r.wait_time / 1000.0                                    AS wait_sec,
    r.wait_resource,
    r.status,
    DB_NAME(r.database_id)                                  AS database_name,
    s.login_name,
    s.program_name,
    s.host_name,
    s.open_transaction_count,
    SUBSTRING(t.text,
        (r.statement_start_offset / 2) + 1,
        ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)
          ELSE r.statement_end_offset END - r.statement_start_offset) / 2) + 1
    )                                                       AS current_statement
FROM sys.dm_exec_requests r
JOIN sys.dm_exec_sessions s ON s.session_id = r.session_id
CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t
WHERE r.blocking_session_id > 0
   OR EXISTS (
        SELECT 1 FROM sys.dm_exec_requests r2
        WHERE r2.blocking_session_id = r.session_id
   )
ORDER BY r.blocking_session_id, r.session_id;
'@

function Invoke-BlockingQuery([string]$server) {
    try {
        $p = @{ ServerInstance = $server; Database = $Database; Query = $sql; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
        if ($credential) { $p.Username = $credential.UserName; $p.Password = $credential.GetNetworkCredential().Password }
        $rows = Invoke-Sqlcmd @p
        if ($rows) { foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $server }} } }
        else { [PSCustomObject]@{ Server = $server; session_id = '-'; blocking_session_id = '-'; wait_type = 'NO BLOCKING'; wait_sec = 0; current_statement = '' } }
    } catch {
        [PSCustomObject]@{ Server = $server; session_id = 'ERROR'; blocking_session_id = ''; wait_type = $_.Exception.Message; wait_sec = 0; current_statement = '' }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_; $q = $using:sql; $db = $using:Database; $cr = $using:credential
        try {
            $p = @{ ServerInstance = $srv; Database = $db; Query = $q; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $rows = Invoke-Sqlcmd @p
            if ($rows) { foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $srv }} } }
            else { [PSCustomObject]@{ Server = $srv; session_id = '-'; blocking_session_id = '-'; wait_type = 'NO BLOCKING'; wait_sec = 0; current_statement = '' } }
        } catch {
            [PSCustomObject]@{ Server = $srv; session_id = 'ERROR'; blocking_session_id = ''; wait_type = $_.Message; wait_sec = 0; current_statement = '' }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Invoke-BlockingQuery $server)
        foreach ($r in $rows) { $allResults.Add($r) }
        $rows | Format-Table session_id, blocking_session_id, wait_type, wait_sec, database_name, login_name, current_statement -AutoSize
    }
}

if ($Parallel -and $allResults.Count -gt 0) {
    $allResults | Sort-Object Server, { [double]((@($_.wait_sec, 0) | Where-Object { $null -ne $_ })[0]) } -Descending |
        Format-Table Server, session_id, blocking_session_id, wait_type, wait_sec, login_name, current_statement -AutoSize
}

Write-Host "`nDone." -ForegroundColor Green

﻿﻿<#
Script Name : MultiServer-GetDatabaseSizes
Category    : multi-server-scripts/sql
Purpose     : Report data and log file sizes across multiple SQL Server instances. Free space is approximate from sys.master_files.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -Database master          Connection database. Default: master.
              -MinSizeMb 0             Only return databases above this size. Default: 0 (all).
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
Output      : Server, database_name, state_desc, recovery_model_desc,
              data_size_mb, log_size_mb, total_size_mb, data_file_count, log_file_count
              Note: no free space — run Get-DatabaseSizesAndFreeSpace for per-file detail.
Example     : .\MultiServer-GetDatabaseSizes.ps1 -Servers "SVR01,SVR02" -MinSizeMb 1000
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$Database = 'master',
    [int]$MinSizeMb = 0,
    [switch]$SqlAuth,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host '  SqlServer module required: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Yellow
    exit 1
}
Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
$credential = if ($SqlAuth) { Get-Credential -Message "SQL credentials for: $($serverList -join ', ')" } else { $null }

$sql = @"
SELECT
    d.name                                                              AS database_name,
    d.state_desc,
    d.recovery_model_desc,
    CAST(SUM(CASE mf.type WHEN 0 THEN mf.size ELSE 0 END) * 8.0 / 1024
         AS DECIMAL(12,2))                                             AS data_size_mb,
    CAST(SUM(CASE mf.type WHEN 1 THEN mf.size ELSE 0 END) * 8.0 / 1024
         AS DECIMAL(12,2))                                             AS log_size_mb,
    CAST(SUM(mf.size) * 8.0 / 1024 AS DECIMAL(12,2))                 AS total_size_mb,
    COUNT(DISTINCT CASE mf.type WHEN 0 THEN mf.file_id END)           AS data_file_count,
    COUNT(DISTINCT CASE mf.type WHEN 1 THEN mf.file_id END)           AS log_file_count
FROM sys.databases d
JOIN sys.master_files mf ON mf.database_id = d.database_id
WHERE d.database_id > 4
GROUP BY d.name, d.state_desc, d.recovery_model_desc
HAVING SUM(mf.size) * 8.0 / 1024 >= $MinSizeMb
ORDER BY total_size_mb DESC;
"@

function Invoke-SizeQuery([string]$server) {
    try {
        $p = @{ ServerInstance = $server; Database = $Database; Query = $sql; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
        if ($credential) { $p.Username = $credential.UserName; $p.Password = $credential.GetNetworkCredential().Password }
        $rows = Invoke-Sqlcmd @p
        if ($rows) { foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $server }} } }
    } catch {
        [PSCustomObject]@{ Server = $server; database_name = 'ERROR'; total_size_mb = 0; Error = $_.Exception.Message }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_; $q = $using:sql; $db = $using:Database; $cr = $using:credential
        try {
            $p = @{ ServerInstance = $srv; Database = $db; Query = $q; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $rows = Invoke-Sqlcmd @p
            foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $srv }} }
        } catch {
            [PSCustomObject]@{ Server = $srv; database_name = 'ERROR'; total_size_mb = 0; Error = $_.Exception.Message }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Invoke-SizeQuery $server)
        foreach ($r in $rows) { $allResults.Add($r) }
        $rows | Format-Table database_name, state_desc, recovery_model_desc, data_size_mb, log_size_mb, total_size_mb -AutoSize
    }
}

if ($Parallel -and $allResults.Count -gt 0) {
    $allResults | Sort-Object { [double]((@($_.total_size_mb, 0) | Where-Object { $null -ne $_ })[0]) } -Descending |
        Format-Table Server, database_name, state_desc, data_size_mb, log_size_mb, total_size_mb -AutoSize
}

$grandTotal = [Math]::Round(($allResults | Measure-Object { [double]((@($_.total_size_mb, 0) | Where-Object { $null -ne $_ })[0]) } -Sum).Sum / 1024, 2)
Write-Host "`nGrand total across all servers: $grandTotal GB" -ForegroundColor Cyan
Write-Host "Done." -ForegroundColor Green

﻿﻿<#
Script Name : MultiServer-GetDiskSpace
Category    : multi-server-scripts/powershell
Purpose     : Check disk space on multiple remote hosts using CIM. Flags volumes below configurable thresholds.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : WinRM on target hosts (Get-CimInstance uses WinRM by default in PS7+).
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated hostnames or IPs.
              -WarnBelowPctFree 20     Flag volumes below this % free. Default: 20.
              -CritBelowPctFree 10     Critical below this % free. Default: 10.
              -Credential              Alternate PSCredential.
              -Parallel                Run all servers simultaneously (PS7+).
Output      : Server, Drive, Label, TotalGB, UsedGB, FreeGB, FreePct, Status
Example     : .\MultiServer-GetDiskSpace.ps1 -Servers "SVR01,SVR02,SVR03" -WarnBelowPctFree 15
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [int]$WarnBelowPctFree = 20,
    [int]$CritBelowPctFree = 10,
    [PSCredential]$Credential,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'
$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

function Get-DiskFromHost([string]$server) {
    try {
        $cimParams = @{ ClassName = 'Win32_LogicalDisk'; Filter = "DriveType=3"; ErrorAction = 'Stop' }
        if ($server -ne '.' -and $server -ne 'localhost') { $cimParams.ComputerName = $server }
        if ($Credential) { $cimParams.Credential = $Credential }

        $disks = Get-CimInstance @cimParams
        foreach ($d in $disks) {
            $totalGb = [Math]::Round($d.Size          / 1GB, 2)
            $freeGb  = [Math]::Round($d.FreeSpace      / 1GB, 2)
            $usedGb  = [Math]::Round(($d.Size - $d.FreeSpace) / 1GB, 2)
            $pctFree = if ($d.Size -gt 0) { [Math]::Round(100.0 * $d.FreeSpace / $d.Size, 1) } else { 0 }
            $status  = if ($pctFree -lt $CritBelowPctFree) { 'CRITICAL' } `
                       elseif ($pctFree -lt $WarnBelowPctFree) { 'WARNING' } `
                       else { 'OK' }
            [PSCustomObject]@{
                Server     = $server
                Drive      = $d.DeviceID
                Label      = $d.VolumeName
                TotalGB    = $totalGb
                UsedGB     = $usedGb
                FreeGB     = $freeGb
                FreePct    = $pctFree
                Status     = $status
                Error      = ''
            }
        }
    } catch {
        [PSCustomObject]@{
            Server = $server; Drive = ''; Label = ''; TotalGB = 0; UsedGB = 0;
            FreeGB = 0; FreePct = 0; Status = 'ERROR'; Error = $_.Exception.Message
        }
    }
}

$results = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv   = $_
        $wPct  = $using:WarnBelowPctFree
        $cPct  = $using:CritBelowPctFree
        $cr    = $using:Credential
        try {
            $p = @{ ClassName = 'Win32_LogicalDisk'; Filter = 'DriveType=3'; ErrorAction = 'Stop' }
            if ($srv -ne '.' -and $srv -ne 'localhost') { $p.ComputerName = $srv }
            if ($cr) { $p.Credential = $cr }
            foreach ($d in (Get-CimInstance @p)) {
                $tg = [Math]::Round($d.Size / 1GB, 2)
                $fg = [Math]::Round($d.FreeSpace / 1GB, 2)
                $ug = [Math]::Round(($d.Size - $d.FreeSpace) / 1GB, 2)
                $pf = if ($d.Size -gt 0) { [Math]::Round(100.0 * $d.FreeSpace / $d.Size, 1) } else { 0 }
                $st = if ($pf -lt $cPct) { 'CRITICAL' } elseif ($pf -lt $wPct) { 'WARNING' } else { 'OK' }
                [PSCustomObject]@{ Server = $srv; Drive = $d.DeviceID; Label = $d.VolumeName; TotalGB = $tg; UsedGB = $ug; FreeGB = $fg; FreePct = $pf; Status = $st; Error = '' }
            }
        } catch {
            [PSCustomObject]@{ Server = $srv; Drive = ''; Label = ''; TotalGB = 0; UsedGB = 0; FreeGB = 0; FreePct = 0; Status = 'ERROR'; Error = $_.Message }
        }
    } -ThrottleLimit 10 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n→ $server" -ForegroundColor Cyan
        $rows = @(Get-DiskFromHost $server)
        foreach ($r in $rows) {
            $clr = switch ($r.Status) { 'CRITICAL' { 'Red' } 'WARNING' { 'Yellow' } 'ERROR' { 'Red' } default { 'Green' } }
            Write-Host ("  [{0,-8}] {1}  {2} GB free of {3} GB ({4}%)" -f $r.Status, $r.Drive, $r.FreeGB, $r.TotalGB, $r.FreePct) -ForegroundColor $clr
            $results.Add($r)
        }
    }
}

Write-Host "`n── All volumes ──────────────────────────────────────────" -ForegroundColor DarkGray
$results | Sort-Object Server, FreePct | Format-Table Server, Drive, Label, TotalGB, UsedGB, FreeGB, FreePct, Status, Error -AutoSize

﻿﻿<#
Script Name : MultiServer-GetFirewallRules
Category    : multi-server-scripts/powershell
Purpose     : List Windows Firewall rules across multiple remote hosts via WinRM.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : WinRM on target hosts (Enable-PSRemoting -Force on each target).
              NetSecurity module (standard on Windows Server 2012+).
Params      : -Servers "SVR01,SVR02"          Required. Comma-separated hostnames or IPs.
              -DisplayNameLike "*"              Wildcard filter on rule name. Default: * (all).
              -Enabled All|True|False           Filter by enabled state. Default: All.
              -Direction Inbound|Outbound|All   Filter by direction. Default: Inbound.
              -Credential                       Alternate PSCredential.
              -Parallel                         Run all servers simultaneously (PS7+).
Output      : Server, Direction, Enabled, Action, Protocol, LocalPort, DisplayName
Example     : .\MultiServer-GetFirewallRules.ps1 -Servers "SVR01,SVR02" -DisplayNameLike "*SQL*"
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$DisplayNameLike = '*',

    [ValidateSet('True','False','All')]
    [string]$Enabled = 'All',

    [ValidateSet('Inbound','Outbound','All')]
    [string]$Direction = 'Inbound',

    [PSCredential]$Credential,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'
$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

$scriptBlock = {
    param($nameLike, $enabledFilter, $dirFilter)
    try {
        $params = @{ DisplayName = $nameLike }
        if ($enabledFilter -ne 'All') { $params.Enabled  = [bool]::Parse($enabledFilter) }
        if ($dirFilter     -ne 'All') { $params.Direction = $dirFilter }

        $rules = Get-NetFirewallRule @params -ErrorAction Stop |
            Where-Object { $_.DisplayName -ne '' }

        foreach ($r in $rules) {
            # Get port filter details where available
            $portInfo = try { $r | Get-NetFirewallPortFilter -ErrorAction SilentlyContinue } catch { $null }
            [PSCustomObject]@{
                Server      = $env:COMPUTERNAME
                DisplayName = $r.DisplayName
                Direction   = $r.Direction
                Enabled     = $r.Enabled
                Action      = $r.Action
                Protocol    = if ($portInfo) { $portInfo.Protocol } else { '' }
                LocalPort   = if ($portInfo) { $portInfo.LocalPort -join ',' } else { '' }
                Profile     = $r.Profile
                Error       = ''
            }
        }
    } catch {
        [PSCustomObject]@{
            Server = $env:COMPUTERNAME; DisplayName = ''; Direction = ''; Enabled = '';
            Action = ''; Protocol = ''; LocalPort = ''; Profile = ''; Error = $_.Exception.Message
        }
    }
}

$invokeParams = @{ ScriptBlock = $scriptBlock; ArgumentList = $DisplayNameLike, $Enabled, $Direction }
if ($Credential) { $invokeParams.Credential = $Credential }

$results = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv = $_
        $ip  = @{ ScriptBlock = $using:scriptBlock; ArgumentList = $using:DisplayNameLike, $using:Enabled, $using:Direction; ComputerName = $srv }
        if ($using:Credential) { $ip.Credential = $using:Credential }
        try   { Invoke-Command @ip }
        catch { [PSCustomObject]@{ Server = $srv; DisplayName = ''; Direction = ''; Enabled = ''; Action = ''; Protocol = ''; LocalPort = ''; Profile = ''; Error = $_.Message } }
    } -ThrottleLimit 10 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n→ $server" -ForegroundColor Cyan
        try {
            $rows = Invoke-Command -ComputerName $server @invokeParams -ErrorAction Stop
            foreach ($r in $rows) { $results.Add($r) }
            Write-Host "  $($rows.Count) rule(s) matched" -ForegroundColor DarkGray
        } catch {
            Write-Warning "$server : $_"
        }
    }
}

Write-Host "`n── All rules ────────────────────────────────────────────" -ForegroundColor DarkGray
$results | Sort-Object Server, Direction, DisplayName |
    Format-Table Server, Direction, Enabled, Action, Protocol, LocalPort, DisplayName -AutoSize

﻿﻿<#
Script Name : MultiServer-GetMaintenanceJobStatus
Category    : multi-server-scripts/sql
Purpose     : Checks whether DBA maintenance jobs (DBA - Backup - FULL, DBA - Backup - LOG,
              DBA - Index Maintenance, etc.) are deployed and have run successfully across
              multiple SQL Server instances. Use after deploying the maintenance framework
              to verify coverage and catch silent failures.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
              -OutCsv path.csv         Save full results to CSV.
              -FailedOnly              Only show jobs that failed or are missing.
Output      : server, job_name, status, last_run_status, last_run_at, last_run_duration,
              next_run_at
Example     : .\MultiServer-GetMaintenanceJobStatus.ps1 -Servers "SVR01,SVR02" -FailedOnly
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [switch]$SqlAuth,
    [switch]$Parallel,
    [switch]$FailedOnly,
    [string]$OutCsv
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host ''
    Write-Host '  The SqlServer module is required.' -ForegroundColor Yellow
    Write-Host '  Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Cyan
    Write-Host ''
    exit 1
}

Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

$credential = $null
if ($SqlAuth) {
    $credential = Get-Credential -Message "SQL Server credentials for: $($serverList -join ', ')"
}

$sql = @"
SELECT
    j.name AS job_name,
    CASE j.enabled WHEN 1 THEN 'Enabled' ELSE 'Disabled' END AS status,
    CASE h.run_status
        WHEN 0 THEN 'Failed'
        WHEN 1 THEN 'Succeeded'
        WHEN 4 THEN 'In Progress'
        ELSE        'Never run'
    END AS last_run_status,
    CASE WHEN h.run_date IS NULL THEN NULL
         ELSE msdb.dbo.agent_datetime(h.run_date, h.run_time)
    END AS last_run_at,
    CASE WHEN h.run_duration IS NULL THEN NULL
         ELSE RIGHT('0' + CAST(h.run_duration / 10000 AS varchar(4)), 2) + ':'
            + RIGHT('0' + CAST((h.run_duration % 10000) / 100 AS varchar(2)), 2) + ':'
            + RIGHT('0' + CAST(h.run_duration % 100 AS varchar(2)), 2)
    END AS last_run_duration,
    CASE WHEN sch.next_run_date = 0 THEN NULL
         ELSE msdb.dbo.agent_datetime(sch.next_run_date, sch.next_run_time)
    END AS next_run_at
FROM msdb.dbo.sysjobs j
OUTER APPLY (
    SELECT TOP 1 h.run_date, h.run_time, h.run_duration, h.run_status
    FROM msdb.dbo.sysjobhistory h
    WHERE h.job_id = j.job_id AND h.step_id = 0
    ORDER BY h.run_date DESC, h.run_time DESC
) h
OUTER APPLY (
    SELECT TOP 1 s.next_run_date, s.next_run_time
    FROM msdb.dbo.sysjobschedules js
    JOIN msdb.dbo.sysschedules s ON s.schedule_id = js.schedule_id
    WHERE js.job_id = j.job_id AND s.enabled = 1
      AND (s.next_run_date > 0 OR s.next_run_time > 0)
    ORDER BY s.next_run_date, s.next_run_time
) sch
WHERE j.name LIKE N'DBA - %'
ORDER BY j.name;
"@

$expectedJobs = @(
    'DBA - Backup - FULL'
    'DBA - Backup - LOG'
    'DBA - Backup - Cleanup'
    'DBA - Index Maintenance'
    'DBA - Statistics Update'
    'DBA - Integrity Check'
    'DBA - History Cleanup'
    'DBA - Cycle Error Log'
)

function Get-JobStatus([string]$server) {
    try {
        $params = @{
            ServerInstance         = $server
            Database               = 'msdb'
            Query                  = $sql
            TrustServerCertificate = $true
            OutputAs               = 'DataTables'
            ErrorAction            = 'Stop'
        }
        if ($credential) {
            $params.Username = $credential.UserName
            $params.Password = $credential.GetNetworkCredential().Password
        }
        $rows = @(Invoke-Sqlcmd @params)
        $found = $rows | Select-Object -ExpandProperty job_name

        # Synthesize a NOT DEPLOYED row for expected but missing jobs
        $missing = $expectedJobs | Where-Object { $_ -notin $found } | ForEach-Object {
            [PSCustomObject]@{ job_name = $_; status = 'NOT DEPLOYED'; last_run_status = 'N/A'
                               last_run_at = $null; last_run_duration = ''; next_run_at = $null }
        }

        @($rows) + @($missing) | ForEach-Object { $_ | Select-Object *, @{n='Server'; e={ $server }} }
    } catch {
        [PSCustomObject]@{
            Server = $server; job_name = 'ERROR'; status = 'ERROR'
            last_run_status = $_.Exception.Message; last_run_at = $null
            last_run_duration = ''; next_run_at = $null
        }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_; $q = $using:sql; $cr = $using:credential; $exp = $using:expectedJobs
        try {
            $p = @{ ServerInstance = $srv; Database = 'msdb'; Query = $q;
                    TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $rows = @(Invoke-Sqlcmd @p)
            $found = $rows | Select-Object -ExpandProperty job_name
            $missing = $exp | Where-Object { $_ -notin $found } | ForEach-Object {
                [PSCustomObject]@{ job_name = $_; status = 'NOT DEPLOYED'; last_run_status = 'N/A'
                                   last_run_at = $null; last_run_duration = ''; next_run_at = $null }
            }
            @($rows) + @($missing) | ForEach-Object { $_ | Select-Object *, @{n='Server'; e={ $srv }} }
        } catch {
            [PSCustomObject]@{ Server = $srv; job_name = 'ERROR'; status = 'ERROR'
                               last_run_status = $_.Message; last_run_at = $null
                               last_run_duration = ''; next_run_at = $null }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Get-JobStatus $server)
        foreach ($r in $rows) { $allResults.Add($r) }
        if ($FailedOnly) { $rows = $rows | Where-Object { $_.status -in 'NOT DEPLOYED','Disabled' -or $_.last_run_status -eq 'Failed' } }
        $rows | Format-Table job_name, status, last_run_status, last_run_at, last_run_duration -AutoSize
    }
}

if ($Parallel -and $allResults.Count -gt 0) {
    $display = if ($FailedOnly) {
        $allResults | Where-Object { $_.status -in 'NOT DEPLOYED','Disabled' -or $_.last_run_status -eq 'Failed' }
    } else { $allResults }
    Write-Host "`n── Maintenance job summary ──────────────────────────────" -ForegroundColor DarkGray
    $display | Sort-Object Server, job_name |
        Format-Table Server, job_name, status, last_run_status, last_run_at -AutoSize
}

if ($OutCsv -and $allResults.Count -gt 0) {
    $allResults | Export-Csv -Path $OutCsv -NoTypeInformation -Encoding UTF8
    Write-Host "Saved to $OutCsv" -ForegroundColor Green
}

# Summary counts
$notDeployed = @($allResults | Where-Object { $_.status -eq 'NOT DEPLOYED' }).Count
$failed      = @($allResults | Where-Object { $_.last_run_status -eq 'Failed' }).Count
$disabled    = @($allResults | Where-Object { $_.status -eq 'Disabled' }).Count
if ($notDeployed -gt 0) { Write-Host "  NOT DEPLOYED: $notDeployed job(s)" -ForegroundColor Yellow }
if ($failed      -gt 0) { Write-Host "  FAILED      : $failed job(s)" -ForegroundColor Red }
if ($disabled    -gt 0) { Write-Host "  DISABLED    : $disabled job(s)" -ForegroundColor Yellow }
Write-Host "`nDone." -ForegroundColor Green

﻿﻿<#
Script Name : MultiServer-GetPatchLevel
Category    : multi-server-scripts/sql
Purpose     : Reports SQL Server version, CU level, and edition across multiple instances.
              Use to build a patch compliance inventory across the estate.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
              -OutCsv path.csv         Save full results to CSV.
Output      : server_name, version_friendly, product_update_level, product_version,
              edition, resource_db_updated, patch_summary
              Check product_version against https://sqlserverupdates.com for latest CU.
Example     : .\MultiServer-GetPatchLevel.ps1 -Servers "SVR01,SVR02,SVR03" -Parallel
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [switch]$SqlAuth,
    [switch]$Parallel,
    [string]$OutCsv
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host ''
    Write-Host '  The SqlServer module is required.' -ForegroundColor Yellow
    Write-Host '  Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Cyan
    Write-Host ''
    exit 1
}

Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

$credential = $null
if ($SqlAuth) {
    $credential = Get-Credential -Message "SQL Server credentials for: $($serverList -join ', ')"
}

$sql = @"
DECLARE @v varchar(20) = CAST(SERVERPROPERTY('ProductVersion') AS varchar(20));
DECLARE @m int         = CAST(PARSENAME(@v, 4) AS int);
SELECT
    @@SERVERNAME AS server_name,
    @v AS product_version,
    CASE @m
        WHEN 16 THEN 'SQL Server 2022'
        WHEN 15 THEN 'SQL Server 2019'
        WHEN 14 THEN 'SQL Server 2017'
        WHEN 13 THEN 'SQL Server 2016'
        WHEN 12 THEN 'SQL Server 2014'
        WHEN 11 THEN 'SQL Server 2012'
        ELSE 'SQL Server (ver ' + CAST(@m AS varchar(5)) + ')'
    END AS version_friendly,
    CAST(SERVERPROPERTY('ProductUpdateLevel') AS varchar(20))    AS product_update_level,
    CAST(SERVERPROPERTY('ProductLevel')       AS varchar(20))    AS product_level,
    CAST(SERVERPROPERTY('ProductUpdateReference') AS varchar(30)) AS kb_reference,
    CAST(SERVERPROPERTY('Edition')            AS varchar(128))   AS edition,
    CAST(SERVERPROPERTY('ResourceLastUpdateDateTime') AS datetime) AS resource_db_updated,
    CASE @m WHEN 16 THEN 'SQL Server 2022' WHEN 15 THEN 'SQL Server 2019'
            WHEN 14 THEN 'SQL Server 2017' WHEN 13 THEN 'SQL Server 2016'
            WHEN 12 THEN 'SQL Server 2014' WHEN 11 THEN 'SQL Server 2012'
            ELSE 'SQL Server' END
    + ' ' + ISNULL(CAST(SERVERPROPERTY('ProductUpdateLevel') AS varchar(20)),
                   CAST(SERVERPROPERTY('ProductLevel') AS varchar(20)))
    + ' (' + @v + ')' AS patch_summary;
"@

function Get-PatchInfo([string]$server) {
    try {
        $params = @{
            ServerInstance         = $server
            Database               = 'master'
            Query                  = $sql
            TrustServerCertificate = $true
            OutputAs               = 'DataTables'
            ErrorAction            = 'Stop'
        }
        if ($credential) {
            $params.Username = $credential.UserName
            $params.Password = $credential.GetNetworkCredential().Password
        }
        $result = Invoke-Sqlcmd @params
        if ($result) { $result | Select-Object *, @{n='_Server'; e={ $server }} }
    } catch {
        [PSCustomObject]@{
            _Server = $server; server_name = $server; patch_summary = "ERROR: $($_.Exception.Message)"
            product_version = ''; version_friendly = ''; product_update_level = ''
            edition = ''; resource_db_updated = $null
        }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_; $q = $using:sql; $cr = $using:credential
        try {
            $p = @{ ServerInstance = $srv; Database = 'master'; Query = $q;
                    TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $r = Invoke-Sqlcmd @p
            if ($r) { $r | Select-Object *, @{n='_Server'; e={ $srv }} }
        } catch {
            [PSCustomObject]@{ _Server = $srv; server_name = $srv; patch_summary = "ERROR: $($_.Message)"
                product_version = ''; version_friendly = ''; product_update_level = ''; edition = '' }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Get-PatchInfo $server)
        foreach ($r in $rows) { $allResults.Add($r) }
        $rows | Format-Table version_friendly, product_update_level, product_version, edition -AutoSize
    }
}

if ($allResults.Count -gt 0) {
    if ($Parallel) {
        Write-Host "`n── Patch level summary (sorted by version) ──────────────" -ForegroundColor DarkGray
        $allResults | Sort-Object version_friendly, product_version |
            Format-Table _Server, version_friendly, product_update_level, product_version, edition -AutoSize
    }
    if ($OutCsv) {
        $allResults | Export-Csv -Path $OutCsv -NoTypeInformation -Encoding UTF8
        Write-Host "Saved to $OutCsv" -ForegroundColor Green
    }
}

Write-Host "`nDone. Compare product_version against https://sqlserverupdates.com for latest CU." -ForegroundColor DarkGray

﻿﻿<#
Script Name : MultiServer-GetRecentEventLogs
Category    : multi-server-scripts/powershell
Purpose     : Pull recent Error and Warning events from Windows Event Logs on multiple remote hosts.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : Remote Event Log access via RPC. RemoteRegistry service running on targets.
Params      : -Servers "SVR01,SVR02"        Required. Comma-separated hostnames or IPs.
              -LogName "Application,System"  Logs to read (comma-separated). Default: Application,System.
              -Level "Error,Warning"         Severity filter. Options: Error,Warning,Information,Critical.
              -Hours 24                      How far back to look. Default: 24.
              -MaxPerServer 50               Max events per server per log. Default: 50.
              -Credential                    Alternate PSCredential.
              -Parallel                      Run all servers simultaneously (PS7+).
Output      : Server, Log, TimeUtc, Level, Source, EventId, Message
Example     : .\MultiServer-GetRecentEventLogs.ps1 -Servers "SVR01,SVR02" -Hours 48 -Level Error
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$LogName = 'Application,System',
    [string]$Level = 'Error,Warning',
    [int]$Hours = 24,
    [int]$MaxPerServer = 50,
    [PSCredential]$Credential,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'
$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
$logNames   = $LogName -split ','  | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

# Map string level names to WinEvent level values
$levelMap = @{ Error=2; Warning=3; Information=4; Critical=1 }
$levelNums = $Level -split ',' | ForEach-Object { $_.Trim() } | ForEach-Object {
    if ($levelMap.ContainsKey($_)) { $levelMap[$_] } else { Write-Warning "Unknown level '$_' - skipping"; $null }
} | Where-Object { $null -ne $_ }

if ($levelNums.Count -eq 0) {
    Write-Error "No valid event levels specified. Use Error, Warning, Information, or Critical."
    exit 1
}

$since = (Get-Date).AddHours(-$Hours)

$results = [System.Collections.Generic.List[object]]::new()

function Get-EventsFromHost([string]$server) {
    foreach ($log in $logNames) {
        try {
            $filter = @{
                LogName   = $log
                Level     = $levelNums
                StartTime = $since
            }
            $params = @{ FilterHashtable = $filter; MaxEvents = $MaxPerServer; ErrorAction = 'Stop' }
            if ($server -ne '.') { $params.ComputerName = $server }
            if ($Credential)     { $params.Credential   = $Credential }

            $events = Get-WinEvent @params -ErrorAction SilentlyContinue
            foreach ($e in $events) {
                [PSCustomObject]@{
                    Server    = $server
                    Log       = $log
                    TimeUtc   = $e.TimeCreated.ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ss')
                    Level     = $e.LevelDisplayName
                    Source    = $e.ProviderName
                    EventId   = $e.Id
                    Message   = ($e.Message -split "`n")[0].Trim()  # first line only
                    Error     = ''
                }
            }
        } catch [System.Exception] {
            if ($_.Exception.Message -match 'No events') { continue }
            [PSCustomObject]@{
                Server = $server; Log = $log; TimeUtc = ''; Level = 'ERROR'; Source = '';
                EventId = 0; Message = $_.Exception.Message; Error = $_.Exception.Message
            }
        }
    }
}

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv   = $_
        $logs  = $using:logNames
        $lvls  = $using:levelNums
        $since = $using:since
        $max   = $using:MaxPerServer
        $cr    = $using:Credential
        foreach ($log in $logs) {
            try {
                $filter = @{ LogName = $log; Level = $lvls; StartTime = $since }
                $params = @{ FilterHashtable = $filter; MaxEvents = $max; ErrorAction = 'SilentlyContinue' }
                if ($srv -ne '.') { $params.ComputerName = $srv }
                if ($cr)          { $params.Credential   = $cr }
                $events = Get-WinEvent @params
                foreach ($e in $events) {
                    [PSCustomObject]@{ Server = $srv; Log = $log; TimeUtc = $e.TimeCreated.ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ss');
                        Level = $e.LevelDisplayName; Source = $e.ProviderName; EventId = $e.Id;
                        Message = ($e.Message -split "`n")[0].Trim(); Error = '' }
                }
            } catch {
                if ($_.Exception.Message -notmatch 'No events') {
                    [PSCustomObject]@{ Server = $srv; Log = $log; TimeUtc = ''; Level = 'ERROR'; Source = '';
                        EventId = 0; Message = $_.Exception.Message; Error = $_.Exception.Message }
                }
            }
        }
    } -ThrottleLimit 10 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n→ $server" -ForegroundColor Cyan
        $rows = @(Get-EventsFromHost $server)
        if ($rows.Count -eq 0) {
            Write-Host "  (no matching events in the last $Hours hours)" -ForegroundColor DarkGray
        } else {
            foreach ($r in $rows) {
                $clr = switch ($r.Level) { 'Error' { 'Red' } 'Critical' { 'Magenta' } 'Warning' { 'Yellow' } default { 'Gray' } }
                Write-Host ("  [{0}] {1}  {2} #{3}  {4}" -f $r.Level, $r.TimeUtc, $r.Source, $r.EventId, $r.Message.Substring(0, [Math]::Min(80, $r.Message.Length))) -ForegroundColor $clr
                $results.Add($r)
            }
        }
    }
}

if ($results.Count -gt 0) {
    Write-Host "`n── All events ───────────────────────────────────────────" -ForegroundColor DarkGray
    $results | Sort-Object Server, TimeUtc -Descending |
        Format-Table Server, Log, TimeUtc, Level, Source, EventId, Message -AutoSize
} else {
    Write-Host "`nNo matching events found on any server in the last $Hours hours." -ForegroundColor Green
}

﻿﻿<#
Script Name : MultiServer-GetServiceStatus
Category    : multi-server-scripts/powershell
Purpose     : Check Windows service status across multiple remote hosts using Get-Service over RPC.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : RPC access to target hosts (port 135). Remote host access uses RPC, not WinRM.
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated hostnames or IPs.
              -ServiceName "SQL*"      Service name filter; wildcard supported. Default: SQL*.
              -Parallel                Run all servers simultaneously (PS7+).
              Note: no -Credential — Get-Service over RPC uses pass-through auth only.
Output      : Server, ServiceName, DisplayName, Status, StartType
Example     : .\MultiServer-GetServiceStatus.ps1 -Servers "SVR01,SVR02" -ServiceName MSSQLSERVER
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$ServiceName = 'SQL*',
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'
$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

if ($serverList.Count -eq 0) {
    Write-Error "-Servers contained no valid hostnames."
    exit 1
}

$results = [System.Collections.Generic.List[object]]::new()

function Get-ServicesFromHost([string]$server) {
    try {
        $params = @{ Name = $ServiceName; ComputerName = $server; ErrorAction = 'Stop' }
        $svcs = Get-Service @params
        foreach ($s in $svcs) {
            [PSCustomObject]@{
                Server      = $server
                ServiceName = $s.Name
                DisplayName = $s.DisplayName
                Status      = $s.Status
                StartType   = $s.StartType
                Error       = ''
            }
        }
    } catch {
        [PSCustomObject]@{
            Server      = $server
            ServiceName = $ServiceName
            DisplayName = ''
            Status      = 'ERROR'
            StartType   = ''
            Error       = $_.Exception.Message
        }
    }
}

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv = $_
        $sn  = $using:ServiceName
        try {
            $params = @{ Name = $sn; ComputerName = $srv; ErrorAction = 'Stop' }
            $svcs = Get-Service @params
            foreach ($s in $svcs) {
                [PSCustomObject]@{ Server = $srv; ServiceName = $s.Name; DisplayName = $s.DisplayName; Status = $s.Status; StartType = $s.StartType; Error = '' }
            }
        } catch {
            [PSCustomObject]@{ Server = $srv; ServiceName = $sn; DisplayName = ''; Status = 'ERROR'; StartType = ''; Error = $_.Message }
        }
    } -ThrottleLimit 10 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n→ $server" -ForegroundColor Cyan
        $rows = Get-ServicesFromHost $server
        foreach ($r in $rows) {
            $clr = switch ($r.Status) { 'Running' { 'Green' } 'Stopped' { 'Yellow' } 'ERROR' { 'Red' } default { 'Gray' } }
            Write-Host ("  [{0,-8}] {1}" -f $r.Status, $r.DisplayName) -ForegroundColor $clr
            $results.Add($r)
        }
    }
}

Write-Host "`n── All results ──────────────────────────────────────────" -ForegroundColor DarkGray
$results | Sort-Object Server, ServiceName | Format-Table Server, ServiceName, Status, StartType, DisplayName, Error -AutoSize

﻿﻿<#
Script Name : MultiServer-GetWaitStats
Category    : multi-server-scripts/sql
Purpose     : Show top wait types ranked by total wait time across multiple SQL Server instances.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : SqlServer PowerShell module.
              Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated SQL Server instances.
              -Database master          Connection database. Default: master.
              -Top 10                  Wait types to show per server. Default: 10.
              -SqlAuth                  Prompt for SQL credentials instead of Windows auth.
              -Parallel                 Run all servers simultaneously (PS7+).
Output      : Server, wait_type, pct_total_wait, avg_wait_ms, max_wait_time_ms,
              wait_time_ms, waiting_tasks_count, signal_wait_time_ms, resource_wait_time_ms
Example     : .\MultiServer-GetWaitStats.ps1 -Servers "SVR01,SVR02,SVR03" -Top 5
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [string]$Database = 'master',
    [int]$Top = 10,
    [switch]$SqlAuth,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Module -Name SqlServer -ListAvailable)) {
    Write-Host ''
    Write-Host '  The SqlServer module is required.' -ForegroundColor Yellow
    Write-Host '  Install with: Install-Module -Name SqlServer -Scope CurrentUser -Force' -ForegroundColor Cyan
    Write-Host ''
    exit 1
}

Import-Module SqlServer -ErrorAction Stop

$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

$credential = $null
if ($SqlAuth) {
    $credential = Get-Credential -Message "SQL Server credentials for: $($serverList -join ', ')"
}

$sql = @"
WITH filtered_waits AS (
    SELECT
        wait_type,
        waiting_tasks_count,
        wait_time_ms,
        max_wait_time_ms,
        signal_wait_time_ms,
        wait_time_ms - signal_wait_time_ms AS resource_wait_time_ms
    FROM sys.dm_os_wait_stats
    WHERE waiting_tasks_count > 0
      AND wait_type NOT IN (
          'SLEEP_TASK','SLEEP_SYSTEMTASK','SLEEP_TEMPDBSTARTUP','SLEEP_DBSTARTUP',
          'SLEEP_DCOMSTARTUP','SLEEP_MASTERDBREADY','SLEEP_MASTERMDREADY',
          'SLEEP_MASTERUPGRADED','SLEEP_MSDBSTARTUP','SNI_HTTP_ACCEPT',
          'DISPATCHER_QUEUE_SEMAPHORE','BROKER_TO_FLUSH','BROKER_TASK_STOP',
          'BROKER_EVENTHANDLER','BROKER_RECEIVE_WAITFOR','CHECKPOINT_QUEUE',
          'DBMIRROR_EVENTS_QUEUE','DBMIRROR_WORKER_QUEUE',
          'SQLTRACE_INCREMENTAL_FLUSH_SLEEP','SQLTRACE_BUFFER_FLUSH',
          'SQLTRACE_WAIT_ENTRIES','WAITFOR','LAZYWRITER_SLEEP','LOGMGR_QUEUE',
          'ONDEMAND_TASK_QUEUE','REQUEST_FOR_DEADLOCK_SEARCH','RESOURCE_QUEUE',
          'SERVER_IDLE_CHECK','SP_SERVER_DIAGNOSTICS_SLEEP',
          'WAIT_XTP_OFFLINE_CKPT_NEW_LOG','XE_DISPATCHER_WAIT','XE_TIMER_EVENT',
          'HADR_WORK_QUEUE','HADR_FILESTREAM_IOMGR_IOCOMPLETION',
          'HADR_CLUSAPI_CALL','HADR_NOTIFICATION_DEQUEUE',
          'FT_IFTS_SCHEDULER_IDLE_WAIT','FT_IFTSHC_MUTEX',
          'REPL_WORK_QUEUE','CLR_AUTO_EVENT','CLR_MANUAL_EVENT','WAIT_XTP_COMPILE_WAIT'
      )
)
SELECT TOP $Top
    wait_type,
    waiting_tasks_count,
    wait_time_ms,
    CAST(100.0 * wait_time_ms / NULLIF(SUM(wait_time_ms) OVER (), 0) AS DECIMAL(5,2)) AS pct_total_wait,
    CAST(wait_time_ms / NULLIF(waiting_tasks_count, 0) AS DECIMAL(10,0))              AS avg_wait_ms,
    max_wait_time_ms,
    signal_wait_time_ms,
    resource_wait_time_ms
FROM filtered_waits
ORDER BY wait_time_ms DESC;
"@

function Invoke-WaitStats([string]$server) {
    try {
        $params = @{
            ServerInstance      = $server
            Database            = $Database
            Query               = $sql
            TrustServerCertificate = $true
            OutputAs            = 'DataTables'
            ErrorAction         = 'Stop'
        }
        if ($credential) {
            $params.Username = $credential.UserName
            $params.Password = $credential.GetNetworkCredential().Password
        }
        $results = Invoke-Sqlcmd @params
        if ($results) {
            foreach ($row in $results) {
                $row | Select-Object *, @{n='Server'; e={ $server }}
            }
        }
    } catch {
        [PSCustomObject]@{ Server = $server; wait_type = 'ERROR'; pct_total_wait = 0; avg_wait_ms = 0; Error = $_.Exception.Message }
    }
}

$allResults = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Querying $($serverList.Count) server(s) in parallel..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        Import-Module SqlServer -ErrorAction SilentlyContinue
        $srv = $_
        $q   = $using:sql
        $db  = $using:Database
        $cr  = $using:credential
        try {
            $p = @{ ServerInstance = $srv; Database = $db; Query = $q; TrustServerCertificate = $true; OutputAs = 'DataTables'; ErrorAction = 'Stop' }
            if ($cr) { $p.Username = $cr.UserName; $p.Password = $cr.GetNetworkCredential().Password }
            $rows = Invoke-Sqlcmd @p
            foreach ($r in $rows) { $r | Select-Object *, @{n='Server'; e={ $srv }} }
        } catch {
            [PSCustomObject]@{ Server = $srv; wait_type = 'ERROR'; pct_total_wait = 0; avg_wait_ms = 0; Error = $_.Message }
        }
    } -ThrottleLimit 10 | ForEach-Object { $allResults.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "`n=== $server ===" -ForegroundColor Cyan
        $rows = @(Invoke-WaitStats $server)
        foreach ($r in $rows) { $allResults.Add($r) }
        $rows | Format-Table wait_type, pct_total_wait, avg_wait_ms, wait_time_ms, waiting_tasks_count -AutoSize
    }
}

if ($Parallel -and $allResults.Count -gt 0) {
    Write-Host "`n── All results (sorted by server, then wait %) ──────────" -ForegroundColor DarkGray
    $allResults | Sort-Object Server, { [double]$_.pct_total_wait } -Descending |
        Format-Table Server, wait_type, pct_total_wait, avg_wait_ms, wait_time_ms -AutoSize
}

Write-Host "`nDone." -ForegroundColor Green

﻿﻿<#
Script Name : MultiServer-RestartService
Category    : multi-server-scripts/powershell
Purpose     : Restart a named Windows service on multiple remote hosts via WinRM.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : WRITE — restarts the named service on each target host
Impact      : High (causes a service interruption on each target)
Requires    : WinRM on target hosts (Enable-PSRemoting -Force as admin on each target).
              Admin rights on target hosts.
Params      : -Servers "SVR01,SVR02"   Required. Comma-separated hostnames or IPs.
              -ServiceName             Required. Short service name (MSSQLSERVER, W3SVC, etc.).
              -Credential              Alternate PSCredential for WinRM auth.
              -WhatIf                  Preview what would restart without doing it.
              -Parallel                Run all servers simultaneously (PS7+).
Output      : Server, Service, WasState, NowState, Result
Example     : .\MultiServer-RestartService.ps1 -Servers "SVR01,SVR02" -ServiceName SQLSERVERAGENT -WhatIf
#>

[CmdletBinding(SupportsShouldProcess)]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [Parameter(Mandatory)]
    [string]$ServiceName,

    [PSCredential]$Credential,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'
$serverList = $Servers -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }

if ($serverList.Count -eq 0) {
    Write-Error "-Servers contained no valid hostnames."
    exit 1
}

$scriptBlock = {
    param($svcName)
    try {
        $svc      = Get-Service -Name $svcName -ErrorAction Stop
        $prevState = $svc.Status
        Restart-Service -Name $svcName -Force -ErrorAction Stop
        $newState  = (Get-Service -Name $svcName).Status
        [PSCustomObject]@{
            Server    = $env:COMPUTERNAME
            Service   = $svcName
            WasState  = $prevState
            NowState  = $newState
            Result    = 'Restarted'
            Error     = ''
        }
    } catch {
        [PSCustomObject]@{
            Server    = $env:COMPUTERNAME
            Service   = $svcName
            WasState  = 'Unknown'
            NowState  = 'Unknown'
            Result    = 'Failed'
            Error     = $_.Exception.Message
        }
    }
}

$baseInvoke = @{ ScriptBlock = $scriptBlock; ArgumentList = $ServiceName }
if ($Credential) { $baseInvoke.Credential = $Credential }

$results = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Running in parallel against $($serverList.Count) server(s)..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv  = $_
        $ip   = @{ ScriptBlock = $using:scriptBlock; ArgumentList = $using:ServiceName; ComputerName = $srv; ErrorAction = 'Stop' }
        if ($using:Credential) { $ip.Credential = $using:Credential }
        try   { Invoke-Command @ip }
        catch { [PSCustomObject]@{ Server = $srv; Service = $using:ServiceName; WasState = ''; NowState = ''; Result = 'Failed'; Error = $_.Message } }
    } -ThrottleLimit 10 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        if (-not $PSCmdlet.ShouldProcess($server, "Restart service '$ServiceName'")) { continue }
        Write-Host "`n→ $server" -ForegroundColor Cyan
        try {
            $r = Invoke-Command -ComputerName $server @baseInvoke -ErrorAction Stop
            $results.Add($r)
            $clr = if ($r.Result -eq 'Restarted') { 'Green' } else { 'Red' }
            Write-Host ("  [{0}]  {1}  {2} → {3}" -f $r.Result, $ServiceName, $r.WasState, $r.NowState) -ForegroundColor $clr
        } catch {
            Write-Warning "$server : $_"
            $results.Add([PSCustomObject]@{ Server = $server; Service = $ServiceName; WasState = ''; NowState = ''; Result = 'Failed'; Error = $_.Message })
        }
    }
}

Write-Host "`n── Summary ──────────────────────────────────────────────" -ForegroundColor DarkGray
$results | Format-Table Server, Service, WasState, NowState, Result, Error -AutoSize

﻿﻿<#
Script Name : MultiServer-TestSqlPort
Category    : multi-server-scripts/powershell
Purpose     : Test TCP connectivity to SQL Server port 1433 (or custom port) on multiple servers. No WinRM needed.
Author      : Peter Whyte (https://sqldba.blog)
Safe        : Read-only
Impact      : Low
Requires    : Nothing — uses System.Net.Sockets.TcpClient.
Params      : -Servers "SVR01,SVR02"   Required. Hostnames, IPs, or SERVER\INSTANCE (instance part stripped).
              -Port 1433               TCP port to test. Default: 1433.
              -Timeout 1000            Connection timeout in milliseconds. Default: 1000.
              -Parallel                Run all tests simultaneously.
Output      : Server, Port, Reachable, LatencyMs, Error
Example     : .\MultiServer-TestSqlPort.ps1 -Servers "SVR01,SVR02,SVR03" -Parallel
#>

[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [string]$Servers,

    [int]$Port = 1433,
    [int]$Timeout = 1000,
    [switch]$Parallel
)

$ErrorActionPreference = 'Stop'

# Parse server list — strip instance names (SERVER\INSTANCE → SERVER)
$serverList = $Servers -split ',' | ForEach-Object {
    $s = $_.Trim()
    if ($s -match '^([^\\]+)\\') { $Matches[1] } else { $s }
} | Where-Object { $_ -ne '' } | Select-Object -Unique

if ($serverList.Count -eq 0) {
    Write-Error "-Servers contained no valid hostnames."
    exit 1
}

function Test-TcpPort([string]$server, [int]$port, [int]$timeout) {
    $client = [System.Net.Sockets.TcpClient]::new()
    try {
        $asyncResult = $client.BeginConnect($server, $port, $null, $null)
        $connected   = $asyncResult.AsyncWaitHandle.WaitOne($timeout, $false)
        if ($connected -and $client.Connected) {
            $client.EndConnect($asyncResult)
            return [PSCustomObject]@{ Server = $server; Port = $port; Reachable = $true; LatencyMs = ''; Error = '' }
        } else {
            return [PSCustomObject]@{ Server = $server; Port = $port; Reachable = $false; LatencyMs = ''; Error = 'Connection timed out' }
        }
    } catch {
        return [PSCustomObject]@{ Server = $server; Port = $port; Reachable = $false; LatencyMs = ''; Error = $_.Exception.Message }
    } finally {
        $client.Dispose()
    }
}

$results = [System.Collections.Generic.List[object]]::new()

if ($Parallel) {
    Write-Host "Testing $($serverList.Count) server(s) in parallel (port $Port, ${Timeout}ms timeout)..." -ForegroundColor Cyan
    $serverList | ForEach-Object -Parallel {
        $srv = $_
        $p   = $using:Port
        $t   = $using:Timeout
        $client = [System.Net.Sockets.TcpClient]::new()
        try {
            $ar = $client.BeginConnect($srv, $p, $null, $null)
            $ok = $ar.AsyncWaitHandle.WaitOne($t, $false)
            if ($ok -and $client.Connected) {
                $client.EndConnect($ar)
                [PSCustomObject]@{ Server = $srv; Port = $p; Reachable = $true; Error = '' }
            } else {
                [PSCustomObject]@{ Server = $srv; Port = $p; Reachable = $false; Error = 'Timed out' }
            }
        } catch {
            [PSCustomObject]@{ Server = $srv; Port = $p; Reachable = $false; Error = $_.Exception.Message }
        } finally {
            $client.Dispose()
        }
    } -ThrottleLimit 20 | ForEach-Object { $results.Add($_) }
} else {
    foreach ($server in $serverList) {
        Write-Host "  Testing $server`:$Port..." -NoNewline
        $sw  = [System.Diagnostics.Stopwatch]::StartNew()
        $r   = Test-TcpPort -server $server -port $Port -timeout $Timeout
        $sw.Stop()
        if ($r.Reachable) { $r.LatencyMs = $sw.ElapsedMilliseconds }
        $clr = if ($r.Reachable) { 'Green' } else { 'Red' }
        $msg = if ($r.Reachable) { " OPEN  ($($r.LatencyMs)ms)" } else { " CLOSED  $($r.Error)" }
        Write-Host $msg -ForegroundColor $clr
        $results.Add($r)
    }
}

$open   = @($results | Where-Object { $_.Reachable }).Count
$closed = @($results | Where-Object { -not $_.Reachable }).Count

Write-Host "`n── Summary ──────────────────────────────────────────────" -ForegroundColor DarkGray
Write-Host "  Open: $open   Closed/unreachable: $closed   Port: $Port" -ForegroundColor $(if ($closed -gt 0) { 'Yellow' } else { 'Green' })
$results | Sort-Object Reachable, Server | Format-Table Server, Port, Reachable, LatencyMs, Error -AutoSize

﻿<#
.SYNOPSIS
Reads a health-check output folder and surfaces flagged findings with severity ratings.

.NOTES
ScriptType   : PowerShell-only
TargetScope  : output-files (offline review)
RiskLevel    : SAFE
Purpose      : Turn raw CSV collection output into an actionable findings list.

.DESCRIPTION
Reads the CSV files produced by Invoke-HealthCheckCollection.ps1 and applies threshold rules
to surface issues. Each finding is rated CRITICAL, WARNING, or INFO.

Rules applied:
  CRITICAL  - database not ONLINE
  CRITICAL  - database with no full backup ever
  CRITICAL  - suspect pages recorded in msdb.dbo.suspect_pages
  CRITICAL  - sa login is enabled
  CRITICAL  - full backup older than 24 hours
  WARNING   - log backup older than 4 hours for FULL recovery databases
  WARNING   - transaction log > 80% used
  WARNING   - auto_shrink enabled on any database
  WARNING   - SQL Agent job failures in the last 7 days
  WARNING   - percent-based autogrowth configured on any file
  CRITICAL  - DBCC CHECKDB never recorded or not run in over 14 days
  WARNING   - DBCC CHECKDB not run in over 7 days
  WARNING   - read or write I/O latency > 50 ms
  WARNING   - SQL login with password policy or expiration disabled
  WARNING   - max server memory left at SQL Server default (unconfigured)
  WARNING   - data files with less than 10% free space
  WARNING   - specific wait types indicating I/O, log, or memory pressure
  WARNING   - TempDB percent-based autogrowth, unequal file sizing, or low file count
  WARNING   - high ad-hoc single-use plan ratio in plan cache (> 60%)
  WARNING   - HIGH-risk linked server login mapping (stored credentials)
  INFO      - MEDIUM-risk linked server (impersonation mapping)
  CRITICAL  - VLF count > 1000 on any database log file
  WARNING   - VLF count > 200 on any database log file
  INFO      - VLF count > 50 on any database log file
  WARNING   - DBA maintenance job missing, failed, or disabled
  CRITICAL  - login account locked out due to failed login attempts
  CRITICAL  - login with repeated failures flagged as likely brute-force
  WARNING   - login with repeated failures in error log
  WARNING   - Query Store switched to READ_ONLY (storage full or error)
  INFO      - user Extended Events sessions running
  WARNING   - CDC or Change Tracking configuration warnings
  CRITICAL/WARNING - Service Broker queue or transmission issues
  CRITICAL  - database at its configured growth limit (AT_LIMIT)
  WARNING   - database near its configured growth limit (NEAR_LIMIT)
  CRITICAL  - volume with less than 5% free space
  WARNING   - volume with less than 10% free space
  CRITICAL  - certificate expired or expiring within 30 days
  WARNING   - certificate expiring within 90 days
  WARNING   - orphaned database users (no matching server login)
  WARNING   - xp_cmdshell enabled
  CRITICAL  - error log corruption/crash patterns (823/824/825/832, stack dumps)
  WARNING   - error log memory pressure patterns (paged out, error 802/701)
  CRITICAL  - AG replica NOT_HEALTHY or DISCONNECTED
  WARNING   - AG replica PARTIALLY_HEALTHY
  CRITICAL/WARNING - AG failover readiness (database offline on replica, redo queue > 1 GB)
  CRITICAL  - mirroring/AG endpoint not STARTED
  WARNING   - replication subscription Inactive
  WARNING   - failover-related error log entries in the last 7 days
  INFO      - sessions with active blocking
  INFO      - sessions with open transactions
  INFO      - error log entries present (requires manual review)

.PARAMETER FolderPath
Path to the healthcheck output folder. If omitted, the most recent folder under
output-files\healthcheck is used.

.PARAMETER OutputFormat
'Table' (default) prints to console. 'Csv' writes findings to a CSV in the same folder.

.EXAMPLE
pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Review-HealthCheckOutput.ps1

.EXAMPLE
pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File .\powershell\reporting\Review-HealthCheckOutput.ps1 -FolderPath ".\output-files\healthcheck\.-20260529-185000"

#>

param(
    [string]$FolderPath
)

$ErrorActionPreference = 'Stop'

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')

if (-not $FolderPath) {
    $hcRoot = Join-Path $repoRoot 'output-files\healthcheck'
    if (-not (Test-Path -LiteralPath $hcRoot)) {
        throw "No FolderPath specified and no output-files\healthcheck directory found. Run Invoke-HealthCheckCollection.ps1 first."
    }
    $latest = Get-ChildItem -LiteralPath $hcRoot -Directory | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if (-not $latest) {
        throw "No healthcheck folders found under $hcRoot. Run Invoke-HealthCheckCollection.ps1 first."
    }
    $FolderPath = $latest.FullName
    Write-Host "No FolderPath specified - using most recent: $FolderPath" -ForegroundColor Yellow
}

if (-not (Test-Path -LiteralPath $FolderPath)) {
    throw "Folder not found: $FolderPath"
}

$findings = [System.Collections.Generic.List[PSObject]]::new()

function Add-Finding {
    param(
        [string]$Severity,
        [string]$Category,
        [string]$Subject,
        [string]$Detail
    )
    $findings.Add([PSCustomObject]@{
        Severity = $Severity
        Category = $Category
        Subject  = $Subject
        Detail   = $Detail
    })
}

function Read-Csv-Safe {
    param([string]$Name)
    $path = Join-Path $FolderPath "$Name.csv"
    if (Test-Path -LiteralPath $path) {
        return @(Import-Csv -LiteralPath $path -ErrorAction SilentlyContinue)
    }
    return @()
}

# ── database-health ──────────────────────────────────────────────────────────
$dbHealth = Read-Csv-Safe 'database-health'
foreach ($row in $dbHealth) {
    if ($row.state_desc -and $row.state_desc -ne 'ONLINE') {
        Add-Finding 'CRITICAL' 'Database State' $row.database_name (
            "Database is $($row.state_desc)")
    }
    if ($row.is_auto_shrink_on -in @('True', '1', 'YES')) {
        Add-Finding 'WARNING' 'Auto-Shrink' $row.database_name (
            'AUTO_SHRINK is enabled - causes fragmentation and random I/O spikes')
    }
    if ($row.is_auto_close_on -in @('True', '1', 'YES')) {
        Add-Finding 'WARNING' 'Auto-Close' $row.database_name (
            'AUTO_CLOSE is enabled - causes overhead on every new connection')
    }
}

# ── backup-times ─────────────────────────────────────────────────────────────
$backups = Read-Csv-Safe 'backup-times'
foreach ($row in $backups) {
    $dbName = $row.database_name

    if (-not $row.last_full_backup -or $row.last_full_backup -eq '') {
        Add-Finding 'CRITICAL' 'Backup' $dbName 'No full backup on record'
    }
    elseif ([double]::TryParse($row.full_backup_age_hours, [ref]$null)) {
        $ageH = [double]$row.full_backup_age_hours
        if ($ageH -gt 24) {
            Add-Finding 'CRITICAL' 'Backup' $dbName (
                "Full backup is $([Math]::Round($ageH, 1)) hours old (threshold: 24h)")
        }
    }

    $recovery = $row.recovery_model_desc
    if ($recovery -eq 'FULL' -or $recovery -eq 'BULK_LOGGED') {
        if (-not $row.last_log_backup -or $row.last_log_backup -eq '') {
            Add-Finding 'WARNING' 'Backup' $dbName (
                "$recovery recovery model but no log backup on record - log will grow unbounded")
        }
        elseif ([double]::TryParse($row.log_backup_age_hours, [ref]$null)) {
            $logAgeH = [double]$row.log_backup_age_hours
            if ($logAgeH -gt 4) {
                Add-Finding 'WARNING' 'Backup' $dbName (
                    "Log backup is $([Math]::Round($logAgeH, 1)) hours old (threshold: 4h, $recovery recovery)")
            }
        }
    }
}

# ── tlog-usage ───────────────────────────────────────────────────────────────
$tlogs = Read-Csv-Safe 'tlog-usage'
foreach ($row in $tlogs) {
    $pct = 0.0
    # Column is log_used_pct in updated script; fall back to log_used_percent for older CSVs
    $pctCol = if ($row.PSObject.Properties['log_used_pct']) { $row.log_used_pct } else { $row.log_used_percent }
    if ([double]::TryParse($pctCol, [ref]$pct) -and $pct -gt 80) {
        Add-Finding 'WARNING' 'Transaction Log' $row.database_name (
            "Log is $pct% used ($($row.log_used_mb) MB of $($row.log_size_mb) MB) - risk of log-full")
    }
}

# ── database-files (autogrowth) ───────────────────────────────────────────────
$dbFiles = Read-Csv-Safe 'database-files'
foreach ($row in $dbFiles) {
    if ($row.growth_is_percent -in @('True', '1', 'YES', 'true')) {
        Add-Finding 'WARNING' 'Autogrowth' "$($row.database_name) / $($row.logical_name)" (
            "Percent-based autogrowth ($($row.auto_growth)) on $($row.file_type) file - can cause large unpredictable growths on large databases")
    }
}

# ── job-failures ─────────────────────────────────────────────────────────────
$jobs = Read-Csv-Safe 'job-failures'
$failedJobs = $jobs | Select-Object -ExpandProperty job_name -Unique
foreach ($jName in $failedJobs) {
    $count = @($jobs | Where-Object job_name -eq $jName).Count
    Add-Finding 'WARNING' 'SQL Agent' $jName (
        "$count failure(s) in the last 7 days")
}

# ── active-sessions (blocking) ────────────────────────────────────────────────
$sessions = Read-Csv-Safe 'active-sessions'
$blocked  = @($sessions | Where-Object {
    $v = $_.blocking_session_id
    $n = 0
    $v -and $v -ne '' -and [int]::TryParse($v, [ref]$n) -and $n -gt 0
})
if ($blocked.Count -gt 0) {
    $blockedList = ($blocked | Select-Object -ExpandProperty session_id) -join ', '
    Add-Finding 'INFO' 'Blocking' 'Active sessions' (
        "$($blocked.Count) session(s) currently blocked: session_id(s) $blockedList")
}

$openTx = @($sessions | Where-Object {
    $n = 0
    [int]::TryParse($_.open_transaction_count, [ref]$n) -and $n -gt 0
})
if ($openTx.Count -gt 0) {
    Add-Finding 'INFO' 'Open Transactions' 'Active sessions' (
        "$($openTx.Count) session(s) with open transactions")
}

# ── recent-errors ─────────────────────────────────────────────────────────────
$errors = Read-Csv-Safe 'recent-errors'

# Known-severe message patterns get their own findings; everything else stays
# behind the generic INFO row below.
$errCritical = @($errors | Where-Object {
    $_.log_text -match 'Error: 82[345]|Error: 832|Stack Dump|SQL Server is terminating' })
if ($errCritical.Count -gt 0) {
    Add-Finding 'CRITICAL' 'Error Log' 'Corruption / crash indicators' (
        "$($errCritical.Count) entry/entries matching 823/824/825/832 or stack dump patterns - read recent-errors.csv now")
}
$errMemory = @($errors | Where-Object {
    $_.log_text -match 'paged out|insufficient memory|Error 802|Error: 701' })
if ($errMemory.Count -gt 0) {
    Add-Finding 'WARNING' 'Error Log' 'Memory pressure' (
        "$($errMemory.Count) entry/entries reporting working set paged out or insufficient buffer pool memory - check max server memory vs host RAM")
}

if ($errors.Count -gt 0) {
    Add-Finding 'INFO' 'Error Log' 'SQL Server error log' (
        "$($errors.Count) non-routine entry/entries in last 24h - review recent-errors.csv")
}

# ── dbcc-checkdb ──────────────────────────────────────────────────────────────
$checkdb = Read-Csv-Safe 'dbcc-checkdb'
foreach ($row in $checkdb) {
    if (-not $row.last_good_checkdb -or $row.last_good_checkdb -eq '') {
        Add-Finding 'CRITICAL' 'DBCC CHECKDB' $row.database_name (
            'No CHECKDB ever recorded - integrity of this database is unknown')
    }
    elseif ([int]::TryParse($row.days_since_checkdb, [ref]$null)) {
        $days = [int]$row.days_since_checkdb
        if ($days -gt 14) {
            Add-Finding 'CRITICAL' 'DBCC CHECKDB' $row.database_name (
                "CHECKDB overdue - $days days since last integrity check (run immediately)")
        } elseif ($days -gt 7) {
            Add-Finding 'WARNING' 'DBCC CHECKDB' $row.database_name (
                "CHECKDB stale - $days days since last integrity check (run soon)")
        }
    }
}

# ── suspect-pages ─────────────────────────────────────────────────────────────
$suspects = Read-Csv-Safe 'suspect-pages'
$activeSuspects = @($suspects | Where-Object {
    $_.event_type -notmatch 'Restored|Repaired|Deallocated'
})
if ($activeSuspects.Count -gt 0) {
    $dbNames = ($activeSuspects | Select-Object -ExpandProperty database_name -Unique) -join ', '
    Add-Finding 'CRITICAL' 'Suspect Pages' 'msdb.dbo.suspect_pages' (
        "$($activeSuspects.Count) active suspect page(s) - run DBCC CHECKDB immediately. Databases: $dbNames")
}

# ── io-usage (latency) ────────────────────────────────────────────────────────
$ioStats = Read-Csv-Safe 'io-usage'
foreach ($row in $ioStats) {
    $readLat  = 0.0
    $writeLat = 0.0
    [double]::TryParse($row.read_latency_ms,  [ref]$readLat)  | Out-Null
    [double]::TryParse($row.write_latency_ms, [ref]$writeLat) | Out-Null
    if ($readLat -gt 50) {
        Add-Finding 'WARNING' 'I/O Latency' $row.database_name (
            "Read latency is $([Math]::Round($readLat, 1)) ms (threshold: 50ms) - check disk subsystem")
    }
    if ($writeLat -gt 50) {
        Add-Finding 'WARNING' 'I/O Latency' $row.database_name (
            "Write latency is $([Math]::Round($writeLat, 1)) ms (threshold: 50ms) - check disk subsystem")
    }
}

# ── weak-logins (security) ────────────────────────────────────────────────────
$logins = Read-Csv-Safe 'weak-logins'
foreach ($login in $logins) {
    if (-not $login.risk_flag -or $login.risk_flag -eq 'OK') { continue }
    $sev = if ($login.risk_flag -eq 'SA_ENABLED') { 'CRITICAL' } else { 'WARNING' }
    Add-Finding $sev 'Security' $login.login_name (
        "Login risk flag: $($login.risk_flag)")
}

# ── wait-stats (pressure patterns) ───────────────────────────────────────────
$waits = Read-Csv-Safe 'wait-stats'
$concernWaits = @{
    'PAGEIOLATCH_SH'     = 'Data file read I/O bottleneck - disk reads are slow'
    'PAGEIOLATCH_EX'     = 'Data file write I/O bottleneck - disk writes are slow'
    'WRITELOG'           = 'Transaction log write bottleneck - check log disk or sync-commit AG'
    'RESOURCE_SEMAPHORE' = 'Memory grant pressure - queries queuing for execution memory'
    'CXPACKET'           = 'Parallelism waits - review MAXDOP and cost threshold for parallelism'
    'CXCONSUMER'         = 'Parallelism waits - review MAXDOP and cost threshold for parallelism'
    'LCK_M_X'            = 'Exclusive lock waits - blocking or high write concurrency'
    'ASYNC_NETWORK_IO'   = 'Client network waits - application not consuming results fast enough'
}
foreach ($row in $waits) {
    if ($concernWaits.ContainsKey($row.wait_type)) {
        $pct = 0.0
        if ([double]::TryParse($row.pct_total_wait, [ref]$pct) -and $pct -gt 10) {
            Add-Finding 'WARNING' 'Wait Statistics' $row.wait_type (
                "$([Math]::Round($pct,1))% of total wait time - $($concernWaits[$row.wait_type])")
        }
    }
}

# ── memory-config (unconfigured max server memory) ───────────────────────────
$memConfig = Read-Csv-Safe 'memory-config'
foreach ($row in $memConfig) {
    $maxMem = 0L
    if ([long]::TryParse($row.max_server_memory_mb, [ref]$maxMem) -and $maxMem -ge 2147483647) {
        Add-Finding 'WARNING' 'Memory Config' 'max server memory' (
            'max server memory is at the SQL Server default (2,147,483,647 MB = uncapped) - SQL Server may consume all available RAM')
    }
}

# ── database-sizes (low free space) ──────────────────────────────────────────
$dbSizes = Read-Csv-Safe 'database-sizes'
foreach ($row in $dbSizes) {
    $freePct = 0.0
    if ([double]::TryParse($row.data_free_pct, [ref]$freePct) -and $freePct -lt 10) {
        Add-Finding 'WARNING' 'Disk Space' $row.database_name (
            "Data files $freePct% free ($($row.data_free_mb) MB free of $($row.data_size_mb) MB) - autogrowth risk")
    }
}

# ── tempdb-config ─────────────────────────────────────────────────────────────
$tempdbConfig = Read-Csv-Safe 'tempdb-config'
foreach ($row in $tempdbConfig) {
    if ($row.autogrowth_status -like 'WARN*') {
        Add-Finding 'WARNING' 'TempDB Config' "TempDB / $($row.logical_name)" (
            $row.autogrowth_status)
    }
    if ($row.sizing_status -like 'WARN*') {
        Add-Finding 'WARNING' 'TempDB Config' "TempDB sizing" (
            $row.sizing_status)
    }
    if ($row.file_count_status -like 'WARN*') {
        Add-Finding 'WARNING' 'TempDB Config' "TempDB file count" (
            $row.file_count_status)
    }
}

# ── plan-cache ────────────────────────────────────────────────────────────────
$planCache = Read-Csv-Safe 'plan-cache'
foreach ($row in $planCache) {
    if ($row.recommendation -like 'WARN*') {
        $pct = if ($row.single_use_pct) { "$($row.single_use_pct)% single-use" } else { '' }
        Add-Finding 'WARNING' 'Plan Cache' $row.plan_type (
            "$($row.recommendation) - $pct ($($row.single_use_mb) MB wasted)")
    }
}

# ── linked-server-security ────────────────────────────────────────────────────
$linkedSec = Read-Csv-Safe 'linked-server-security'
$seenLs = @{}
foreach ($row in $linkedSec) {
    $key = "$($row.linked_server)|$($row.local_login)"
    if ($seenLs.ContainsKey($key)) { continue }
    $seenLs[$key] = $true
    if ($row.risk_level -like 'HIGH*') {
        Add-Finding 'WARNING' 'Linked Server' $row.linked_server (
            "Risk: $($row.risk_level) - $($row.security_context)")
    }
    elseif ($row.risk_level -like 'MEDIUM*') {
        Add-Finding 'INFO' 'Linked Server' $row.linked_server (
            "Risk: $($row.risk_level) - $($row.security_context)")
    }
}

# ── vlf-count ─────────────────────────────────────────────────────────────────
$vlfData = Read-Csv-Safe 'vlf-count'
foreach ($row in $vlfData) {
    if ($row.status -eq 'CRITICAL') {
        Add-Finding 'CRITICAL' 'VLF Count' $row.database_name (
            "VLF count $($row.vlf_count) is severe (>1000). Shrink log to near-zero then grow in one fixed-MB step.")
    } elseif ($row.status -eq 'HIGH') {
        Add-Finding 'WARNING' 'VLF Count' $row.database_name (
            "VLF count $($row.vlf_count) is high (>200). Shrink and resize the log file.")
    } elseif ($row.status -eq 'ELEVATED') {
        Add-Finding 'INFO' 'VLF Count' $row.database_name (
            "VLF count $($row.vlf_count) is elevated (>50). Monitor - resize on next maintenance window.")
    }
}

# ── maintenance-jobs ──────────────────────────────────────────────────────────
# Check file existence separately: empty file (0 DBA jobs) vs missing file (collection
# skipped/failed) need different responses. Count-based guard silently swallows the
# most important case — a fresh server with no maintenance framework deployed at all.
$maintJobsFile = Join-Path $FolderPath 'maintenance-jobs.csv'
if (Test-Path -LiteralPath $maintJobsFile) {
    $maintJobs = Read-Csv-Safe 'maintenance-jobs'
    $backupJob = $maintJobs | Where-Object { $_.job_name -like 'DBA - Backup - FULL*' }
    if (-not $backupJob) {
        Add-Finding 'WARNING' 'Maintenance Jobs' 'DBA - Backup - FULL' (
            'Full backup job not found. Run .\\powershell\\wrappers\\maintenance\\Generate-BackupJobs.ps1.')
    }
    foreach ($row in $maintJobs) {
        if ($row.last_run_status -eq 'Failed') {
            Add-Finding 'WARNING' 'Maintenance Job' $row.job_name (
                "Last run FAILED. Check SQL Agent job history for details.")
        }
        if ($row.status -eq 'Disabled') {
            Add-Finding 'WARNING' 'Maintenance Job' $row.job_name "Job is disabled - no scheduled maintenance running."
        }
    }
}

# ── failed-logins ─────────────────────────────────────────────────────────────
$failedLogins = Read-Csv-Safe 'failed-logins'
foreach ($row in $failedLogins) {
    if ($row.is_currently_locked -in @('1','True','true')) {
        Add-Finding 'CRITICAL' 'Failed Logins' $row.login_name 'Login is currently locked out'
    }
    if ($row.status -like 'CRITICAL*') {
        Add-Finding 'CRITICAL' 'Failed Logins' $row.login_name "$($row.failure_count) failures in error log - likely brute-force or app misconfiguration"
    } elseif ($row.status -like 'WARN*') {
        Add-Finding 'WARNING' 'Failed Logins' $row.login_name "$($row.failure_count) repeated failures in error log"
    }
}

# ── query-store-status ────────────────────────────────────────────────────────
$qsStatus = Read-Csv-Safe 'query-store-status'
foreach ($row in $qsStatus) {
    if ($row.qs_state -eq 'READ_ONLY' -and $row.qs_desired_state -in @('READ_WRITE','AUTO')) {
        $fp = if ($row.fill_pct -and $row.fill_pct -ne '') { " ($([Math]::Round([double]$row.fill_pct,1))% full)" } else { '' }
        Add-Finding 'WARNING' 'Query Store' $row.database_name "QS switched to READ_ONLY$fp - storage full or error; plan history is paused"
    }
}

# ── extended-events ───────────────────────────────────────────────────────────
$xeSessions = Read-Csv-Safe 'extended-events'
$sysXeNames = @('system_health','AlwaysOn_health','telemetry_xevents','hkenginexesession',
                'sp_server_diagnostics session')
$userXE     = @($xeSessions | Where-Object { $_.session_name -notin $sysXeNames })
if ($userXE.Count -gt 0) {
    Add-Finding 'INFO' 'Extended Events' "$($userXE.Count) user session(s) running" (
        ($userXE | Select-Object -ExpandProperty session_name) -join ', ')
}

# ── cdc-and-ct ────────────────────────────────────────────────────────────────
$cdcCt = Read-Csv-Safe 'cdc-and-ct'
foreach ($row in $cdcCt) {
    if ($row.status -like 'WARN*') {
        Add-Finding 'WARNING' 'CDC / Change Tracking' $row.database_name $row.status
    }
}

# ── service-broker ────────────────────────────────────────────────────────────
$svcBroker = Read-Csv-Safe 'service-broker'
foreach ($row in $svcBroker) {
    if ($row.status -like 'CRITICAL*') {
        Add-Finding 'CRITICAL' 'Service Broker' $row.database_name $row.status
    } elseif ($row.status -like 'WARN*') {
        Add-Finding 'WARNING' 'Service Broker' $row.database_name $row.status
    }
}

# ── growth-risk ───────────────────────────────────────────────────────────────
$growthRisk = Read-Csv-Safe 'growth-risk'
foreach ($row in $growthRisk) {
    if ($row.growth_status -eq 'AT_LIMIT') {
        Add-Finding 'CRITICAL' 'Growth Risk' $row.database_name (
            "Database is at its configured growth limit ($($row.total_mb) MB of $($row.growth_limit_mb) MB) - writes will fail when full")
    } elseif ($row.growth_status -eq 'NEAR_LIMIT') {
        Add-Finding 'WARNING' 'Growth Risk' $row.database_name (
            "Database is near its configured growth limit ($($row.total_mb) MB of $($row.growth_limit_mb) MB)")
    }
}

# ── disk-space (volume free space) ────────────────────────────────────────────
$volumes = Read-Csv-Safe 'disk-space'
foreach ($row in $volumes) {
    $freePct = 0.0
    if (-not [double]::TryParse($row.free_pct, [ref]$freePct)) { continue }
    if ($freePct -lt 5) {
        Add-Finding 'CRITICAL' 'Disk Space' $row.volume_mount_point (
            "Volume has $freePct% free ($($row.free_gb) GB of $($row.total_gb) GB) - SQL files on this volume can run out of space")
    } elseif ($freePct -lt 10) {
        Add-Finding 'WARNING' 'Disk Space' $row.volume_mount_point (
            "Volume has $freePct% free ($($row.free_gb) GB of $($row.total_gb) GB)")
    }
}

# ── certificate-expiry ────────────────────────────────────────────────────────
$certs = Read-Csv-Safe 'certificate-expiry'
foreach ($row in $certs) {
    if ($row.expiry_status -eq 'EXPIRED') {
        Add-Finding 'CRITICAL' 'Certificates' "$($row.cert_scope) / $($row.cert_name)" (
            "Certificate EXPIRED on $($row.expiry_date)")
    } elseif ($row.expiry_status -eq 'CRITICAL') {
        Add-Finding 'CRITICAL' 'Certificates' "$($row.cert_scope) / $($row.cert_name)" (
            "Certificate expires in $($row.days_until_expiry) days")
    } elseif ($row.expiry_status -eq 'WARNING') {
        Add-Finding 'WARNING' 'Certificates' "$($row.cert_scope) / $($row.cert_name)" (
            "Certificate expires in $($row.days_until_expiry) days")
    }
}

# ── orphaned-users ────────────────────────────────────────────────────────────
$orphans = Read-Csv-Safe 'orphaned-users'
foreach ($row in $orphans) {
    if (-not $row.user_name) { continue }
    Add-Finding 'WARNING' 'Orphaned Users' "$($row.database_name) / $($row.user_name)" (
        "Database user has no matching server login - remap or drop (see Fix-OrphanedUsers)")
}

# ── security-surface-area ─────────────────────────────────────────────────────
$surface = Read-Csv-Safe 'security-surface-area'
foreach ($row in $surface) {
    if ($row.name -eq 'xp_cmdshell' -and $row.running_value -in @('1','True')) {
        Add-Finding 'WARNING' 'Security' 'xp_cmdshell' (
            'xp_cmdshell is enabled - OS command execution from T-SQL; disable unless a documented process depends on it')
    }
}

# ── ag-replica-state ──────────────────────────────────────────────────────────
# HA CSVs contain a single status row when the feature is not configured —
# only apply rules when the real columns are present.
$agReplicas = Read-Csv-Safe 'ag-replica-state'
foreach ($row in $agReplicas) {
    if (-not $row.PSObject.Properties['synchronization_health_desc']) { break }
    if ($row.synchronization_health_desc -eq 'NOT_HEALTHY') {
        Add-Finding 'CRITICAL' 'Availability Group' "$($row.ag_name) / $($row.replica_server_name)" (
            "Replica synchronization health is NOT_HEALTHY (state: $($row.operational_state_desc))")
    } elseif ($row.synchronization_health_desc -eq 'PARTIALLY_HEALTHY') {
        Add-Finding 'WARNING' 'Availability Group' "$($row.ag_name) / $($row.replica_server_name)" (
            'Replica synchronization health is PARTIALLY_HEALTHY')
    }
    if ($row.connected_state_desc -eq 'DISCONNECTED') {
        Add-Finding 'CRITICAL' 'Availability Group' "$($row.ag_name) / $($row.replica_server_name)" (
            "Replica is DISCONNECTED (last error: $($row.last_connect_error_description))")
    }
}

# ── ag-failover-readiness ─────────────────────────────────────────────────────
$agReadiness = Read-Csv-Safe 'ag-failover-readiness'
foreach ($row in $agReadiness) {
    if (-not $row.PSObject.Properties['readiness_status']) { break }
    if ($row.readiness_status -like 'CRITICAL*') {
        Add-Finding 'CRITICAL' 'AG Failover Readiness' "$($row.ag_name) / $($row.database_name)" $row.readiness_status
    } elseif ($row.readiness_status -like 'WARN*') {
        Add-Finding 'WARNING' 'AG Failover Readiness' "$($row.ag_name) / $($row.database_name)" $row.readiness_status
    }
}

# ── mirroring-endpoint-health ─────────────────────────────────────────────────
$mirrorEndpoints = Read-Csv-Safe 'mirroring-endpoint-health'
foreach ($row in $mirrorEndpoints) {
    if (-not $row.PSObject.Properties['endpoint_state']) { break }
    if ($row.endpoint_state -and $row.endpoint_state -ne 'STARTED') {
        Add-Finding 'CRITICAL' 'Mirroring Endpoint' $row.endpoint_name (
            "Endpoint state is $($row.endpoint_state) - mirroring/AG traffic cannot flow until it is STARTED")
    }
}

# ── replication-status ────────────────────────────────────────────────────────
$replication = Read-Csv-Safe 'replication-status'
foreach ($row in $replication) {
    if (-not $row.PSObject.Properties['subscription_status']) { break }
    if ($row.subscription_status -eq 'Inactive') {
        Add-Finding 'WARNING' 'Replication' "$($row.publication_name) → $($row.subscriber_server)" (
            "Subscription to $($row.subscriber_database) is Inactive")
    }
}

# ── last-node-blip ────────────────────────────────────────────────────────────
$nodeBlips = Read-Csv-Safe 'last-node-blip'
$recentBlips = @($nodeBlips | Where-Object {
    $t = [datetime]::MinValue
    $_.PSObject.Properties['event_time'] -and $_.event_time -and
    [datetime]::TryParse($_.event_time, [ref]$t) -and $t -gt (Get-Date).AddDays(-7)
})
if ($recentBlips.Count -gt 0) {
    Add-Finding 'WARNING' 'Failover Cluster' 'Error log failover entries' (
        "$($recentBlips.Count) failover-related error log entry/entries in the last 7 days - review last-node-blip.csv")
}

# ── Output ───────────────────────────────────────────────────────────────────

Write-Host ''
Write-Host '============================================' -ForegroundColor Cyan
Write-Host '  DBA Health Check Review' -ForegroundColor Cyan
Write-Host '============================================' -ForegroundColor Cyan
Write-Host "  Folder    : $FolderPath"
$folderLeaf = Split-Path -Leaf $FolderPath
if ($folderLeaf -match '(\d{8}-\d{6})$') {
    $collectedAt = [DateTime]::ParseExact($Matches[1], 'yyyyMMdd-HHmmss', $null)
    Write-Host "  Collected : $($collectedAt.ToString('yyyy-MM-dd HH:mm:ss'))"
}
Write-Host "  Reviewed  : $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
Write-Host '--------------------------------------------'

if ($findings.Count -eq 0) {
    Write-Host ''
    Write-Host '  No findings. All checked thresholds look healthy.' -ForegroundColor Green
    Write-Host ''
}
else {
    $order = @{ CRITICAL = 0; WARNING = 1; INFO = 2 }
    $sorted = $findings | Sort-Object { $order[$_.Severity] }, Category, Subject

    Write-Host ''
    foreach ($f in $sorted) {
        $color = switch ($f.Severity) {
            'CRITICAL' { 'Red' }
            'WARNING'  { 'Yellow' }
            default    { 'Cyan' }
        }
        Write-Host ("  [{0,-8}] {1,-22} {2}" -f $f.Severity, $f.Category, $f.Subject) -ForegroundColor $color
        Write-Host ("             {0}" -f $f.Detail) -ForegroundColor DarkGray
        Write-Host ''
    }

    $critCount = @($findings | Where-Object Severity -eq 'CRITICAL').Count
    $warnCount = @($findings | Where-Object Severity -eq 'WARNING').Count
    $infoCount = @($findings | Where-Object Severity -eq 'INFO').Count
    Write-Host '--------------------------------------------'
    Write-Host ("  CRITICAL: {0}  |  WARNING: {1}  |  INFO: {2}" -f $critCount, $warnCount, $infoCount) -ForegroundColor Cyan
    Write-Host ''

    $csvOut = Join-Path $FolderPath 'findings.csv'
    $sorted | Export-Csv -LiteralPath $csvOut -NoTypeInformation -Encoding UTF8
}

$uiUp = $false
try { $tcp = [System.Net.Sockets.TcpClient]::new('localhost', 8787); $tcp.Close(); $uiUp = $true } catch { $null = $_ }
$folderEnc   = [Uri]::EscapeDataString($FolderPath)
$dashboardUrl = "http://localhost:8787/review?folder=$folderEnc"

Write-Host ('─' * 64) -ForegroundColor DarkCyan
if ($findings.Count -gt 0) {
    Write-Host "  Findings : $(Join-Path $FolderPath 'findings.csv')" -ForegroundColor Green
}
if ($uiUp) {
    Write-Host "  Dashboard: $dashboardUrl" -ForegroundColor Cyan
} else {
    Write-Host "  Dashboard: $dashboardUrl" -ForegroundColor DarkGray
    Write-Host "             (web UI not running - start with: .\web-ui\Start-WebUi.ps1)" -ForegroundColor DarkGray
}
Write-Host ('─' * 64) -ForegroundColor DarkCyan
Write-Host ''
